// Keyboard handling for bottom sheets inside Modals.
//
// The app is edge-to-edge, so a Modal's window is never resized for the
// keyboard — the keyboard simply covers the bottom of the sheet. These pieces
// give every sheet the same behaviour as the Signup form:
//   • KeyboardSheetOverlay lifts the sheet to sit right above the keyboard and
//     keeps it below the status bar (the sheet must allow `flexShrink: 1`);
//   • the sheet's header/footer stay fixed while KeyboardSheetScroll holds the
//     fields and scrolls the focused input into view;
//   • useSheetBottomPadding(base) adds the navigation-bar inset only while the
//     keyboard is closed (when open, the sheet already sits above it).
import React, {
  createContext,
  forwardRef,
  useCallback,
  useContext,
  useEffect,
  useImperativeHandle,
  useRef,
  useState,
} from 'react';
import { Keyboard, Platform, ScrollView, TextInput, View, useWindowDimensions } from 'react-native';
import { MAX_SHEET_WIDTH } from '../../utils/responsiveLayout';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

const FOCUSED_INPUT_GAP = 16;

const KeyboardSheetContext = createContext({ overlap: 0 });

// How much of a full-screen view the keyboard covers. Measured against the
// view's own height, so it is ~0 on devices that do resize the window.
export function useKeyboardOverlap() {
  const [overlap, setOverlap] = useState(0);
  const heightRef = useRef(0);

  useEffect(() => {
    const showEvent = Platform.OS === 'ios' ? 'keyboardWillShow' : 'keyboardDidShow';
    const hideEvent = Platform.OS === 'ios' ? 'keyboardWillHide' : 'keyboardDidHide';
    const showSub = Keyboard.addListener(showEvent, (e) => {
      const keyboardTop = e?.endCoordinates?.screenY;
      const height = heightRef.current;
      setOverlap(
        height && keyboardTop
          ? Math.max(0, height - keyboardTop)
          : e?.endCoordinates?.height || 0,
      );
    });
    const hideSub = Keyboard.addListener(hideEvent, () => setOverlap(0));
    return () => {
      showSub.remove();
      hideSub.remove();
    };
  }, []);

  const onLayout = useCallback((e) => {
    heightRef.current = e.nativeEvent.layout.height;
  }, []);

  return { overlap, onLayout };
}

// Bottom padding for a sheet: `base` plus the navigation bar, but only while
// the keyboard is closed.
export function useSheetBottomPadding(base = 16) {
  const insets = useSafeAreaInsets();
  const { overlap } = useContext(KeyboardSheetContext);
  return base + (overlap > 0 ? 0 : insets.bottom);
}

// The sheet panel itself: shrinks to the space above the keyboard and pads its
// bottom by `bottomPadding` (+ the navigation bar while the keyboard is closed).
export function KeyboardSheet({ style, bottomPadding = 16, children, ...rest }) {
  const paddingBottom = useSheetBottomPadding(bottomPadding);
  const { width } = useWindowDimensions();
  return (
    <View {...rest} style={[style, { flexShrink: 1, paddingBottom, width: '100%', maxWidth: width >= 600 ? MAX_SHEET_WIDTH : undefined, alignSelf: 'center' }]}>
      {children}
    </View>
  );
}

// Replaces the sheet's dim overlay View. Pass the existing overlay style
// (flex: 1, justifyContent: 'flex-end', backdrop colour).
export function KeyboardSheetOverlay({ style, children, topGap = 12, ...rest }) {
  const insets = useSafeAreaInsets();
  const { overlap, onLayout } = useKeyboardOverlap();

  return (
    <KeyboardSheetContext.Provider value={{ overlap }}>
      <View
        {...rest}
        style={[style, { paddingTop: insets.top + topGap, paddingBottom: overlap }]}
        onLayout={onLayout}
      >
        {children}
      </View>
    </KeyboardSheetContext.Provider>
  );
}

// ScrollView for a sheet's fields. Scrolls the focused input into view once
// the keyboard has opened and the sheet has shrunk to fit above it.
export const KeyboardSheetScroll = forwardRef(function KeyboardSheetScroll(
  { children, onScroll, onLayout, ...props },
  ref,
) {
  const scrollRef = useRef(null);
  const contentRef = useRef(null);
  const scrollYRef = useRef(0);
  const viewportRef = useRef(0);
  const timerRef = useRef(null);
  const { overlap } = useContext(KeyboardSheetContext);

  useImperativeHandle(ref, () => scrollRef.current);

  const scrollFocusedIntoView = useCallback(() => {
    const input = TextInput.State?.currentlyFocusedInput?.();
    const content = contentRef.current;
    if (!input || !content || !input.measureLayout) return;
    input.measureLayout(
      content,
      (_x, y, _w, h) => {
        const viewport = viewportRef.current;
        const current = scrollYRef.current;
        let next = current;
        if (y + h + FOCUSED_INPUT_GAP > current + viewport) {
          next = y + h + FOCUSED_INPUT_GAP - viewport;
        } else if (y - FOCUSED_INPUT_GAP < current) {
          next = Math.max(0, y - FOCUSED_INPUT_GAP);
        }
        if (Math.abs(next - current) > 2) {
          scrollRef.current?.scrollTo({ y: next, animated: true });
        }
      },
      () => {}, // focused input is not inside this sheet
    );
  }, []);

  const schedule = useCallback((delay = 120) => {
    clearTimeout(timerRef.current);
    timerRef.current = setTimeout(scrollFocusedIntoView, delay);
  }, [scrollFocusedIntoView]);

  useEffect(() => {
    if (overlap > 0) schedule();
  }, [overlap, schedule]);

  useEffect(() => () => clearTimeout(timerRef.current), []);

  return (
    <ScrollView
      keyboardShouldPersistTaps="handled"
      {...props}
      ref={scrollRef}
      scrollEventThrottle={16}
      onScroll={(e) => {
        scrollYRef.current = e.nativeEvent.contentOffset.y;
        onScroll?.(e);
      }}
      onLayout={(e) => {
        viewportRef.current = e.nativeEvent.layout.height;
        if (overlap > 0) schedule(60);
        onLayout?.(e);
      }}
    >
      <View
        ref={contentRef}
        collapsable={false}
        // Focus moved to another field while the keyboard stays open.
        onFocusCapture={overlap > 0 ? () => schedule(60) : undefined}
      >
        {children}
      </View>
    </ScrollView>
  );
});

import React, { useState, useCallback, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import Ionicons from 'react-native-vector-icons/Ionicons';
import {
  View,
  TouchableOpacity,
  Modal,
  FlatList,
  StyleSheet,
  Animated,
} from 'react-native';
import TextInput from '../TranslatedTextInput';
import Text from '../TranslatedText';
import AsyncStorage from '@react-native-async-storage/async-storage';
import i18n, { LANGUAGES, saveUserLanguage, LANG_STORAGE_KEY, PENDING_ACCOUNT_LANG_KEY } from '../../i18n';
import { useLanguageContext } from '../../contexts/LanguageContext';
import useLanguageRender from '../../hooks/useLanguageRender';


const LANG_ACCENT = {
  en: '#3B82F6',
  hi: '#F97316',
  mr: '#8B5CF6',
  ta: '#10B981',
  pa: '#F59E0B',
  bn: '#EC4899',
  gu: '#06B6D4',
  kn: '#EF4444',
  ml: '#6366F1',
  te: '#0EA5E9',
  ur: '#14B8A6',
};

// `brand` (optional): when set, the whole sheet uses this single accent instead
// of the per-language rainbow — used by the patient/user side (green palette).
export default function LanguageSelector({ iconColor, iconSize, userId, role, iconName, brand, triggerStyle, children }) {
  // Blend the brand toward white so the soft fills always belong to whatever
  // accent was passed in - previously these were hardcoded green.
  const mixWithWhite = (hex, amount) => {
    const m = /^#?([0-9a-f]{6})$/i.exec(String(hex || ''));
    if (!m) return null;
    const n = parseInt(m[1], 16);
    const blend = (c) => Math.round(c + (255 - c) * amount);
    const r = blend((n >> 16) & 255);
    const g = blend((n >> 8) & 255);
    const b = blend(n & 255);
    return `rgb(${r}, ${g}, ${b})`;
  };
  const brandSoft = (brand && mixWithWhite(brand, 0.88)) || '#EFF6FF';
  const brandFaint = (brand && mixWithWhite(brand, 0.95)) || '#F8FAFF';
  const { i18n } = useTranslation();
  const { t } = useLanguageRender();
  const { language: contextLang, setLanguage: setContextLanguage } = useLanguageContext();
  const [visible, setVisible] = useState(false);
  const [scale] = useState(new Animated.Value(0.88));
  const [opacity] = useState(new Animated.Value(0));
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedLang, setSelectedLang] = useState(i18n.language || 'en-US');

  // Use context language, which is always in sync
  const currentLang = contextLang || selectedLang || 'en-US';

  const filteredLanguages = useMemo(() => {
    const query = searchQuery.trim().toLowerCase();
    if (!query) return LANGUAGES;

    return LANGUAGES.filter(lang =>
      [lang.label, lang.name, lang.code]
        .join(' ')
        .toLowerCase()
        .includes(query),
    );
  }, [searchQuery]);

  const open = useCallback(() => {
    setVisible(true);
    Animated.parallel([
      Animated.spring(scale, { toValue: 1, useNativeDriver: true, tension: 140, friction: 8 }),
      Animated.timing(opacity, { toValue: 1, duration: 180, useNativeDriver: true }),
    ]).start();
  }, [scale, opacity]);

  const close = useCallback(() => {
    Animated.parallel([
      Animated.timing(scale, { toValue: 0.88, duration: 150, useNativeDriver: true }),
      Animated.timing(opacity, { toValue: 0, duration: 150, useNativeDriver: true }),
    ]).start(() => {
      setVisible(false);
      setSearchQuery('');
    });
  }, [scale, opacity]);

  const selectLanguage = useCallback(
    async (code) => {
      if (code === currentLang) {
        close();
        return;
      }
      try {
        console.log(`[LanguageSelector] 🌐 Changing language to: ${code}`);

        // Use the context's setLanguage for persistence and i18n change
        // This handles both the state update and storage
        await setContextLanguage(code);

        // Add small delay to ensure state updates propagate
        await new Promise(resolve => setTimeout(resolve, 100));

        // Also save user-specific language if userId and role are available
        if (userId && role) {
          console.log(`[LanguageSelector] Saving user-specific language: ${code}`);
          await saveUserLanguage(userId, role, code);
        } else {
          // Picked before sign-in: the account adopts it on its first dashboard load.
          await AsyncStorage.setItem(PENDING_ACCOUNT_LANG_KEY, code);
        }

        console.log(`[LanguageSelector] ✅ Language changed successfully to: ${code}`);
        setSelectedLang(code);
        close();
      } catch (error) {
        console.error('[LanguageSelector] ❌ Failed to change language:', error);
        // Revert on error
        setSelectedLang(currentLang);
      }
    },
    [currentLang, close, userId, role, setContextLanguage]
  );

  const renderItem = ({ item, index }) => {
    const isActive = item.code === currentLang;
    const accent = brand || LANG_ACCENT[item.code] || '#3B82F6';
    const initial = item.name?.charAt(0) || item.label?.charAt(0) || '?';

    return (
      <TouchableOpacity
        style={[
          styles.langRow,
          isActive && styles.langRowActive,
          isActive && brand && { backgroundColor: brandFaint },
        ]}
        onPress={() => selectLanguage(item.code)}
        activeOpacity={0.65}
      >
        {isActive && <View style={[styles.activeBar, { backgroundColor: accent }]} />}

        {/* Language names are never translated: each language shows in its own
            script ("English", "हिंदी") with the English name under it, so the
            list reads the same in every app language — "English" never turns
            into "अंग्रेज़ी". */}
        <View style={[styles.langBadge, { backgroundColor: accent + '20', borderColor: accent + '40' }]}>
          <Text translate={false} style={[styles.langBadgeText, { color: accent }]}>{initial}</Text>
        </View>

        <View style={styles.langLabels}>
          <Text translate={false} style={[styles.langNative, isActive && { color: accent }]}>{item.name || item.label}</Text>
          {!!item.label && item.label !== item.name && (
            <Text translate={false} style={styles.langEnglish}>{item.label}</Text>
          )}
        </View>

        {isActive ? (
          <View style={[styles.checkCircle, { backgroundColor: accent }]}>
            <Text style={styles.checkMark}>✓</Text>
          </View>
        ) : (
          <View style={styles.checkCircleEmpty} />
        )}
      </TouchableOpacity>
    );
  };

  return (
    <>
      <TouchableOpacity
        onPress={open}
        style={triggerStyle || styles.trigger}
        activeOpacity={0.7}
        hitSlop={children ? undefined : { top: 10, bottom: 10, left: 10, right: 10 }}
      >
        {children ? (
          children
        ) : iconName ? (
          <Ionicons name={iconName} size={iconSize || 22} color={iconColor || '#111827'} />
        ) : (
          <Text style={{ fontSize: iconSize || 22, lineHeight: (iconSize || 22) + 2 }}>🌐</Text>
        )}
      </TouchableOpacity>

      <Modal visible={visible} transparent animationType="none" onRequestClose={close} statusBarTranslucent>
        <TouchableOpacity style={styles.backdrop} activeOpacity={1} onPress={close} />

        <Animated.View style={[styles.sheet, { transform: [{ scale }], opacity }]}>
          {/* Header */}
          <View style={[styles.header, brand && { backgroundColor: brandFaint }]}>
            <View style={styles.headerLeft}>
              <View style={[styles.headerIconWrap, brand && { backgroundColor: brandSoft }]}>
                {brand ? (
                  <Ionicons name="globe-outline" size={20} color={brand} />
                ) : (
                  <Text style={styles.headerIcon}>🌐</Text>
                )}
              </View>
              <View>
                <Text style={styles.headerTitle}>{t('language:selectLanguage')}</Text>
                <Text style={styles.headerSub}>Choose your preferred language</Text>
              </View>
            </View>
            <TouchableOpacity onPress={close} style={styles.closeBtn} hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}>
              <Text style={styles.closeBtnText}>✕</Text>
            </TouchableOpacity>
          </View>

          {/* Divider */}
          <View style={styles.divider} />

          {/* Search Box */}
          <View style={styles.searchSection}>
            <View style={styles.searchContainer}>
              <View style={[styles.searchIconWrap, brand && { backgroundColor: brandSoft }]}>
                <Ionicons name="search-outline" size={18} color={brand || '#2563EB'} />
              </View>
              <TextInput
                style={styles.searchInput}
                placeholder={t('search language') || 'Search languages...'}
                placeholderTextColor="#94A3B8"
                value={searchQuery}
                onChangeText={setSearchQuery}
              />
              {searchQuery ? (
                <TouchableOpacity
                  style={styles.clearButton}
                  onPress={() => setSearchQuery('')}
                  hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
                >
                  <Ionicons name="close-circle" size={18} color="#94A3B8" />
                </TouchableOpacity>
              ) : null}
            </View>
          </View>

          {filteredLanguages.length > 0 ? (
            <FlatList
              data={filteredLanguages}
              keyExtractor={(item) => item.code}
              renderItem={renderItem}
              showsVerticalScrollIndicator={true}
              scrollIndicatorInsets={{ right: 2 }}
              bounces={false}
              nestedScrollEnabled={true}
              style={styles.list}
              scrollEnabled={true}
            />
          ) : (
            <View style={styles.emptyContainer}>
