        <View style={s.profileChips}>
          <View style={s.activeChip}>
            <View style={s.activeDot} />
            <Text style={s.activeChipText}>Your care team</Text>
          </View>
          <View style={s.shiftChip}>
            <Ionicons name="business-outline" size={13} color="#0369A1" />
