  assignmentUnassigned: { color: REC.muted, fontWeight: '400' },
});

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import {
  View,
  TouchableOpacity,
  StyleSheet,
  Animated,
  useWindowDimensions,
  StatusBar,
  Vibration,
  Platform,
  Alert,
  Modal,
  ScrollView,
  Linking,
  BackHandler,
  ActivityIndicator,
} from 'react-native';
import Text from '../../components/TranslatedText';

// India's national mental-health helpline (Tele-MANAS). Change to your own
// support line or a local crisis number as needed.
const CRISIS_HELPLINE = '14416';
const SUPPORT_EMAIL = 'support@humaeli.com';
import { isBiometricAvailable, authenticateWithBiometrics } from '../../utils/biometrics';
import { SafeAreaView, useSafeAreaInsets } from 'react-native-safe-area-context';
import LinearGradient from 'react-native-linear-gradient';
import Ionicons from 'react-native-vector-icons/Ionicons';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { PATIENT } from '../../theme/palette';
import { getStoredThemeRole, paletteForRole } from '../../theme/rolePalette';
import AuthBackground from '../../theme/AuthBackground';
import useLanguageRender from '../../hooks/useLanguageRender';

const PIN_LENGTH = 4;
export const PIN_STORAGE_KEY = 'appLockPin';
export const BIOMETRIC_LOCK_STORAGE_KEY = 'appLockBiometricEnabled';

const getBiometryLabel = (type) => {
  if (type === 'FaceID') return 'Face ID';
  if (type === 'TouchID') return 'Touch ID';
  return 'Fingerprint';
};

// ─── Keypad layout ────────────────────────────────────────────────────────────
const KEYPAD = [
  [{ n: '1', s: '' },   { n: '2', s: 'ABC' },  { n: '3', s: 'DEF' }],
  [{ n: '4', s: 'GHI' },{ n: '5', s: 'JKL' },  { n: '6', s: 'MNO' }],
  [{ n: '7', s: 'PQRS' },{ n: '8', s: 'TUV' }, { n: '9', s: 'WXYZ' }],
];

// ─── Single PIN dot ────────────────────────────────────────────────────────────
const PinDot = ({ filled, isSuccess, scaleAnim, accent }) => (
  <Animated.View
    style={[
      dotS.dot,
      filled && { backgroundColor: accent, borderColor: accent },
      isSuccess && filled && dotS.success,
      { transform: [{ scale: scaleAnim }] },
    ]}
  />
);

const dotS = StyleSheet.create({
  dot: {
    width: 13,
    height: 13,
    borderRadius: 7,
    borderWidth: 1.6,
    borderColor: '#CBD5E1',
    backgroundColor: 'transparent',
    marginHorizontal: 9,
  },
  success: {
    backgroundColor: '#22C55E',
    borderColor: '#22C55E',
  },
});

// ─── Number / icon key ────────────────────────────────────────────────────────
const Key = ({ num, sub, iconName, onPress, disabled, accent }) => {
  const pressScale = useRef(new Animated.Value(1)).current;

  const handlePress = () => {
    if (disabled) return;
    Animated.sequence([
      Animated.timing(pressScale, { toValue: 0.9, duration: 70, useNativeDriver: true }),
      Animated.spring(pressScale, { toValue: 1, tension: 240, friction: 7, useNativeDriver: true }),
    ]).start();
    onPress?.();
  };

  if (!num && !iconName) return <View style={keyS.ghost} />;

  return (
    <TouchableOpacity onPress={handlePress} activeOpacity={0.7} disabled={disabled} style={keyS.tap}>
      <Animated.View style={{ transform: [{ scale: pressScale }], alignItems: 'center', justifyContent: 'center' }}>
        {iconName ? (
          <Ionicons name={iconName} size={26} color={accent || '#334155'} />
        ) : (
          <Text style={keyS.num}>{num}</Text>
        )}
      </Animated.View>
    </TouchableOpacity>
  );
};

const keyS = StyleSheet.create({
  ghost: { width: 76, height: 60, marginHorizontal: 8 },
  tap: {
    width: 76,
    height: 60,
    borderRadius: 16,
    alignItems: 'center',
    justifyContent: 'center',
    marginHorizontal: 8,
  },
  num: {
    fontSize: 28,
    fontWeight: '500',
    color: '#0F172A',
    letterSpacing: 0.5,
  },
});

// ─── AppLockScreen ────────────────────────────────────────────────────────────
/**
 * mode:
 *   'unlock'  – verify existing PIN (default)
 *   'setup'   – first-step of PIN creation  → onSuccess(pin) called with the entered pin
 *   'confirm' – second-step               → onSuccess() called after saving
 *
 * Props:
 *   onSuccess   — () => void  |  (pin: string) => void
 *   onCancel    — () => void  (shown in setup/confirm modes)
 *   confirmPin  — string       (required in confirm mode)
 */
const AppLockScreen = ({
  mode = 'unlock',
  onSuccess,
  onCancel = undefined,
  confirmPin = undefined,
  forced = false,
}) => {
  const insets = useSafeAreaInsets();
  const { height } = useWindowDimensions();
  const { t } = useLanguageRender();
  const [pin, setPin] = useState('');
  const [errorMsg, setErrorMsg] = useState('');
  const [isSuccess, setIsSuccess] = useState(false);
  // Role → palette: doctor = teal, counselor = blue, everyone else = green.
  const [C, setC] = useState(PATIENT);
  const [role, setRole] = useState('user');
  const [biometricUnlockEnabled, setBiometricUnlockEnabled] = useState(false);
  const [biometricLabel, setBiometricLabel] = useState('Fingerprint');
  // In unlock mode the first render waits for the saved biometric setting. That
  // prevents the PIN keypad from flashing before fingerprint availability is
  // known.
  const [authChoiceReady, setAuthChoiceReady] = useState(mode !== 'unlock');
  const [showKeypad, setShowKeypad] = useState(mode !== 'unlock');
  const [showEmergency, setShowEmergency] = useState(false);
  const [emergency, setEmergency] = useState(null);

  useEffect(() => {
    (async () => {
      const themeRole = await getStoredThemeRole();
      setRole(themeRole);
      setC(paletteForRole(themeRole));
    })();
  }, []);

  // ── Android back ────────────────────────────────────────────────────────────
  // This screen had no back handler at all. In unlock mode it renders as an
  // overlay ABOVE the navigator, so a back press fell through to whatever screen
  // was underneath: it popped that screen invisibly, and once nothing was left
  // to pop it closed the app to the phone's home screen. Either way the user
  // lost the page they were on.
  //
  // Registered on mount, so it sits on top of any screen-level handler (RN calls
  // the most recently added one first) and this screen decides what back means.
  useEffect(() => {
    const onBack = () => {
      // Unlock mode (no onCancel): the lock is a barrier, so swallow the press.
      // Nothing under it moves, and the screen the user left is still there once
      // they unlock.
      if (!onCancel) return true;
      // Setup / confirm mode: hand it to the same handler as the on-screen
      // cancel link, so confirm steps back to setup rather than skipping out of
      // the flow, and a forced setup can't be escaped at all.
      onCancel();
      return true;
    };
    const sub = BackHandler.addEventListener('hardwareBackPress', onBack);
    return () => sub.remove();
  }, [onCancel]);

  // ── Animation refs ──────────────────────────────────────────────────────────
  const slideAnim  = useRef(new Animated.Value(height * 0.06)).current;
  const fadeAnim   = useRef(new Animated.Value(0)).current;
  const shakeAnim  = useRef(new Animated.Value(0)).current;
  const errorFade  = useRef(new Animated.Value(0)).current;
  const checkScale = useRef(new Animated.Value(0)).current;
  const checkFade  = useRef(new Animated.Value(0)).current;
  const dotScales  = useRef(
    Array.from({ length: PIN_LENGTH }, () => new Animated.Value(1))
  ).current;

  // ── Entry animation ─────────────────────────────────────────────────────────
  useEffect(() => {
    Animated.parallel([
      Animated.timing(fadeAnim, { toValue: 1, duration: 280, useNativeDriver: true }),
      Animated.spring(slideAnim, { toValue: 0, tension: 70, friction: 12, useNativeDriver: true }),
    ]).start();
  }, []);

  // ── Load biometric preference (unlock mode) ─────────────────────────────────
  useEffect(() => {
    let active = true;

    if (mode !== 'unlock') {
      setBiometricUnlockEnabled(false);
      setAuthChoiceReady(true);
      setShowKeypad(true);
      return () => {
        active = false;
      };
    }

    setAuthChoiceReady(false);
    setShowKeypad(false);

    (async () => {
      try {
        const [savedSetting, availability] = await Promise.all([
          AsyncStorage.getItem(BIOMETRIC_LOCK_STORAGE_KEY),
          isBiometricAvailable(),
        ]);

        if (!active) return;

        const enabled = savedSetting === 'true' && availability?.available === true;
        setBiometricUnlockEnabled(enabled);
        setBiometricLabel(getBiometryLabel(availability?.biometryType));
        setShowKeypad(!enabled);
      } catch {
        if (!active) return;
        setBiometricUnlockEnabled(false);
        setShowKeypad(true);
      } finally {
        if (active) setAuthChoiceReady(true);
      }
    })();

    return () => {
      active = false;
    };
  }, [mode]);

  // ── Helpers ─────────────────────────────────────────────────────────────────
  const resetDots = useCallback((keepFilled = false) => {
    if (!keepFilled) {
      dotScales.forEach(s =>
        Animated.timing(s, { toValue: 1, duration: 80, useNativeDriver: true }).start()
      );
    }
  }, [dotScales]);

  const triggerError = useCallback((msg) => {
    setErrorMsg(msg);
    setPin('');
    resetDots();

    // Fade in error
    errorFade.setValue(0);
    Animated.timing(errorFade, { toValue: 1, duration: 180, useNativeDriver: true }).start();

    // Vibrate
    if (Platform.OS === 'android') {
      Vibration.vibrate([0, 80, 60, 80]);
    } else {
      Vibration.vibrate(400);
    }

    // Shake the dots row
    Animated.sequence([
      Animated.timing(shakeAnim, { toValue: -13, duration: 55, useNativeDriver: true }),
      Animated.timing(shakeAnim, { toValue:  13, duration: 55, useNativeDriver: true }),
      Animated.timing(shakeAnim, { toValue:  -9, duration: 55, useNativeDriver: true }),
      Animated.timing(shakeAnim, { toValue:   9, duration: 55, useNativeDriver: true }),
      Animated.timing(shakeAnim, { toValue:   0, duration: 55, useNativeDriver: true }),
    ]).start();
  }, [shakeAnim, errorFade, resetDots]);

  const triggerSuccess = useCallback(() => {
    setIsSuccess(true);
    Animated.parallel([
      Animated.spring(checkScale, { toValue: 1, tension: 55, friction: 5, useNativeDriver: true }),
      Animated.timing(checkFade, { toValue: 1, duration: 200, useNativeDriver: true }),
    ]).start(() => {
      setTimeout(() => onSuccess?.(), 380);
    });
  }, [checkScale, checkFade, onSuccess]);

  // ── Auto-prompt biometrics only when the saved toggle is ON ─────────────────
  useEffect(() => {
    if (mode !== 'unlock' || !authChoiceReady || !biometricUnlockEnabled) return;
    const timer = setTimeout(async () => {
      const setting = await AsyncStorage.getItem(BIOMETRIC_LOCK_STORAGE_KEY);
      if (setting !== 'true') {
        setBiometricUnlockEnabled(false);
        setAuthChoiceReady(true);
        setShowKeypad(true);
        return;
      }

      const { available } = await isBiometricAvailable();
      if (!available) return;

      const { success } = await authenticateWithBiometrics('Unlock Humaeli');
      if (success) triggerSuccess();
    }, 350); // slight delay so the screen finishes sliding in
    return () => clearTimeout(timer);
  }, [mode, authChoiceReady, biometricUnlockEnabled, triggerSuccess]);

  // ── PIN completion ──────────────────────────────────────────────────────────
  const handleComplete = useCallback(async (fullPin) => {
    if (mode === 'setup') {
      // Pass the entered PIN to the parent (which moves to confirm step)
      setTimeout(() => {
        setPin('');
        resetDots();
        onSuccess?.(fullPin);
      }, 100);
      return;
    }

    if (mode === 'confirm') {
      if (fullPin === confirmPin) {
        await AsyncStorage.setItem(PIN_STORAGE_KEY, fullPin);
        triggerSuccess();
      } else {
        triggerError(t('lock:pinsDoNotMatch'));
      }
      return;
    }

    // unlock
    const stored = await AsyncStorage.getItem(PIN_STORAGE_KEY);
    if (fullPin === stored) {
      triggerSuccess();
    } else {
      triggerError(t('lock:incorrectPin'));
    }
  }, [mode, confirmPin, onSuccess, resetDots, triggerError, triggerSuccess]);

  // ── Key press ───────────────────────────────────────────────────────────────
  const handlePress = useCallback(async (digit) => {
    if (isSuccess || pin.length >= PIN_LENGTH) return;

    const idx = pin.length;
    const newPin = pin + digit;

    setErrorMsg('');
    errorFade.setValue(0);
    setPin(newPin);

    // Bounce the dot
    Animated.sequence([
      Animated.spring(dotScales[idx], { toValue: 1.45, tension: 280, friction: 5, useNativeDriver: true }),
      Animated.spring(dotScales[idx], { toValue: 1,    tension: 220, friction: 8, useNativeDriver: true }),
    ]).start();

    if (newPin.length === PIN_LENGTH) {
      await handleComplete(newPin);
    }
  }, [pin, isSuccess, dotScales, errorFade, handleComplete]);

  const handleDelete = useCallback(() => {
    if (isSuccess || pin.length === 0) return;
    const idx = pin.length - 1;
    Animated.timing(dotScales[idx], { toValue: 1, duration: 90, useNativeDriver: true }).start();
    setPin(prev => prev.slice(0, -1));
    setErrorMsg('');
    errorFade.setValue(0);
  }, [pin, isSuccess, dotScales, errorFade]);

  const handleBiometric = useCallback(async () => {
    if (mode === 'unlock' && !biometricUnlockEnabled) {
      setShowKeypad(true);
      triggerError(t('lock:enterPin', 'Enter your PIN'));
      return;
    }

    if (mode === 'unlock') {
      const setting = await AsyncStorage.getItem(BIOMETRIC_LOCK_STORAGE_KEY);
      if (setting !== 'true') {
        setBiometricUnlockEnabled(false);
        setAuthChoiceReady(true);
        setShowKeypad(true);
        triggerError(t('lock:enterPin', 'Enter your PIN'));
        return;
      }
    }

    const { available, biometryType } = await isBiometricAvailable();
    if (!available) {
      Alert.alert(
        t('lock:biometricsUnavailable'),
        t('lock:setupBiometrics'),
        [{ text: t('common:ok') }]
      );
      return;
    }
    const label = getBiometryLabel(biometryType);
    const { success } = await authenticateWithBiometrics(`Use ${label} to unlock Humaeli`);
    if (success) triggerSuccess();
  }, [mode, biometricUnlockEnabled, triggerError, triggerSuccess, t]);

  // ── Labels ──────────────────────────────────────────────────────────────────
  const TITLES = {
    unlock:  t('lock:welcomeBack'),
    setup:   t('lock:createPin'),
    confirm: t('lock:confirmPin'),
  };
  const SUBS = {
    unlock:  t('lock:enterPin'),
    setup:   t('lock:choosePin'),
    confirm: t('lock:reenterPin'),
  };

  // Bottom "Unlock" button on the keypad view: submit a complete PIN, else
  // fall back to biometrics (unlock mode) so the button is never a dead tap.
  const handleKeypadUnlock = useCallback(() => {
    if (isSuccess) return;
    if (pin.length === PIN_LENGTH) {
      handleComplete(pin);
    } else if (mode === 'unlock' && biometricUnlockEnabled) {
      handleBiometric();
    } else {
      triggerError(t('lock:enterPin', 'Enter your PIN'));
    }
  }, [isSuccess, pin, mode, biometricUnlockEnabled, handleComplete, handleBiometric, triggerError, t]);

  const dial = (num) => Linking.openURL(`tel:${num}`).catch(() => {});

  
  const emergencyContact = useCallback(async () => {
    let ec = null;
    try {
      const raw = await AsyncStorage.getItem('userData');
      const u = raw ? JSON.parse(raw) : null;
      ec = u?.emergencyContact || u?.personalInfo?.emergencyContact || null;
    } catch { /* ignore */ }
    setEmergency(ec && (ec.phone || ec.phoneNumber) ? ec : null);
    setShowEmergency(true);
  }, []);

  return (
    <Modal
      visible={true}
      animationType="none"
      presentationStyle="fullScreen"
      statusBarTranslucent
    >
    <AuthBackground role={role}>
      <SafeAreaView style={s.safe} edges={['top', 'bottom']}>
        <StatusBar barStyle="dark-content" backgroundColor="transparent" translucent />

        {/* Scrolls when the (tall PIN) card can't fit, so all 4 corners always
            stay on-screen instead of the bottom being clipped. */}
        <ScrollView
          style={s.scroll}
          contentContainerStyle={s.scrollContent}
          showsVerticalScrollIndicator={false}
          bounces={false}
        >
        <Animated.View style={[s.card, { opacity: fadeAnim, transform: [{ translateY: slideAnim }] }]}>
          {/* ── Header ────────────────────────────────────────────────────── */}
          <View style={s.header}>
            <Ionicons name="shield-checkmark" size={20} color={C.primary} />
            <Text style={[s.brand, { color: C.primary }]}>{t('Humaeli')}</Text>
          </View>
          <Text style={s.secureLabel}>{t('SECURE ACCESS REQUIRED')}</Text>

          {mode === 'unlock' && !authChoiceReady ? (
            /* ═══ Auth-choice loading view: no PIN keypad flash ═══ */
            <>
              <View style={[s.faceRing, { borderColor: C.border }]}>
                <View style={[s.faceInner, { backgroundColor: C.secondaryTint }]}>
                  <ActivityIndicator size="small" color={C.primary} />
                </View>
              </View>

              <Text style={s.title}>{t('lock:welcomeBack', 'Unlock Humaeli')}</Text>
              <Text style={s.subtitle}>{t('Checking secure unlock...')}</Text>

              <TouchableOpacity onPress={emergencyContact} activeOpacity={0.7} style={s.emergencyBtn}>
                <Text style={[s.emergencyText, { color: C.primary }]}>{t('EMERGENCY CONTACT')}</Text>
              </TouchableOpacity>
            </>
          ) : mode === 'unlock' && biometricUnlockEnabled && !showKeypad ? (
            /* ═══ Face-ID landing view ═══ */
            <>
              <View style={[s.faceRing, { borderColor: C.border }]}>
                <View style={[s.faceInner, { backgroundColor: C.secondaryTint }]}>
                  <Ionicons name="happy-outline" size={40} color={C.primary} />
                </View>
              </View>

              <Text style={s.title}>{t('lock:welcomeBack', 'Unlock Humaeli')}</Text>
              <Text style={s.subtitle}>{t(`${biometricLabel} or passcode`)}</Text>

              <TouchableOpacity activeOpacity={0.88} onPress={handleBiometric} style={s.primaryBtnWrap}>
                <LinearGradient
                  colors={[C.gradientFrom, C.gradientTo]}
                  start={{ x: 0, y: 0 }}
                  end={{ x: 1, y: 0 }}
                  style={s.primaryBtn}
                >
                  <Ionicons name="lock-open" size={17} color="#fff" />
                  <Text style={s.primaryBtnText}>{t('Unlock')}</Text>
                </LinearGradient>
              </TouchableOpacity>

              <TouchableOpacity style={s.secondaryBtn} activeOpacity={0.8} onPress={() => setShowKeypad(true)}>
                <Text style={s.secondaryBtnText}>{t('Use PIN instead')}</Text>
              </TouchableOpacity>

              <TouchableOpacity onPress={emergencyContact} activeOpacity={0.7} style={s.emergencyBtn}>
                <Text style={[s.emergencyText, { color: C.primary }]}>{t('EMERGENCY CONTACT')}</Text>
              </TouchableOpacity>
            </>
          ) : (
            /* ═══ PIN keypad view ═══ */
            <>
              <Text style={s.title}>{TITLES[mode]}</Text>
              <Text style={s.subtitle}>{SUBS[mode]}</Text>

              <Animated.View style={[s.dotsRow, { transform: [{ translateX: shakeAnim }] }]}>
                {Array.from({ length: PIN_LENGTH }).map((_, i) => (
                  <PinDot
                    key={i}
                    filled={i < pin.length}
                    isSuccess={isSuccess}
                    scaleAnim={dotScales[i]}
                    accent={C.primary}
                  />
                ))}
              </Animated.View>

              <Animated.Text style={[s.error, { opacity: errorFade }]}>
                {errorMsg}
              </Animated.Text>

              <View style={s.pad}>
                {KEYPAD.map((row, ri) => (
                  <View key={ri} style={s.padRow}>
                    {row.map(({ n }) => (
                      <Key key={n} num={n} onPress={() => handlePress(n)} disabled={isSuccess} />
                    ))}
                  </View>
                ))}
                <View style={s.padRow}>
                  {mode === 'unlock' && biometricUnlockEnabled ? (
                    <Key iconName="finger-print-outline" onPress={handleBiometric} disabled={isSuccess} accent={C.primary} />
                  ) : (
                    <View style={keyS.ghost} />
                  )}
                  <Key num="0" onPress={() => handlePress('0')} disabled={isSuccess} />
                  <Key iconName="backspace-outline" onPress={handleDelete} disabled={isSuccess} accent="#64748B" />
                </View>
              </View>

              {/* Gradient action button (role palette) */}
              <TouchableOpacity activeOpacity={0.88} onPress={handleKeypadUnlock} style={s.primaryBtnWrap} disabled={isSuccess}>
                <LinearGradient
                  colors={[C.gradientFrom, C.gradientTo]}
                  start={{ x: 0, y: 0 }}
                  end={{ x: 1, y: 0 }}
                  style={s.primaryBtn}
                >
                  <Ionicons name="lock-open" size={17} color="#fff" />
                  <Text style={s.primaryBtnText}>
                    {mode === 'setup' ? t('common:continue', 'Continue')
                      : mode === 'confirm' ? t('lock:confirmPin', 'Confirm')
                      : 'Unlock'}
                  </Text>
                </LinearGradient>
              </TouchableOpacity>

              {mode === 'unlock' && biometricUnlockEnabled ? (
                <TouchableOpacity style={s.textLink} activeOpacity={0.7} onPress={() => setShowKeypad(false)}>
                  <Text style={s.textLinkLabel}>{t(`Use ${biometricLabel} instead`)}</Text>
                </TouchableOpacity>
              ) : onCancel && !(forced && mode === 'setup') ? (
                <TouchableOpacity style={s.textLink} activeOpacity={0.7} onPress={onCancel}>
                  <Text style={s.textLinkLabel}>{forced ? 'Back' : 'Cancel'}</Text>
                </TouchableOpacity>
              ) : (
                <View style={{ height: 16 }} />
              )}
            </>
          )}

          {/* Success checkmark overlay */}
          <Animated.View
            pointerEvents="none"
            style={[s.checkWrap, { opacity: checkFade, transform: [{ scale: checkScale }] }]}
          >
            <Ionicons name="checkmark-circle" size={64} color="#22C55E" />
          </Animated.View>
        </Animated.View>
        </ScrollView>

        {/* ── Emergency help sheet (role-themed) ────────────────────────────── */}
        {showEmergency && (
          <View style={s.emgOverlay}>
            <TouchableOpacity style={s.emgBackdrop} activeOpacity={1} onPress={() => setShowEmergency(false)} />
            <View style={[s.emgSheet, { paddingBottom: Math.max(insets.bottom, 26) }]}>
              <View style={s.emgHandle} />

              <View style={[s.emgIcon, { backgroundColor: C.secondaryTint }]}>
                <Ionicons name="medical" size={24} color={C.primary} />
