const GENDERS       = ["all", "male", "female"];

const INITIALS_COLORS = [
  "#667eea", "#f093fb", "#4facfe", "#43e97b",
  "#fa709a", "#fcc419", "#ff6b6b", "#20c997",
  "#fd7e14", "#6f42c1", "#0dcaf0", "#d63384",
];

const DICEBEAR_BASE = "https://api.dicebear.com/7.x";
function getInitialsUrl(initials, color) {
  const enc = encodeURIComponent(initials.toUpperCase().slice(0, 2));
  const bg  = color.replace("#", "");
  return `${DICEBEAR_BASE}/initials/svg?seed=${enc}&backgroundColor=${bg}&radius=50&fontSize=40`;
}

const AvatarGenerator = ({ userName, onSelect, onClose }) => {
  const { S } = useResponsiveScreenStyles();
  const insets = useSafeAreaInsets();
  const { t } = useLanguageRender();
  const [tab, setTab]           = useState("real");
  const [selectedId, setSelectedId] = useState(null);
  const [gender, setGender]     = useState("all");
  const [age, setAge]           = useState("all");
  const [color, setColor]       = useState(INITIALS_COLORS[0]);

  const initials = (userName || "U")
    .split(" ").map(n => n[0]).join("").toUpperCase().slice(0, 2);

  const filtered = REAL_AVATARS.filter(a =>
    (gender === "all" || a.gender === gender) &&
    (age    === "all" || a.age    === age)
  );

  const handleApply = () => {
    if (tab === "real") {
      const a = REAL_AVATARS.find(x => x.id === selectedId);
      if (a) { onSelect(a.url); onClose(); }
    } else {
      onSelect(getInitialsUrl(initials, color));
      onClose();
    }
  };

  return (
    <Modal animationType="slide" transparent visible onRequestClose={onClose}>
      <View style={S.overlay}>
        <View style={[S.sheet, { paddingBottom: Math.max(insets.bottom, 24) }]}>

          {/* Header */}
          <View style={S.header}>
            <Text style={S.headerTitle}>{t('Choose Avatar')}</Text>
            <TouchableOpacity onPress={onClose} style={S.closeBtn}>
              <Text style={S.closeX}>✕</Text>
            </TouchableOpacity>
          </View>

          {/* Tabs */}
          <View style={S.tabs}>
            {["real", "initials"].map(t => (
              <TouchableOpacity key={t} style={[S.tab, tab === t && S.tabActive]} onPress={() => setTab(t)}>
                <Text style={[S.tabText, tab === t && S.tabTextActive]}>
                  {t === "real" ? "Real Photos" : "Initials"}
                </Text>
              </TouchableOpacity>
            ))}
          </View>

          {tab === "real" ? (
            <>
              {/* Gender filter */}
              <ScrollView horizontal showsHorizontalScrollIndicator={false} style={S.filterRow} contentContainerStyle={{ gap: 6, paddingHorizontal: 16, paddingVertical: 8 }}>
                {GENDERS.map(g => (
                  <TouchableOpacity key={g} style={S.pillWrap} onPress={() => setGender(g)} activeOpacity={0.85}>
                    <LinearGradient
                      colors={gender === g ? PATIENT_GRADIENT : TRANSPARENT_GRADIENT}
                      {...GRADIENT_DIRECTION}
                      style={[S.pill, gender === g && S.pillActive]}
                    >
                      <Text style={[S.pillText, gender === g && S.pillTextActive]}>
                        {g === "all" ? "All" : g === "male" ? "Male" : "Female"}
                      </Text>
                    </LinearGradient>
                  </TouchableOpacity>
                ))}
                <View style={{ width: 12 }} />
                {AGE_GROUPS.map(a => (
                  <TouchableOpacity key={a} style={S.pillWrap} onPress={() => setAge(a)} activeOpacity={0.85}>
                    <LinearGradient
                      colors={age === a ? PATIENT_GRADIENT : TRANSPARENT_GRADIENT}
                      {...GRADIENT_DIRECTION}
                      style={[S.pill, age === a && S.pillActive]}
                    >
                      <Text style={[S.pillText, age === a && S.pillTextActive]}>
                        {a === "all" ? "All Ages" : a}
                      </Text>
                    </LinearGradient>
                  </TouchableOpacity>
                ))}
              </ScrollView>

              {/* Photo grid */}
              <FlatList
                data={filtered}
                keyExtractor={item => item.id}
                numColumns={3}
                style={{ flex: 1 }}
                contentContainerStyle={S.grid}
                renderItem={({ item }) => (
                  <TouchableOpacity
                    style={[S.gridItem, selectedId === item.id && S.gridItemSelected]}
                    onPress={() => setSelectedId(item.id)}
                    activeOpacity={0.8}
