// Counselor names are often stored with the title already on them, so blindly
// prefixing produced "Dr. Dr. Naina Sharma".
const TERMINAL_APT_STATUSES = new Set(["completed", "cancelled", "rejected", "no-show", "no_show"]);
const normalizeAptStatus = (value) => String(value || "pending").trim().toLowerCase().replace(/^canceled$/, "cancelled");
// Emergency request the clinic hasn't given a time yet (web emergencyBooking.js).
const isUnscheduledEmergency = (apt) =>
  String(apt?.priority || "").toLowerCase() === "emergency" && !apt?.appointment_time;

const isEmergencyAppointment = (apt) =>
  String(apt?.priority || apt?.appointment_priority || '').toLowerCase() === 'emergency'
  || apt?.is_emergency === true || apt?.isEmergency === true || String(apt?.is_emergency).toLowerCase() === 'true';

// Doctor appointments have no chat (web MyAppointments getProfessionalRole).
// GET /api/appointments only populates the professional's name/photo, so the
// role comes from the appointment if present, else the counsellors list.
const isDoctorAppointment = (apt, doctorIds) => {
  const rawRole = String(apt?.counselor?.role || apt?.doctor?.role || apt?.role || '').trim().toLowerCase();
  if (rawRole) return rawRole === 'doctor';
  const id = apt?.counselor?._id || apt?.counselor?.id || apt?.counselorId || apt?.counselor;
  return !!id && doctorIds.has(String(id));
};
const getAppointmentIdentity = (apt) => String(
  apt?._id || apt?.id || apt?.appointmentId || apt?.appointment_id || '',
);
const getProviderIdentity = (apt) => {
  const counselor = apt?.counselor || apt?.doctor || {};
  const id = counselor?._id || counselor?.id || apt?.counselorId || apt?.doctorId;
  if (id) return `provider:${id}`;
  return `name:${String(counselor?.fullName || counselor?.name || 'provider').trim().toLowerCase()}`;
};

// In-clinic (OPD / walk-in / emergency) doctor visits happen in person, so they
// get the live token queue instead of video / voice / chat. DoctorBookingModal
// sends consultation_mode 'in-clinic' | 'video' | 'voice'; older rows may only
// carry a clinic or token, so those count as clinic visits unless a remote mode
// is named.
const getAptConsultMode = (apt) => String(
  apt?.consultation_mode || apt?.consultationMode || apt?.mode || apt?.sessionType
  || apt?.appointment_type || apt?.visit_type || ''
).trim().toLowerCase();

const isClinicVisitAppointment = (apt) => {
  if (!apt) return false;
  const mode = getAptConsultMode(apt);
  if (/clinic|opd|in[-_ ]?person|offline|walk[-_ ]?in/.test(mode)) return true;
  if (/video|voice|audio|call|online|chat/.test(mode)) return false;
  return Boolean(
    apt.clinic_id || apt.clinicId || apt.clinic
    || apt.token_number != null || apt.tokenNumber != null || apt.queue_token != null
  );
};

const canCancelUserAppointment = (appointment) => {
  if (!appointment) return false;
  const status = String(appointment.appointment_status || appointment.status || '').toLowerCase();
  const queue = String(appointment.queue_status || appointment.queueStatus || '').toLowerCase();
  let timing = appointment.consultation_timing || appointment.consultationTiming || appointment.timing || {};
  if (typeof timing === 'string') {
    try { timing = JSON.parse(timing); } catch { return false; }
  }
  return ['pending', 'confirmed', 'booked', 'accepted'].includes(status)
    && !['in_progress', 'in-progress', 'completed', 'canceled', 'cancelled'].includes(queue)
    && !appointment.consultation_started_at && !appointment.consultation_ended_at
    && !timing?.startedAt && !timing?.started_at && !timing?.endedAt && !timing?.ended_at;
};

function PatientEmergencyModal({ visible, appointment, busy, error, onClose, onSubmit }) {
  const { t } = useLanguageRender();
  const [reason, setReason] = useState('');

  useEffect(() => {
    if (visible) setReason('');
  }, [visible, appointment]);

  const trimmed = reason.trim();
  return (
    <Modal visible={visible} transparent animationType="fade" statusBarTranslucent navigationBarTranslucent onRequestClose={onClose}>
      <View style={styles.emergencyModalOverlay}>
        <View style={styles.emergencyModalCard}>
          <View style={styles.emergencyModalHeader}>
            <View style={styles.emergencyModalIcon}><Ionicons name="warning" size={20} color="#B42318" /></View>
            <View style={{ flex: 1 }}>
              <Text style={styles.emergencyModalTitle}>{t('Emergency request')}</Text>
              <Text style={styles.emergencyModalSubtitle}>{t('Send an urgent alert to your doctor and clinic.')}</Text>
            </View>
            <TouchableOpacity onPress={onClose} disabled={busy} hitSlop={10}>
              <MaterialIcons name="close" size={21} color="#64748B" />
            </TouchableOpacity>
          </View>
          <TextInput
            value={reason}
            onChangeText={setReason}
            multiline
            maxLength={1000}
            editable={!busy}
            placeholder={t('What is happening?')}
            placeholderTextColor="#94A3B8"
            style={styles.emergencyReasonInput}
          />
          <Text style={styles.emergencyHint}>{trimmed.length}/1000 · {t('At least 10 characters')}</Text>
          {!!error && <Text style={styles.emergencyError}>{error}</Text>}
          <View style={styles.emergencyModalActions}>
            <TouchableOpacity style={styles.emergencyCancelBtn} onPress={onClose} disabled={busy}>
              <Text style={styles.emergencyCancelText}>{t('Cancel')}</Text>
            </TouchableOpacity>
            <TouchableOpacity
              style={[styles.emergencySendBtn, (busy || trimmed.length < 10) && styles.emergencySendDisabled]}
              onPress={() => onSubmit(trimmed)}
              disabled={busy || trimmed.length < 10}
            >
              {busy ? <ActivityIndicator color="#FFF" size="small" /> : <Ionicons name="alert-circle-outline" size={17} color="#FFF" />}
              <Text style={styles.emergencySendText}>{busy ? t('Sending...') : t('Send Emergency')}</Text>
            </TouchableOpacity>
          </View>
        </View>
      </View>
    </Modal>
  );
}

const getAptId = (apt) => String(apt?._id || apt?.id || apt?.appointmentId || apt?.appointment_id || '');
const getTokenItemAptId = (item) => String(
  item?.appointment?.appointmentId || item?.appointment?._id || item?.appointment?.id || item?._id || item?.id || ''
);
const showQueueValue = (value, suffix = '') => (value != null && value !== '' ? `${value}${suffix}` : '--');
const formatTurnTime = (value) => {
  const ms = Date.parse(value);
  return Number.isFinite(ms) ? new Date(ms).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '--';
};
const CLINIC_QUEUE_POLL_MS = 10000;

// Live queue for one clinic-visit appointment, from the same endpoint and
// `queueUpdated` socket event as the My Token screen. Only runs while enabled
// (the details sheet is open on a clinic visit).
const useClinicQueue = (apt, enabled) => {
  const [item, setItem] = useState(null);
  const [loading, setLoading] = useState(false);
  const [now, setNow] = useState(Date.now());
  const [clockOffset, setClockOffset] = useState(0);
  const aptId = getAptId(apt);
  const aptToken = apt?.token_number ?? apt?.tokenNumber ?? apt?.queue_token ?? apt?.token;

  useEffect(() => {
    if (!enabled) {
      setItem(null);
      return undefined;
    }
    let cancelled = false;
    let unsubscribe = null;
    let debounceId = null;
    setNow(Date.now());

    const load = async (silent) => {
      try {
        if (!silent) setLoading(true);
        const res = await axiosInstance.get('/api/appointments/my-token-status', { headers: { 'Cache-Control': 'no-cache' } });
        if (cancelled) return;
        const list = Array.isArray(res.data?.appointments) ? res.data.appointments : [];
        const match = list.find((entry) => aptId && getTokenItemAptId(entry) === aptId)
          || (aptToken != null ? list.find((entry) => String(entry?.token?.myToken) === String(aptToken)) : null)
          || null;
        setItem(match);
        const serverTime = Date.parse(match?.current?.serverTime);
        if (Number.isFinite(serverTime)) setClockOffset(serverTime - Date.now());
      } catch (err) {
        console.warn('Failed to load clinic queue:', err?.response?.data || err?.message);
      } finally {
        if (!cancelled && !silent) setLoading(false);
      }
    };

    load(false);
    const pollId = setInterval(() => load(true), CLINIC_QUEUE_POLL_MS);
    const tickId = setInterval(() => setNow(Date.now()), 1000);
    (async () => {
      try {
        await socketService.connect();
        const off = await socketService.on('queueUpdated', () => {
          clearTimeout(debounceId);
          debounceId = setTimeout(() => load(true), 500);
        });
        if (cancelled) off?.(); else unsubscribe = off;
      } catch (e) { /* polling still keeps it fresh */ }
    })();

    return () => {
      cancelled = true;
      clearInterval(pollId);
      clearInterval(tickId);
      clearTimeout(debounceId);
      try { unsubscribe?.(); } catch (e) { /* ignore */ }
    };
  }, [enabled, aptId, aptToken]);

  return { item, loading, now: now + clockOffset, fallbackToken: aptToken };
};

const counselorDisplayName = (apt) => {
  const name = String(apt?.counselor?.fullName || '').trim() || 'Counselor';
  return /^(dr\.?|doctor)\s/i.test(name) ? name : `Dr. ${name}`;
};

// How long the consultation actually ran, from the fields the API really sends.
// This used to read camelCase names (actualDuration / talkTime / startTime …)
// that the payload never contains, so every lookup missed and it fell through to
// a hard-coded "45". Pauses are subtracted so the figure is real talk time.
const getActualDurationMinutes = (apt) => {
  const timing = apt?.consultation_timing || apt?.consultationTiming || {};
  const startedAt = apt?.consultation_started_at ?? apt?.consultationStartedAt
    ?? apt?.actual_start_at ?? apt?.actualStartAt ?? timing.startedAt;
  const endedAt = apt?.consultation_ended_at ?? apt?.consultationEndedAt
    ?? apt?.actual_end_at ?? apt?.actualEndAt ?? timing.endedAt;
  const start = Date.parse(startedAt);
  const end = Date.parse(endedAt);
  if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start) return null;
  const pausedMs = (Array.isArray(timing.pauses) ? timing.pauses : []).reduce((sum, pause) => {
    const from = Date.parse(pause?.startedAt ?? pause?.pausedAt ?? pause?.from);
    const to = Date.parse(pause?.endedAt ?? pause?.resumedAt ?? pause?.to);
    return Number.isFinite(from) && Number.isFinite(to) && to > from ? sum + (to - from) : sum;
  }, 0);
  return Math.max(0, end - start - pausedMs) / 60000;
};

// Clock time the consultation actually ended. The "Ended" stamp used to print
// the appointment's scheduled time, so a 14:45 booking that really ran until
// 14:57 still read "Ended 14:45".
const getActualEndDate = (apt) => {
  const timing = apt?.consultation_timing || apt?.consultationTiming || {};
  const endedAt = apt?.consultation_ended_at ?? apt?.consultationEndedAt
    ?? apt?.actual_end_at ?? apt?.actualEndAt ?? timing.endedAt;
  const ms = Date.parse(endedAt);
  return Number.isFinite(ms) ? new Date(ms) : null;
};

// The slot the doctor gave — what to show before the consultation has happened.
const getScheduledDurationMinutes = (apt) => {
  const explicit = Number(
    apt?.expected_duration_minutes ?? apt?.expectedDurationMinutes
    ?? apt?.slot_duration_minutes ?? apt?.slotDurationMinutes ?? apt?.duration,
  );
  if (Number.isFinite(explicit) && explicit > 0) return explicit;
  const start = Date.parse(apt?.estimated_start_at ?? apt?.estimatedStartAt ?? apt?.scheduledTime);
  const end = Date.parse(apt?.estimated_end_at ?? apt?.estimatedEndAt);
  if (Number.isFinite(start) && Number.isFinite(end) && end > start) return (end - start) / 60000;
  return null;
};

// "10 minutes" / "1 minute" / "40 sec" / "1 hour 5 min" — and a dash rather than
// an invented number when the data genuinely isn't there.
const formatDurationLabel = (minutes) => {
  if (minutes == null || !Number.isFinite(minutes)) return '—';
  if (minutes < 1) return `${Math.max(1, Math.round(minutes * 60))} sec`;
  const total = Math.round(minutes);
  if (total < 60) return `${total} ${total === 1 ? 'minute' : 'minutes'}`;
  const hours = Math.floor(total / 60);
  const rest = total % 60;
  const hourLabel = `${hours} ${hours === 1 ? 'hour' : 'hours'}`;
  return rest ? `${hourLabel} ${rest} min` : hourLabel;
};

// Experience can arrive as a bare number (4) or a string ("4 years"). Always
// render it with the unit (TranslatedText localizes the word), and return '' —
// not a fake fallback — when it's missing.
const formatExperience = (value) => {
  if (value == null || value === '') return '';
  const str = String(value).trim();
  if (/year|yr|साल|वर्ष/i.test(str)) return str; // already carries a unit
  const n = parseFloat(str);
  if (!Number.isFinite(n)) return str;
  return `${n} ${n === 1 ? 'year' : 'years'}`;
};

