const MyAppointmentsPanel = ({ onBookPress, onVideoCall, onVoiceCall, onChat }) => {
  const { t } = useLanguageRender();
  const { width: screenWidth, height: screenHeight } = useWindowDimensions();
  const [appointments, setAppointments] = useState([]);
  const [loadingAppointments, setLoadingAppointments] = useState(true);
  const [activeTab, setActiveTab] = useState("All");
  const [statusFilter, setStatusFilter] = useState("All");
  const [selectedApt, setSelectedApt] = useState(null);
  const [selectedProviderKey, setSelectedProviderKey] = useState(null);
  const [showDetailsModal, setShowDetailsModal] = useState(false);
  const [countdown, setCountdown] = useState("");
  const [actionLoading, setActionLoading] = useState(null);
  const [emergencyAppointment, setEmergencyAppointment] = useState(null);
  const [emergencyBusy, setEmergencyBusy] = useState(false);
  const [emergencyError, setEmergencyError] = useState('');
  const [doctorIds, setDoctorIds] = useState(() => new Set());
  const socketRef = useRef(null);
  // Web MyAppointments "Rate Doctor": a completed doctor appointment can be
  // rated once — POST /api/appointments/:id/doctor-rating { rating, review }.
  const [ratingApt, setRatingApt] = useState(null);
  const [ratingBusy, setRatingBusy] = useState(false);
  const [ratingError, setRatingError] = useState("");
  const [ratingSuccess, setRatingSuccess] = useState(false);
  const openDoctorRating = (apt) => {
    setRatingError("");
    setRatingSuccess(false);
    setRatingApt(apt);
  };
  const submitDoctorRating = async ({ rating, review }) => {
    const appointmentId = getAppointmentIdentity(ratingApt);
    if (ratingBusy || !appointmentId) return;
    setRatingBusy(true);
    setRatingError("");
    try {
      const { data } = await axiosInstance.post(
        `/api/appointments/${encodeURIComponent(appointmentId)}/doctor-rating`,
        { rating, review: String(review || "").trim() },
        { timeout: 15000 },
      );
      const saved = data?.doctorRating || { stars: rating, review };
      setAppointments((rows) => rows.map((row) => (
        getAppointmentIdentity(row) === appointmentId ? { ...row, doctorRating: saved } : row
      )));
      setRatingSuccess(true);
      setTimeout(() => setRatingApt(null), 1500);
    } catch (err) {
      const status = err?.response?.status;
      setRatingError(status === 404
        ? t('Doctor rating is not available on the server yet. Please try again later.')
        : err?.response?.data?.error || err?.response?.data?.message || t('Rating could not be saved. Please try again.'));
    } finally {
      setRatingBusy(false);
    }
  };

  useEffect(() => {
    let cancelled = false;
    axiosInstance.get('/api/auth/counsellors')
      .then((res) => {
        const list = res.data?.counsellors || res.data?.data || (Array.isArray(res.data) ? res.data : []);
        if (cancelled) return;
        setDoctorIds(new Set(list
          .filter((c) => String(c?.role || '').toLowerCase() === 'doctor')
          .map((c) => String(c._id || c.id))));
      })
      .catch(() => {});
    return () => { cancelled = true; };
  }, []);
  // Only a doctor appointment booked as a clinic visit drops the calls for the
  // live token queue; consultant appointments always keep video/voice/chat.
  const isDoctorClinicVisit = (apt) => isDoctorAppointment(apt, doctorIds) && isClinicVisitAppointment(apt);
  // The details sheet is a Modal, so it sits OUTSIDE the screen's SafeAreaView
  // and nothing was compensating for the device's bottom inset. On a phone with
  // gesture navigation the footer's Chat / Call row ran under the system bar.
  const sheetInsets = useSafeAreaInsets();

  // Live countdown to the session start while the details sheet is open.
  useEffect(() => {
    if (!showDetailsModal || !selectedApt?.date) return;
    console.log('📌 SELECTED APPOINTMENT (View Details opened):', JSON.stringify(selectedApt, null, 2));
    const target = new Date(selectedApt.date).getTime();
    const pad = (n) => String(n).padStart(2, "0");
    const tick = () => {
      const diff = target - Date.now();
      if (diff <= 0) {
        setCountdown("00:00:00");
        return;
      }
      const h = Math.floor(diff / 3600000);
      const m = Math.floor((diff % 3600000) / 60000);
      const s = Math.floor((diff % 60000) / 1000);
      setCountdown(`${pad(h)}:${pad(m)}:${pad(s)}`);
    };
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, [showDetailsModal, selectedApt]);

  // Tablet detection for responsive modal
  const isTablet = screenWidth >= 600;
  const sheetMaxHeight = Math.min(screenHeight * (isTablet ? 0.82 : 0.86), isTablet ? 720 : 680);
  const sheetScrollMaxHeight = Math.max(360, sheetMaxHeight - 90);

  const fetchAppointments = useCallback(async (silent = false) => {
    try {
      if (!silent) setLoadingAppointments(true);
      const response = await axiosInstance.get('/api/appointments');
      const rawApts = Array.isArray(response.data) ? response.data : [];
      // A deleted consultant/doctor account leaves its appointments behind with
      // no professional record, so they rendered as a nameless placeholder card.
      const apts = rawApts.filter((apt) => !isProfessionalAccountDeleted(apt));
      if (apts.length > 0) {
        console.log('📋 APPOINTMENT DATA STRUCTURE:', JSON.stringify(apts[0], null, 2));
      }
      setAppointments(apts);
    } catch (err) {
      console.error("Error fetching appointments:", err);
      if (!silent) setAppointments([]);
    } finally {
      setLoadingAppointments(false);
    }
  }, []);

  const cancelAppointment = async (appointment) => {
    const appointmentId = getAppointmentIdentity(appointment);
    if (actionLoading || !appointmentId || !canCancelUserAppointment(appointment)) return;
    Alert.alert(t('Cancel appointment'), t('Cancel this appointment?'), [
      { text: t('Keep'), style: 'cancel' },
      {
        text: t('Cancel appointment'),
        style: 'destructive',
        onPress: async () => {
          setActionLoading(`cancel-${appointmentId}`);
          try {
            await axiosInstance.patch(`/api/appointments/${encodeURIComponent(appointmentId)}/cancel`, { source: 'online' });
            setAppointments((rows) => rows.map((row) => getAppointmentIdentity(row) === appointmentId
              ? { ...row, status: 'canceled', queue_status: 'canceled' } : row));
            setSelectedApt((current) => current && getAppointmentIdentity(current) === appointmentId
              ? { ...current, status: 'canceled', queue_status: 'canceled' } : current);
            setShowDetailsModal(false);
          } catch (error) {
            Alert.alert(t('Cancel appointment'), error?.response?.data?.message || t('Appointment could not be cancelled. Please try again.'));
            if (error?.response?.status === 409) await fetchAppointments(true);
          } finally {
            setActionLoading(null);
          }
        },
      },
    ]);
  };

  const submitEmergency = async (reason) => {
    const appointmentId = getAppointmentIdentity(emergencyAppointment);
    if (emergencyBusy || !appointmentId || reason.length < 10) return;
    setEmergencyBusy(true);
    setEmergencyError('');
    try {
      await axiosInstance.patch(`/api/appointments/${encodeURIComponent(appointmentId)}/emergency`, {
        reason,
        is_emergency: true,
      });
      setAppointments((rows) => rows.map((row) => getAppointmentIdentity(row) === appointmentId
        ? { ...row, priority: 'emergency', emergency_reason: reason, is_emergency: true } : row));
      setSelectedApt((current) => current && getAppointmentIdentity(current) === appointmentId
        ? { ...current, priority: 'emergency', emergency_reason: reason, is_emergency: true } : current);
      setEmergencyAppointment(null);
    } catch (error) {
      setEmergencyError(error?.response?.data?.message || error?.response?.data?.error || t('Emergency request could not be sent. Please try again.'));
    } finally {
      setEmergencyBusy(false);
    }
  };

  useLiveRefresh(() => fetchAppointments(true));

  useEffect(() => {
    const connectSocket = async () => {
      const token = (await AsyncStorage.getItem("token")) || (await AsyncStorage.getItem("accessToken"));
      const userId = await AsyncStorage.getItem("userId");
      if (!token) return;

      const unsubscribers = [];
      try {
        const socket = await socketService.connect();
        socketRef.current = socket;

        if (userId) socket.emit('join-user-room', { userId });

        const refresh = () => fetchAppointments();
        unsubscribers.push(await socketService.on('appointment-booked', refresh));
        unsubscribers.push(await socketService.on('appointment-updated', refresh));
        unsubscribers.push(await socketService.on('appointment-confirmed', refresh));
        unsubscribers.push(await socketService.on('appointment-cancelled', refresh));
        unsubscribers.push(await socketService.on('appointment-status-changed', refresh));
        unsubscribers.push(await socketService.on('appointment-call-initiated', refresh));
        unsubscribers.push(await socketService.on('appointment-status-updated', refresh));

        socketRef.current._unsubscribers = unsubscribers;
      } catch (err) {
        console.error('Failed to connect shared socket for appointments:', err);
      }
    };

    connectSocket();

    return () => {
      try {
        const unsub = socketRef.current?._unsubscribers || [];
        unsub.forEach(fn => { try { fn(); } catch {} });
      } catch (e) {}
      socketRef.current = null;
    };
  }, [fetchAppointments]);

  // Same rules as the web (appointmentFilters.js). An emergency request with
  // no time yet has no valid date, so a plain date check dropped it from both
  // Upcoming and Past — it stays in Upcoming until it's completed/cancelled.
  const nowMs = Date.now();
  const aptTimestamp = (apt) => Date.parse(apt?.date) || 0;
  const periodApts = appointments.filter((apt) => {
    const value = normalizeAptStatus(apt.status);
    const pendingEmergency = isUnscheduledEmergency(apt) && !TERMINAL_APT_STATUSES.has(value);
    if (activeTab === "Upcoming") return !TERMINAL_APT_STATUSES.has(value) && (pendingEmergency || aptTimestamp(apt) > nowMs);
    if (activeTab === "Past") return TERMINAL_APT_STATUSES.has(value) || (!pendingEmergency && aptTimestamp(apt) <= nowMs);
    return true;
  }).sort((a, b) => (Date.parse(b.createdAt || b.created_at) || aptTimestamp(b)) - (Date.parse(a.createdAt || a.created_at) || aptTimestamp(a)));

  // Vitals tracking only makes sense once a Doctor (psychiatrist — medical,
  // can prescribe) has actually seen the patient, not a talk-therapy
  // Consultant. Same classifier used for the "Doctor"/"Consultant" badge in
  // the counselor directory.
  const hasCompletedDoctorVisit = appointments.some(
    (apt) => apt.status === "completed" && isPsychiatristSpecialization(apt?.counselor?.specialization)
  );

  let displayApts = periodApts;

  if (statusFilter === "Pending") {
    displayApts = displayApts.filter((apt) => apt.status === "pending");
  }
  if (statusFilter === "Confirmed") {
    displayApts = displayApts.filter((apt) => apt.status === "confirmed");
  }
  if (statusFilter === "Completed") {
    displayApts = displayApts.filter((apt) => apt.status === "completed");
  }

  const providerGroups = Object.values(displayApts.reduce((groups, appointment) => {
    const key = getProviderIdentity(appointment);
    if (!groups[key]) groups[key] = { key, latest: appointment, appointments: [] };
    groups[key].appointments.push(appointment);
    return groups;
  }, {}));
  const selectedProvider = providerGroups.find((group) => group.key === selectedProviderKey) || null;
  const selectedProviderAppointments = selectedProvider?.appointments || [];

  useEffect(() => {
    if (selectedProviderKey && !selectedProvider) setSelectedProviderKey(null);
  }, [selectedProviderKey, selectedProvider]);

  const isCanceledStatus = (status) => status === "canceled" || status === "cancelled";

  const getStatusStyle = (status) => {
    if (status === "confirmed") return styles.aptStatusConfirmed;
    if (status === "completed") return styles.aptStatusCompleted;
    if (isCanceledStatus(status)) return styles.aptStatusCanceled;
    return styles.aptStatusPending;
  };

  const getStatusTextColor = (status) => {
    if (status === "confirmed") return PATIENT.primary;
    if (status === "completed") return PATIENT.primary;
    if (isCanceledStatus(status)) return "#B91C1C";
    return "#C2410C";
  };

  const getStatusIcon = (status) => {
    if (status === "confirmed") return "checkmark-circle";
    if (status === "completed") return "checkmark-done-circle";
    if (isCanceledStatus(status)) return "close-circle";
    return "time";
  };

  const getAvatarSrc = (apt) => {
    const photo = apt?.counselor?.profilePhoto;
    if (photo) {
      return typeof photo === "string" ? photo : photo.url;
    }

    const name = apt?.counselor?.fullName || "Counselor";
    return `https://ui-avatars.com/api/?name=${encodeURIComponent(name)}&background=0f172a&color=ffffff&bold=true`;
  };

  // ---- Derived values for the details sheet ----
  const aptDate = Number.isFinite(Date.parse(selectedApt?.date)) ? new Date(selectedApt.date) : null;
  const isToday = aptDate ? aptDate.toDateString() === new Date().toDateString() : false;
  const dayLabel = aptDate ? (isToday ? "Today" : aptDate.toLocaleDateString("en-US", { weekday: "short" })) : "";
  const timeLabel = aptDate ? aptDate.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }) : "-";
  const dateLabel = aptDate ? aptDate.toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric", year: "numeric" }) : "-";
  const statusRaw = selectedApt?.status || "pending";
  const statusLower = String(statusRaw).toLowerCase();
  const statusCap = statusLower.charAt(0).toUpperCase() + statusLower.slice(1);
  const selectedIsClinicVisit = isDoctorClinicVisit(selectedApt);
  const modeLabel = selectedIsClinicVisit
    ? t('In-Clinic Visit')
    : selectedApt?.mode || selectedApt?.sessionType || "Video Call";
  const actualDurationMinutes = getActualDurationMinutes(selectedApt);
  const slotDurationMinutes = getScheduledDurationMinutes(selectedApt);
  const isCompletedApt = statusLower === 'completed';
  // Once it's done, show how long it actually ran; before that, show the slot
  // length the doctor gave. Never a hard-coded figure.
  const durationMinutes = isCompletedApt
    ? (actualDurationMinutes ?? slotDurationMinutes)
    : slotDurationMinutes;
  const durationLabel = formatDurationLabel(durationMinutes);
  const aptTime = aptDate?.getTime?.() ?? NaN;
  const hasValidAptTime = Number.isFinite(aptTime);
  const sessionHasStarted = hasValidAptTime && aptTime <= Date.now();
  // A clinic visit runs on the token queue, not the booked minute: the patient
  // can still be waiting after that time, so only a final status ends it.
  const isPast = TERMINAL_APT_STATUSES.has(normalizeAptStatus(statusLower))
    || (!selectedIsClinicVisit && sessionHasStarted && !isUnscheduledEmergency(selectedApt));
  const isJoinDisabled = !sessionHasStarted || statusLower === "completed" || statusLower === "canceled";
  // Real talk time for the "Session Completed" banner.
  const talkTimeLabel = formatDurationLabel(actualDurationMinutes ?? slotDurationMinutes);
  // Only claim "Ended" when a real end time exists; otherwise say what the time
  // actually is (the booked slot) instead of mislabelling it as the end.
  const actualEndDate = getActualEndDate(selectedApt);
  const endedTimeLabel = actualEndDate
    ? actualEndDate.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    : timeLabel;

  // ---- Live token queue (clinic visits only) ----
  const clinicQueue = useClinicQueue(selectedApt, showDetailsModal && selectedIsClinicVisit && !isPast);
  const queueToken = clinicQueue.item?.token || {};
  const queueCurrent = clinicQueue.item?.current || {};
  const queueInfo = clinicQueue.item?.queue || {};
  const myTokenNo = queueToken.myToken ?? clinicQueue.fallbackToken;
  const nowServingNo = queueCurrent.currentToken;
  const queueTiming = getLiveTokenTiming(queueCurrent, queueInfo, clinicQueue.now);
  const queueWait = queueTiming.waiting != null
    ? formatTimer(queueTiming.waiting)
    : showQueueValue(queueInfo.estimatedWaitMinutes, ' min');
  const queueStatusText = queueCurrent.isYourTurn
    ? t("It's your turn! Please go to the doctor's cabin.")
    : queueCurrent.doctorStatus === 'consulting'
      ? t('Doctor is consulting. Please wait for your token.')
      : queueCurrent.doctorStatus === 'paused' || queueCurrent.doctorStatus === 'break'
        ? t('Doctor is on a short break. The queue will resume soon.')
        : t('Consultation has not started yet.');
  // Live "your turn in" countdown (HH:MM:SS, ticks every second on server
  // time). The queue ETA moves as patients are seen, but a turn never comes
  // before the booked time, so the later of the two is counted down to.
  const queueEtaMs = Date.parse(queueInfo.estimatedTurnTime);
  const turnTargetMs = Math.max(
    hasValidAptTime ? aptTime : -Infinity,
    Number.isFinite(queueEtaMs) ? queueEtaMs : -Infinity,
  );
  const turnLeftSec = Number.isFinite(turnTargetMs)
    ? Math.max(0, Math.floor((turnTargetMs - clinicQueue.now) / 1000))
    : null;
  const turnCountdown = turnLeftSec == null
    ? '--:--:--'
    : [Math.floor(turnLeftSec / 3600), Math.floor((turnLeftSec % 3600) / 60), turnLeftSec % 60]
      .map((n) => String(n).padStart(2, '0')).join(':');
  const turnCountdownLabel = queueCurrent.isYourTurn
    ? t("It's your turn now")
    : turnLeftSec === 0
      ? t('Your turn is coming up any moment')
      : t('Your turn in');
  const clinicName = selectedApt?.clinic?.name || selectedApt?.clinic?.clinic_name
    || (typeof selectedApt?.clinic === 'string' ? selectedApt.clinic : '') || selectedApt?.clinic_name || '';

  return (
    <View style={styles.appointmentsRoot}>
      {/* Tabs + Filter bar */}
      <View style={styles.appointmentsTopBar}>
        <View style={styles.appointmentsTabRow}>
          {["All", "Upcoming", "Past"].map((tab) => (
            <TouchableOpacity
              key={tab}
              onPress={() => setActiveTab(tab)}
              style={[styles.aptTabBtn, activeTab === tab && styles.aptTabBtnActive]}
            >
              {activeTab === tab && (
                <LinearGradient
                  colors={[PATIENT.gradientFrom, PATIENT.gradientTo]}
                  start={{ x: 0, y: 0.5 }}
                  end={{ x: 1, y: 0.5 }}
                  style={StyleSheet.absoluteFillObject}
                />
              )}
              <Text style={[styles.aptTabText, activeTab === tab && styles.aptTabTextActive]}>{t(tab)}</Text>
            </TouchableOpacity>
          ))}
        </View>

        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          contentContainerStyle={styles.appointmentFilterRow}
        >
          {[
            { key: "All", label: t('common:all', 'All') },
            { key: "Pending", label: t('common:pending', 'Pending') },
            { key: "Confirmed", label: t('common:confirmed', 'Confirmed') },
            { key: "Completed", label: t('appointment:completed', 'completed') },
          ].map((chip) => (
            <TouchableOpacity
              key={chip.key}
              style={[styles.filterChip, statusFilter === chip.key && styles.filterChipActive]}
              onPress={() => setStatusFilter(chip.key)}
              activeOpacity={0.8}
            >
              {statusFilter === chip.key && (
                <LinearGradient
                  colors={[PATIENT.gradientFrom, PATIENT.gradientTo]}
                  start={{ x: 0, y: 0.5 }}
                  end={{ x: 1, y: 0.5 }}
                  style={StyleSheet.absoluteFillObject}
                />
              )}
              <Text style={[styles.filterChipText, statusFilter === chip.key && styles.filterChipTextActive]}>
                {chip.label}
              </Text>
            </TouchableOpacity>
          ))}
        </ScrollView>
      </View>

      <ScrollView contentContainerStyle={styles.appointmentsList} showsVerticalScrollIndicator={false}>
        {hasCompletedDoctorVisit && <HealthVitalsCard />}
        {loadingAppointments ? (
          <AppointmentsSkeleton />
        ) : displayApts.length === 0 ? (
          <View style={styles.appointmentEmptyCard}>
            <MaterialIcons name="event-busy" size={40} color="#A7E3BE" />
            <Text style={styles.appointmentEmptyTitle}>{t('No appointments found')}</Text>
            <Text style={styles.appointmentEmptySubtitle}>
              {t('Try changing filters or book a new session with a consultant.')}
            </Text>
          </View>
        ) : (
          <>
          {selectedProviderKey && selectedProvider && (
            <View style={styles.providerHistoryHeader}>
              <TouchableOpacity style={styles.providerBackBtn} onPress={() => setSelectedProviderKey(null)}>
                <Ionicons name="arrow-back" size={17} color={PATIENT.primary} />
                <Text style={styles.providerBackText}>{t('Back to doctors & consultants')}</Text>
              </TouchableOpacity>
              <View style={styles.providerHistoryPerson}>
                <Image source={{ uri: getAvatarSrc(selectedProvider.latest) }} style={styles.providerHistoryAvatar} />
                <View style={{ flex: 1 }}>
                  <Text style={styles.providerHistoryName} numberOfLines={1}>{selectedProvider.latest?.counselor?.fullName || t('Provider unavailable')}</Text>
                  <Text style={styles.providerHistoryMeta}>{selectedProvider.appointments.length} {selectedProvider.appointments.length === 1 ? t('appointment') : t('appointments')}</Text>
                </View>
              </View>
            </View>
          )}
          {!selectedProviderKey ? providerGroups.map((provider) => {
            const sample = provider.latest;
            const name = sample?.counselor?.fullName || t('Provider unavailable');
            const completed = provider.appointments.filter((appointment) => String(appointment.status).toLowerCase() === 'completed').length;
            return (
              <TouchableOpacity key={provider.key} style={styles.providerCard} onPress={() => setSelectedProviderKey(provider.key)} activeOpacity={0.85}>
                <Image source={{ uri: getAvatarSrc(sample) }} style={styles.providerCardAvatar} />
                <View style={styles.providerCardBody}>
                  <Text style={styles.providerCardName} numberOfLines={1}>{name}</Text>
                  <Text style={styles.providerCardSpec} numberOfLines={1}>{sample?.counselor?.specialization || t('Medical specialist')}</Text>
                  <View style={styles.providerCardStats}>
                    <Text style={styles.providerCardStat}>{provider.appointments.length} {provider.appointments.length === 1 ? t('appointment') : t('appointments')}</Text>
                    <Text style={styles.providerCardStat}>{completed} {t('completed')}</Text>
                  </View>
                </View>
                <Ionicons name="chevron-forward" size={20} color={PATIENT.primary} />
              </TouchableOpacity>
            );
          }) : selectedProviderAppointments.map((apt) => {
            const aptStatus = String(apt.status || 'pending').toLowerCase();
            const doctorAppointment = isDoctorAppointment(apt, doctorIds);
            const doctorActionable = doctorAppointment && !TERMINAL_APT_STATUSES.has(normalizeAptStatus(aptStatus));
            const aptHasDate = Number.isFinite(Date.parse(apt.date));
            const aptDateObj = aptHasDate ? new Date(apt.date) : null;
            const aptExperience = formatExperience(apt?.counselor?.experience);
            const aptSpecialization = String(apt?.counselor?.specialization || '').trim();
            return (
            <View key={apt._id} style={styles.appointmentCard}>
              <View style={styles.appointmentCardHeader}>
                <View style={styles.aptAvatarWrap}>
                  <Image source={{ uri: getAvatarSrc(apt) }} style={styles.appointmentAvatar} />
                </View>
                <View style={styles.appointmentMetaColumn}>
                  <View style={styles.aptNameRow}>
                    <Text style={styles.appointmentDoctorName} numberOfLines={1}>
                      {apt?.counselor?.fullName || "Counselor"}
                    </Text>
                  </View>
                  <Text style={styles.appointmentSpecialization} numberOfLines={1}>
                    {aptSpecialization || t('Mental Wellness Specialist')}
                  </Text>
                  <View style={styles.aptMetaRow}>
                    {!!aptExperience && (
                      <>
                        <Ionicons name="briefcase-outline" size={12} color={PATIENT.textSecondary} />
                        <Text style={styles.aptMetaText}>
                          {aptExperience}
                        </Text>
                      </>
                    )}
                    {Number(apt?.counselor?.rating) > 0 ? (
                      <>
                        <Ionicons name="star" size={12} color="#F5A623" style={{ marginLeft: 10 }} />
                        <Text style={styles.aptMetaText}>
                          {Number(apt.counselor.rating).toFixed(1)}
                        </Text>
                      </>
                    ) : (
                      <View style={[styles.newRatingBadge, !aptExperience && styles.newRatingBadgeFirst]}>
                        <Ionicons name="sparkles" size={10} color={PATIENT.gradientTo} />
                        <Text style={styles.newRatingText}>{t('counselor:newRating', 'New')}</Text>
                      </View>
                    )}
                  </View>
                </View>
                <View style={[styles.aptStatusPill, getStatusStyle(aptStatus)]}>
                  <Ionicons
                    name={getStatusIcon(aptStatus)}
                    size={12}
                    color={getStatusTextColor(aptStatus)}
                  />
                  <Text style={[styles.aptStatusText, { color: getStatusTextColor(aptStatus) }]}>
                    {aptStatus}
                  </Text>
                </View>
              </View>

              {/* Date & time in a soft tinted strip, each with a small label. */}
              <View style={styles.aptInfoStrip}>
                <View style={styles.aptInfoItem}>
                  <View style={styles.aptDateIconWrap}>
                    <MaterialIcons name="event" size={16} color={PATIENT.primary} />
                  </View>
                  <View style={styles.aptInfoTextWrap}>
                    <Text style={styles.aptInfoLabel}>{t('Date')}</Text>
                    <Text style={styles.appointmentDateText} numberOfLines={1}>
                      {aptDateObj
                        ? aptDateObj.toLocaleDateString("en-US", {
                          weekday: "short",
                          month: "short",
                          day: "numeric",
                          // Year only when it isn't this year, so the date fits.
                          ...(aptDateObj.getFullYear() !== new Date().getFullYear() && { year: "numeric" }),
                        })
                        : t('Emergency request')}
                    </Text>
                  </View>
                </View>
                <View style={styles.aptInfoDivider} />
                <View style={styles.aptInfoItem}>
                  <View style={styles.aptDateIconWrap}>
                    <MaterialIcons name="access-time" size={16} color={PATIENT.primary} />
                  </View>
                  <View style={styles.aptInfoTextWrap}>
                    <Text style={styles.aptInfoLabel}>{t('Time')}</Text>
                    <Text style={styles.appointmentDateText} numberOfLines={1}>
                      {isUnscheduledEmergency(apt) || !aptHasDate
                        ? t('Clinic will confirm')
                        : new Date(apt.date).toLocaleTimeString([], {
                          hour: "2-digit",
                          minute: "2-digit",
                        })}
                    </Text>
                  </View>
                </View>
              </View>

              <View style={styles.appointmentActionRow}>
                <TouchableOpacity
                  style={styles.appointmentDetailsBtn}
                  onPress={() => {
                    setSelectedApt(apt);
                    setShowDetailsModal(true);
                  }}
                >
                  <Ionicons name="eye-outline" size={16} color={PATIENT.primary} />
                  <Text style={styles.appointmentDetailsText}>
                    {t('counselor:viewDetails', 'View Details')}
                  </Text>
                </TouchableOpacity>

                {/* Quick Video / Voice only on a doctor's video/voice
                    consultation. Consultant cards show just View Details (their
                    video, voice and chat are inside the details sheet), and a
                    doctor's in-clinic visit is in person. */}
                {doctorAppointment && aptStatus === 'completed' && (
                  <TouchableOpacity
                    style={[styles.aptRateBtn, apt.doctorRating && styles.aptRateBtnDone]}
                    onPress={() => openDoctorRating(apt)}
                    disabled={Boolean(apt.doctorRating)}
                    activeOpacity={0.8}
                  >
                    <Ionicons
                      name={apt.doctorRating ? 'checkmark-circle' : 'star'}
                      size={15}
                      color={apt.doctorRating ? PATIENT.primary : '#D97706'}
                    />
                    <Text style={[styles.aptRateText, apt.doctorRating && styles.aptRateTextDone]} numberOfLines={1}>
                      {apt.doctorRating
                        ? `${t('Rated')} (${Number(apt.doctorRating.stars ?? apt.doctorRating.rating) || 0}/5)`
                        : t('Rate Doctor')}
                    </Text>
                  </TouchableOpacity>
                )}
                {doctorAppointment && !isDoctorClinicVisit(apt) && aptStatus !== 'completed' && (
                  <>
                    <TouchableOpacity
                      style={styles.aptActionIconBtn}
                      onPress={() => onVideoCall && onVideoCall(apt)}
                      activeOpacity={0.7}
                    >
                      <Ionicons name="videocam-outline" size={19} color={PATIENT.primary} />
                    </TouchableOpacity>

                    <TouchableOpacity
                      style={styles.aptActionIconBtn}
                      onPress={() => onVoiceCall && onVoiceCall(apt)}
                      activeOpacity={0.7}
                    >
                      <Ionicons name="call-outline" size={19} color={PATIENT.primary} />
                    </TouchableOpacity>
                  </>
                )}
              </View>
              {doctorActionable && (
                <View style={styles.doctorAppointmentActionRow}>
                  {canCancelUserAppointment(apt) && (
                    <TouchableOpacity
                      style={[styles.doctorCancelBtn, actionLoading && styles.actionDisabled]}
                      onPress={() => cancelAppointment(apt)}
                      disabled={Boolean(actionLoading)}
                    >
                      <Ionicons name="close-circle-outline" size={16} color="#B42318" />
                      <Text style={styles.doctorCancelText}>{actionLoading === `cancel-${getAppointmentIdentity(apt)}` ? t('Cancelling...') : t('Cancel')}</Text>
                    </TouchableOpacity>
                  )}
                  <TouchableOpacity
                    style={[styles.doctorEmergencyBtn, isEmergencyAppointment(apt) && styles.doctorEmergencySent]}
                    onPress={() => { setEmergencyError(''); setEmergencyAppointment(apt); }}
                    disabled={isEmergencyAppointment(apt) || Boolean(actionLoading)}
                  >
                    <Ionicons name={isEmergencyAppointment(apt) ? 'checkmark-circle' : 'warning-outline'} size={16} color={isEmergencyAppointment(apt) ? '#9F1239' : '#B42318'} />
                    <Text style={[styles.doctorEmergencyText, isEmergencyAppointment(apt) && styles.doctorEmergencySentText]}>
                      {isEmergencyAppointment(apt) ? t('Emergency sent') : t('Emergency')}
                    </Text>
                  </TouchableOpacity>
                </View>
              )}
            </View>
            );
          })}
          </>
        )}
      </ScrollView>

      {ratingApt && (
        <RatingModal
          key={getAppointmentIdentity(ratingApt)}
          visible
          professionalType="doctor"
          counselorName={ratingApt?.counselor?.fullName || ratingApt?.counselor?.name || ratingApt?.doctor?.fullName || ratingApt?.doctor?.name || t('your doctor')}
          counselorPhoto={ratingApt?.counselor?.profilePhoto || ratingApt?.doctor?.profilePhoto}
          submitting={ratingBusy}
          success={ratingSuccess}
          error={ratingError}
          onSubmit={submitDoctorRating}
          onClose={() => { if (!ratingBusy) setRatingApt(null); }}
        />
      )}

      <PatientEmergencyModal
        visible={Boolean(emergencyAppointment)}
        appointment={emergencyAppointment}
        busy={emergencyBusy}
        error={emergencyError}
        onClose={() => { if (!emergencyBusy) setEmergencyAppointment(null); }}
        onSubmit={submitEmergency}
      />

      <Modal statusBarTranslucent navigationBarTranslucent
        transparent={true}
        visible={showDetailsModal}
        animationType="slide"
        onRequestClose={() => setShowDetailsModal(false)}
      >
        <View style={sheetStyles.overlay}>
          <View style={[sheetStyles.backdrop, { paddingTop: Math.max(sheetInsets.top, 24) }]}>
            <TouchableWithoutFeedback onPress={() => setShowDetailsModal(false)}>
              <View style={{ flex: 1 }} />
            </TouchableWithoutFeedback>
          </View>

          <View style={[sheetStyles.sheet, { maxHeight: sheetMaxHeight }]}>
            <View style={sheetStyles.grabber} />

            {/* Header */}
            <View style={sheetStyles.header}>
              <View style={{ flex: 1 }}>
                <Text style={sheetStyles.title}>{t('Appointment Details')}</Text>
                <Text style={sheetStyles.subtitle}>{t('View your session information')}</Text>
              </View>
              <TouchableOpacity
                onPress={() => setShowDetailsModal(false)}
                style={sheetStyles.closeBtn}
                hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
              >
                <MaterialIcons name="close" size={20} color="#334155" />
              </TouchableOpacity>
            </View>

            <ScrollView
              style={[sheetStyles.scrollView, { maxHeight: sheetScrollMaxHeight }]}
              contentContainerStyle={[
                sheetStyles.scroll,
                { paddingBottom: Math.max(sheetInsets.bottom, 12) + 12 },
              ]}
              showsVerticalScrollIndicator={false}
              keyboardShouldPersistTaps="handled"
              bounces={false}
            >
              {/* Counselor card */}
              <View style={sheetStyles.docCard}>
                <Image source={{ uri: getAvatarSrc(selectedApt) }} style={sheetStyles.docAvatar} />
                <View style={{ flex: 1 }}>
                  <View style={sheetStyles.docNameRow}>
                    <Text style={sheetStyles.docName} numberOfLines={1}>
                      {counselorDisplayName(selectedApt)}
                    </Text>
                  </View>
                  <Text style={sheetStyles.docSpec} numberOfLines={1}>
                    {String(selectedApt?.counselor?.specialization || '').trim() || t('Mental Wellness Specialist')}
                  </Text>
                  <View style={sheetStyles.docMetaRow}>
                    {!!formatExperience(selectedApt?.counselor?.experience) && (
                      <>
                        <Ionicons name="briefcase-outline" size={12} color={PATIENT.textSecondary} />
                        <Text style={sheetStyles.docMetaText}>
                          {formatExperience(selectedApt?.counselor?.experience)}
                        </Text>
                      </>
                    )}
                    {Number(selectedApt?.counselor?.rating) > 0 ? (
                      <>
                        <Ionicons name="star" size={12} color="#F5A623" style={{ marginLeft: 10 }} />
                        <Text style={sheetStyles.docMetaText}>
                          {Number(selectedApt.counselor.rating).toFixed(1)}
                        </Text>
                      </>
                    ) : (
                      <View
                        style={[
                          styles.newRatingBadge,
                          !formatExperience(selectedApt?.counselor?.experience) && styles.newRatingBadgeFirst,
                        ]}
                      >
                        <Ionicons name="sparkles" size={10} color={PATIENT.gradientTo} />
                        <Text style={styles.newRatingText}>{t('counselor:newRating', 'New')}</Text>
                      </View>
                    )}
                  </View>
                </View>
                <View style={sheetStyles.confirmPill}>
                  <View style={sheetStyles.confirmDot} />
                  <Text style={sheetStyles.confirmText}>{statusCap}</Text>
                </View>
              </View>

              {/* Live token queue (clinic visit) OR Countdown banner (upcoming)
                  OR Session summary (past) */}
              {!isPast && selectedIsClinicVisit ? (
                <View style={sheetStyles.queueCard}>
                  <View style={sheetStyles.queueHeadRow}>
                    <View style={{ flex: 1 }}>
                      <Text style={sheetStyles.queueHeadLabel}>{t('Your Token')}</Text>
                      <Text style={sheetStyles.queueTokenValue}>
                        {myTokenNo != null ? `#${myTokenNo}` : '--'}
                      </Text>
                    </View>
                    <View style={sheetStyles.queueServingBox}>
                      <Text style={sheetStyles.queueServingLabel}>{t('Now Serving')}</Text>
                      <Text style={sheetStyles.queueServingValue}>
                        {nowServingNo != null ? `#${nowServingNo}` : '--'}
                      </Text>
                    </View>
                  </View>

                  <View style={sheetStyles.queueCountdownRow}>
                    <LinearGradient
                      colors={[PATIENT.gradientFrom, PATIENT.gradientTo]}
                      style={sheetStyles.countIcon}
                    >
                      <Ionicons name="time-outline" size={22} color="#ffffff" />
                    </LinearGradient>
                    <View style={{ flex: 1 }}>
                      <Text style={sheetStyles.countLabel}>{turnCountdownLabel}</Text>
                      <Text style={sheetStyles.countValue}>
                        {queueCurrent.isYourTurn ? '00:00:00' : turnCountdown}
                      </Text>
                    </View>
                    <View style={{ alignItems: "flex-end" }}>
                      <Text style={sheetStyles.countDay}>{dayLabel}</Text>
                      <Text style={sheetStyles.countTime}>{timeLabel}</Text>
                    </View>
                  </View>

                  <View style={[sheetStyles.queueStatusRow, queueCurrent.isYourTurn && sheetStyles.queueStatusRowTurn]}>
                    {clinicQueue.loading && !clinicQueue.item ? (
                      <ActivityIndicator size="small" color={PATIENT.primary} />
                    ) : (
                      <Ionicons
                        name={queueCurrent.isYourTurn ? 'notifications' : 'hourglass-outline'}
                        size={16}
                        color={queueCurrent.isYourTurn ? '#ffffff' : PATIENT.primary}
                      />
                    )}
                    <Text style={[sheetStyles.queueStatusText, queueCurrent.isYourTurn && sheetStyles.queueStatusTextTurn]}>
                      {clinicQueue.loading && !clinicQueue.item ? t('Loading live queue...') : queueStatusText}
                    </Text>
                  </View>

                  <View style={sheetStyles.queueStatsRow}>
                    <View style={sheetStyles.queueStat}>
                      <Text style={sheetStyles.queueStatValue}>{showQueueValue(queueInfo.patientsAhead)}</Text>
                      <Text style={sheetStyles.queueStatLabel}>{t('People ahead')}</Text>
                    </View>
                    <View style={sheetStyles.queueStat}>
                      <Text style={sheetStyles.queueStatValue}>{queueWait}</Text>
                      <Text style={sheetStyles.queueStatLabel}>{t('Est. wait')}</Text>
                    </View>
                    <View style={sheetStyles.queueStat}>
                      <Text style={sheetStyles.queueStatValue}>{formatTurnTime(queueInfo.estimatedTurnTime)}</Text>
                      <Text style={sheetStyles.queueStatLabel}>{t('Expected turn')}</Text>
                    </View>
                  </View>

                  {!clinicQueue.loading && !clinicQueue.item && (
                    <Text style={sheetStyles.queueNote}>
                      {t('Live queue starts on your appointment day once the clinic opens.')}
                    </Text>
                  )}
                  {!!clinicName && (
                    <View style={sheetStyles.queueClinicRow}>
                      <Ionicons name="business-outline" size={13} color="#64748b" />
                      <Text style={sheetStyles.queueClinicText} numberOfLines={1}>{clinicName}</Text>
                    </View>
                  )}
                </View>
              ) : !isPast ? (
                <View style={sheetStyles.countBanner}>
                  <LinearGradient
                    colors={[PATIENT.gradientFrom, PATIENT.gradientTo]}
                    style={sheetStyles.countIcon}
                  >
                    <Ionicons name="time-outline" size={22} color="#ffffff" />
                  </LinearGradient>
                  <View style={{ flex: 1 }}>
                    <Text style={sheetStyles.countLabel}>{t('Session starts in')}</Text>
                    <Text style={sheetStyles.countValue}>{countdown || "--:--:--"}</Text>
                  </View>
                  <View style={{ alignItems: "flex-end" }}>
                    <Text style={sheetStyles.countDay}>{dayLabel}</Text>
                    <Text style={sheetStyles.countTime}>{timeLabel}</Text>
                  </View>
                </View>
              ) : (
                <View style={sheetStyles.pastBanner}>
                  <LinearGradient
                    colors={["#10b98133", "#34d39933"]}
                    style={sheetStyles.pastIcon}
                  >
                    <Ionicons name="checkmark-circle" size={22} color="#10b981" />
                  </LinearGradient>
                  <View style={{ flex: 1 }}>
                    <Text style={sheetStyles.pastLabel}>
                      {selectedIsClinicVisit ? t('Visit') : t('Session Completed')}
                    </Text>
                    <Text style={sheetStyles.pastValue}>
                      {selectedIsClinicVisit ? statusCap : `${t('Talk time')}: ${talkTimeLabel}`}
                    </Text>
                  </View>
                  <View style={{ alignItems: "flex-end" }}>
                    <Text style={sheetStyles.pastDay}>
                      {actualEndDate ? t('Ended') : t('Scheduled')}
                    </Text>
                    <Text style={sheetStyles.pastTime}>{endedTimeLabel}</Text>
                  </View>
                </View>
              )}

              {/* Info grid */}
              <View style={sheetStyles.gridRow}>
                <View style={sheetStyles.gridCell}>
                  <View style={[sheetStyles.gridIcon, { backgroundColor: "#E7EEFE" }]}>
                    <MaterialIcons name="event" size={18} color="#2563EB" />
                  </View>
                  <Text style={sheetStyles.gridLabel}>{t('DATE')}</Text>
                  <Text style={sheetStyles.gridValue} numberOfLines={2}>{dateLabel}</Text>
                </View>
                <View style={sheetStyles.gridCell}>
                  <View style={[sheetStyles.gridIcon, { backgroundColor: "#E6F6EC" }]}>
                    <MaterialIcons name="schedule" size={18} color={PATIENT.primary} />
                  </View>
                  <Text style={sheetStyles.gridLabel}>{t('TIME')}</Text>
                  <Text style={sheetStyles.gridValue} numberOfLines={2}>{timeLabel}</Text>
                </View>
              </View>

              <View style={sheetStyles.gridRow}>
                <View style={sheetStyles.gridCell}>
                  <View style={[sheetStyles.gridIcon, { backgroundColor: "#F1EAFE" }]}>
                    <MaterialIcons name="laptop-mac" size={18} color="#7C3AED" />
                  </View>
                  <Text style={sheetStyles.gridLabel}>{t('MODE')}</Text>
                  <Text style={sheetStyles.gridValue} numberOfLines={2}>{modeLabel}</Text>
                </View>
                <View style={sheetStyles.gridCell}>
                  <View style={[sheetStyles.gridIcon, { backgroundColor: "#FEF3E2" }]}>
                    <MaterialIcons name="timer" size={18} color="#F59E0B" />
                  </View>
                  <Text style={sheetStyles.gridLabel}>
                    {isCompletedApt ? t('DURATION') : t('SLOT DURATION')}
                  </Text>
                  <Text style={sheetStyles.gridValue} numberOfLines={2}>{durationLabel}</Text>
                </View>
              </View>

              {!isPast && !selectedIsClinicVisit ? (
                <View style={sheetStyles.inlineFooter}>
                  <TouchableOpacity
                    activeOpacity={isJoinDisabled ? 1 : 0.9}
                    disabled={isJoinDisabled}
                    onPress={() => {
                      if (isJoinDisabled) return;
                      const apt = selectedApt;
                      setShowDetailsModal(false);
                      setTimeout(() => onVideoCall && onVideoCall(apt), MODAL_DISMISS_MS);
                    }}
                  >
                    <LinearGradient
                      colors={isJoinDisabled ? ['#94a3b8', '#cbd5e1'] : [PATIENT.gradientFrom, PATIENT.gradientTo]}
                      start={{ x: 0, y: 0 }}
                      end={{ x: 1, y: 0 }}
                      style={[sheetStyles.joinBtn, isJoinDisabled && sheetStyles.joinBtnDisabled]}
                    >
                      <Ionicons name="videocam" size={20} color="#ffffff" />
                      <Text style={sheetStyles.joinText}>{t('Join Video Session')}</Text>
                    </LinearGradient>
                  </TouchableOpacity>

                  <View style={sheetStyles.secRow}>
                    {!isDoctorAppointment(selectedApt, doctorIds) && (
                      <TouchableOpacity
                        style={sheetStyles.secBtn}
                        activeOpacity={0.85}
                        onPress={() => {
                          const apt = selectedApt;
                          setShowDetailsModal(false);
                          setTimeout(() => onChat && onChat(apt), MODAL_DISMISS_MS);
                        }}
                      >
                        <Ionicons name="chatbubble-ellipses" size={17} color="#F59E0B" />
                        <Text style={sheetStyles.secText}>{t('Chat')}</Text>
                      </TouchableOpacity>
                    )}
                    <TouchableOpacity
                      style={sheetStyles.secBtn}
                      activeOpacity={0.85}
                      onPress={() => {
                        const apt = selectedApt;
                        setShowDetailsModal(false);
                        setTimeout(() => onVoiceCall && onVoiceCall(apt), MODAL_DISMISS_MS);
                      }}
                    >
                      <Ionicons name="call" size={17} color={PATIENT.primary} />
                      <Text style={sheetStyles.secText}>{t('Call')}</Text>
                    </TouchableOpacity>
                  </View>
                </View>
              ) : (
                <View style={sheetStyles.inlineFooter}>
                  <TouchableOpacity
                    activeOpacity={0.85}
                    onPress={() => setShowDetailsModal(false)}
                    style={sheetStyles.closePastBtnWrap}
                  >
                    <LinearGradient
                      colors={['#006B2C', '#01CE54']}
                      start={{ x: 0, y: 0.5 }}
                      end={{ x: 1, y: 0.5 }}
                      style={sheetStyles.closePastBtn}
                    >
                      <Text style={sheetStyles.closePastText}>{t('Close')}</Text>
                    </LinearGradient>
                  </TouchableOpacity>
                </View>
              )}

            </ScrollView>
          </View>
        </View>
      </Modal>
    </View>
  );
};

export default function UserDashboard() {
  const { width: windowWidth, height: windowHeight } = useContentDimensions();
  const [avatarFailed, setAvatarFailed] = useState(false);
  // The bottom tab bar had a fixed paddingBottom (6 on Android), so on a phone
  // with gesture navigation its labels were clipped by the gesture bar.
  const navInsets = useSafeAreaInsets();
  const androidStatusInset = Platform.OS === 'android'
    ? Math.max(navInsets.top, StatusBar.currentHeight || 0)
    : 0;
  const androidVisibleBottomInset = Platform.OS === 'android'
    ? Math.max(0, Dimensions.get('screen').height - windowHeight - androidStatusInset)
    : 0;
  const androidNavInsetFallback = Platform.OS === 'android'
    ? (androidVisibleBottomInset <= 80 ? androidVisibleBottomInset : 0)
    : 0;
  const androidStableBottomInset = Platform.OS === 'android'
    ? (navInsets.bottom <= 80 ? navInsets.bottom : 0)
    : navInsets.bottom;
  const dashboardBottomInset = Math.max(androidStableBottomInset, androidNavInsetFallback, 0);
  const sidebarTopInset = Platform.OS === 'android' ? androidStatusInset : navInsets.top;
  const bottomNavHeight = (Platform.OS === 'ios' ? 84 : 68) + dashboardBottomInset;
  const bottomNavPaddingBottom = (Platform.OS === 'ios' ? 20 : 6) + dashboardBottomInset;
  const aiButtonBottom = (Platform.OS === "ios" ? 42 : 28) + dashboardBottomInset;
  const { i18n } = useTranslation();
  const { t } = useLanguageRender();
  const { setToastRole } = useToast();
  const navigation = useNavigation();
  const route = useRoute();
  const isFocused = useIsFocused();

  useEffect(() => {
    setToastRole('user');
  }, [setToastRole]);

  const [active, setActive] = useState("Chat");
  const [chatOpen, setChatOpen] = useState(false);
  const [newMessage, setNewMessage] = useState("");
  const [targetCounselor, setTargetCounselor] = useState("");
  const [openCounselorRequestTarget, setOpenCounselorRequestTarget] = useState("");
  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);
  const [loggingOut, setLoggingOut] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [deletingAccount, setDeletingAccount] = useState(false);
  const [deleteSuccess, setDeleteSuccess] = useState(false);
  const isMobile = windowWidth <= 768;
  const [isLoading, setIsLoading] = useState(false);
  const [aiSessionId, setAiSessionId] = useState(null);
  const [showMoreModal, setShowMoreModal] = useState(false);
  // Which sidebar entry to highlight when that entry opens a modal instead of a
  // tab. Profile / Call history / Settings can just read `active`, but Help and
  // Privacy have no tab of their own, so their selection is remembered here.
  const [sidebarSection, setSidebarSection] = useState(null);
  // Visited tabs, most recent last. Drives back navigation between tabs.
  const tabHistoryRef = useRef([]);
  // True while a screen opened from the sidebar is showing.
  const cameFromSidebarRef = useRef(false);
  // True when the sidebar is on screen only because a back press re-opened it.
  // The screen sitting behind it is then the one the user just backed out of,
  // so the next back must skip past it instead of landing on it again.
  const sidebarViaBackRef = useRef(false);
  const [showHelpSupport, setShowHelpSupport] = useState(false);
  const [walletInitialTab, setWalletInitialTab] = useState('add-money');
  const [showNotifications, setShowNotifications] = useState(false);
  const [showQrScanner, setShowQrScanner] = useState(false);
  // A scanned doctor QR opens the walk-in booking form directly (instead of
  // just showing the link). { doctorId, source } | null
  const [walkInBooking, setWalkInBooking] = useState(null);
  const handleQrScanned = useCallback((value) => {
    const walkIn = parseWalkInQr(value);
    setShowQrScanner(false);
    const showScanError = (title, message) => setTimeout(() => {
      Alert.alert(title, message, [
        { text: t('Close'), style: 'cancel' },
        { text: t('Scan Again'), onPress: () => setShowQrScanner(true) },
      ]);
    }, MODAL_DISMISS_MS);

    // Clinic walk-in QR (https://…/walkin/<doctorClinicId>): look up which
    // doctor and clinic it belongs to, then open the same booking form.
    if (walkIn?.doctorClinicId) {
      axios.get(`${API_BASE_URL}/api/qr/walkin/${encodeURIComponent(walkIn.doctorClinicId)}`)
        .then(({ data }) => {
          const info = data?.data || {};
          const doctorId = info.doctorId || info.doctor?.id;
          if (!doctorId) throw new Error('missing doctor');
          // The QR belongs to ONE clinic — book there, never at another one.
          const clinicId = info.clinicId || info.clinic_id || info.clinic?._id || info.clinic?.id;
          setWalkInBooking({
            doctorId: String(doctorId),
            clinicId: clinicId ? String(clinicId) : null,
            clinicName: String(info.clinicName || info.clinic?.name || info.clinic?.clinic_name || ''),
            source: 'qr',
          });
        })
        .catch(() => showScanError(
          t('QR not active'),
          t("This clinic's walk-in QR is no longer active. Please ask the clinic reception."),
        ));
      return;
    }
    if (walkIn) {
      // Let the scanner modal finish closing before the form slides in.
      setTimeout(() => setWalkInBooking(walkIn), MODAL_DISMISS_MS);
      return;
    }
    showScanError(
      t('Not a Humaeli QR code'),
      t("Scan the QR code shown at your doctor's clinic to book a walk-in visit."),
    );
  }, [t]);
  const [showPrivacyPolicy, setShowPrivacyPolicy] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);
  // Unread NOTIFICATION count for the header bell (separate from AI-chat unread).
  const [notifUnread, setNotifUnread] = useState(0);
  const [showProfileMenu, setShowProfileMenu] = useState(false);
  const [showResetChatConfirm, setShowResetChatConfirm] = useState(false);
  // Direct booking modal state (opened from appointment "Book Now" button)
  const [showDirectBookingModal, setShowDirectBookingModal] = useState(false);
  const [directBookCounselor, setDirectBookCounselor] = useState(null);
  const [directBookDateTime, setDirectBookDateTime] = useState(new Date());
  const [directBookNotes, setDirectBookNotes] = useState("");
  const [directBookLoading, setDirectBookLoading] = useState(false);
  const [showDirectDatePicker, setShowDirectDatePicker] = useState(false);
  const [showDirectTimePicker, setShowDirectTimePicker] = useState(false);

  // Call Modal States
  const [showCallModal, setShowCallModal] = useState(false);
  const [callType, setCallType] = useState("video");
  const [callerInfo, setCallerInfo] = useState({
    name: "",
    image: null,
    userId: "",
    userName: "",
    callId: "",
    roomId: "",
    waitingDuration: 0,
  });
  const [isVideoModalOpen, setIsVideoModalOpen] = useState(false);
  const [isVoiceModalOpen, setIsVoiceModalOpen] = useState(false);
  const [selectedCall, setSelectedCall] = useState(null);

  const [userId, setUserId] = useState(null);
  const chatBodyRef = useRef(null);
  const headerAnim = useRef(new Animated.Value(0)).current;

  const [userData, setUserData] = useState({
    name: "",
    email: "",
    phone: "",
    profilePhoto: "",
  });

  const [chatMessages, setChatMessages] = useState([]);
  // AI chat language — seeded from the app language so replies match the
  // dashboard language by default.
  const [selectedLang, setSelectedLang] = useState(i18n.language || 'en-IN');
  const [showAvatarChooser, setShowAvatarChooser] = useState(false);
  const [showAvatarBuilder, setShowAvatarBuilder] = useState(false);

  const handleAIContactClick = (name) => {
    setTargetCounselor(name);
    setOpenCounselorRequestTarget("");
    switchDashboardTab("Counselor");
    setChatOpen(false);
  };

  useEffect(() => {
    const params = route?.params || {};
    if (params.openTab !== 'Counselor' || !params.targetCounselor) return;

    const target = String(params.targetCounselor).trim();
    if (!target) return;
    setTargetCounselor(target);
    setOpenCounselorRequestTarget(params.openCounselorRequest ? target : "");
    switchDashboardTab("Counselor");
  }, [route?.params?.openTab, route?.params?.targetCounselor, route?.params?.openCounselorRequest]);

  useEffect(() => {
    fetchUserData();
    Animated.timing(headerAnim, {
      toValue: 1,
      duration: 800,
      useNativeDriver: true,
    }).start();
  }, []);

  // Reload user's language whenever this dashboard gains focus
  useEffect(() => {
    if (isFocused && userId) loadUserLanguage(userId, 'user');
  }, [isFocused, userId]);

  useEffect(() => {
    if (chatOpen) {
      setUnreadCount(0);
    }
  }, [chatOpen]);

  // ── Notification bell: unread count (API) + real-time updates ──
  const fetchNotifUnread = useCallback(async () => {
    try {
      const res = await axiosInstance.get('/api/notifications/unread-count');
      const c =
        res.data?.count ??
        res.data?.unreadCount ??
        res.data?.unread ??
        (typeof res.data === 'number' ? res.data : 0);
      setNotifUnread(Number(c) || 0);
    } catch (e) {
      // silent — bell just won't show a badge
    }
  }, []);

  useEffect(() => {
    fetchNotifUnread();
  }, [fetchNotifUnread]);

  // Re-sync the count whenever the notifications panel closes (marks read there).
  useEffect(() => {
    if (!showNotifications) fetchNotifUnread();
  }, [showNotifications, fetchNotifUnread]);

  // Live push: bump the badge immediately, event name varies by backend.
  useEffect(() => {
    let unsubs = [];
    let mounted = true;
    const onPush = () => { if (mounted) setNotifUnread((c) => c + 1); };
    (async () => {
      try {
        for (const evt of ['notification', 'new-notification', 'notification:new', 'notification-new']) {
          unsubs.push(await socketService.on(evt, onPush));
        }
      } catch (e) { /* socket optional */ }
    })();
    return () => {
      mounted = false;
      unsubs.forEach((off) => { try { off(); } catch {} });
    };
  }, []);

  const startAiChat = useCallback(async (lang) => {
    setIsLoading(true);
    try {
      const response = await axiosInstance.post(
        '/api/ai-chat/send-message',
        {
          message: AI_OPENING_EVENT,
          kind: "opening",
          history: [],
          language: lang,
        }
      );
 
      if (response.data?.success) {
        const responsePayload = response.data?.data || response.data || {};
        if (responsePayload?.sessionId) {
          setAiSessionId(responsePayload.sessionId);
        }

        setChatMessages([
          {
            id: Date.now(),
            // Keep the opening message app-owned so the assistant name remains
            // consistent even if the API is still configured with an older brand.
            text: AI_WELCOME_MESSAGE,
            system: 'welcome',
            sender: "ai",
          },
        ]);
      } else {
        throw new Error("Invalid AI kickoff response");
      }
    } catch (err) {
      console.warn("[AI-CHAT] kickoff failed:", err.message);
      setChatMessages([
        {
          id: Date.now(),
          text: AI_WELCOME_MESSAGE,
          system: 'welcome',
          sender: "ai",
        },
      ]);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    if (!chatOpen) return;
    if (chatMessages.length > 0) return;
    if (isLoading) return;

    void startAiChat(selectedLang);
  }, [chatOpen, chatMessages.length, isLoading, startAiChat, selectedLang]);

  const handleResetChat = useCallback(() => {
    if (isLoading) return;
    setShowResetChatConfirm(true);
  }, [isLoading]);

  const cancelResetChat = useCallback(() => {
    if (isLoading) return;
    setShowResetChatConfirm(false);
  }, [isLoading]);

  const confirmResetChat = useCallback(async () => {
    if (isLoading) return;

    setShowResetChatConfirm(false);
    setIsLoading(true);
    try {
      await axiosInstance.delete('/api/ai-chat/my-history');
    } catch (err) {
      console.warn("[AI-CHAT] reset history failed:", err.message);
    }

    setAiSessionId(null);
    setNewMessage("");
    setChatMessages([]);
    await startAiChat(selectedLang);
  }, [isLoading, startAiChat]);

  const handleLangChange = useCallback(async (newLang) => {
    if (isLoading) return;
    setIsLoading(true);
    try {
      await axiosInstance.delete('/api/ai-chat/my-history');
    } catch (_) {}
    setAiSessionId(null);
    setNewMessage("");
    setChatMessages([]);
    await startAiChat(newLang);
  }, [isLoading, startAiChat]);

  // ── Keep the AI language in sync with the app (dashboard) language ──────────
  // When the user switches the app language, the AI automatically follows: it
  // restarts and replies in that language. No need to use the in-chat picker.
  const syncedAppLangRef = useRef(i18n.language);
  useEffect(() => {
    const syncAiLanguage = (appLang) => {
      if (!appLang || appLang === syncedAppLangRef.current) return;
      syncedAppLangRef.current = appLang;
      setSelectedLang(appLang);
      // If an AI conversation is already open/active, restart it in the new
      // language; otherwise it will start in the new language when next opened.
      if (chatOpen || chatMessages.length > 0) {
        void handleLangChange(appLang);
      }
    };

    i18n.on('languageChanged', syncAiLanguage);
    syncAiLanguage(i18n.language);
    return () => i18n.off('languageChanged', syncAiLanguage);
  }, [i18n, chatOpen, chatMessages.length, handleLangChange]);

  // Track call IDs already handled so the same call never rings twice
  const handledCallIdsRef = useRef(new Set());
  const launchedFromCallPushRef = useRef(false);
  // After a call ends, block polling for 6s so the backend clears the call first
  const pollBlockedUntilRef = useRef(0);
  // Refs so the polling interval never needs to restart when modal state changes
  const showCallModalRef = useRef(false);
  const isVideoModalOpenRef = useRef(false);
  const isVoiceModalOpenRef = useRef(false);
  const activeRef = useRef(active);
  const isFocusedRef = useRef(isFocused);
  // Ref mirror for callerInfo so "still pending" check has stable access
  const callerInfoRef = useRef({ callId: '' });

  // Keep refs in sync with state
  useEffect(() => { showCallModalRef.current = showCallModal; }, [showCallModal]);
  useEffect(() => { isVideoModalOpenRef.current = isVideoModalOpen; }, [isVideoModalOpen]);
  useEffect(() => { isVoiceModalOpenRef.current = isVoiceModalOpen; }, [isVoiceModalOpen]);
  useEffect(() => { activeRef.current = active; }, [active]);
  useEffect(() => { isFocusedRef.current = isFocused; }, [isFocused]);
  useEffect(() => { callerInfoRef.current = callerInfo; }, [callerInfo]);

  // Poll for incoming calls from counselor — single stable interval, never restarts
  useEffect(() => {
    let isMounted = true;

    const fetchIncomingCalls = async () => {
      try {
        if (!isFocusedRef.current) return;
        if (!INCOMING_CALL_POLL_TABS.has(activeRef.current)) return;
        if (Date.now() < pollBlockedUntilRef.current) return;
        if (showCallModalRef.current || isVideoModalOpenRef.current || isVoiceModalOpenRef.current) return;
        if (isGlobalCallUiActive()) return;

        const storedUserId = await AsyncStorage.getItem('userId');
        if (!storedUserId) return;

        const response = await axiosInstance.get(`/api/video/calls/pending/${storedUserId}`);
        if (!isMounted) return;
        if (isGlobalCallUiActive()) return;

        const callsList = response.data.pendingRequests || [];
        if (response.data.success && callsList.length > 0) {
          const waitingCall = callsList[0];
          const callId = waitingCall.callId || waitingCall._id || waitingCall.id;

          // Skip calls we already handled or dismissed
          if (handledCallIdsRef.current.has(callId)) return;

          const fromData = waitingCall.from || {};
          const counselorName =
            fromData.fullName ||
            fromData.name ||
            fromData.displayName ||
            waitingCall.counselorName ||
            waitingCall.counsellorName ||
            'Counselor';

          handledCallIdsRef.current.add(callId);

          const resolvedCallType =
            String(waitingCall.callType || 'video').toLowerCase() === 'audio'
              ? 'voice'
              : 'video';

          setCallerInfo({
            callId,
        roomId: getStreamRoomId(waitingCall),
        streamCallId: getStreamRoomId(waitingCall),
            name: counselorName,
            userName: counselorName,
            image: fromData.profilePhoto || fromData.image || null,
            userId: fromData._id || fromData.id || '',
            callType: resolvedCallType,
            from: fromData,
          });
          setCallType(resolvedCallType);
          startIncomingRingtone(true);
          setShowCallModal(true);
          launchedFromCallPushRef.current = Boolean(
            await AsyncStorage.getItem('pendingIncomingCallPush'),
          );
        }
      } catch (_) {}
    };

    // A full-screen push may have just launched the app; show the incoming
    // call modal immediately instead of waiting for the first 5-second tick.
    fetchIncomingCalls();
    const intervalId = setInterval(fetchIncomingCalls, 5000);

    return () => {
      isMounted = false;
      clearInterval(intervalId);
    };
  }, []);

  // If the counselor cancels/ends the outgoing call while the user's incoming
  // call modal is open, detect that the call is gone and close the modal + stop ring.
  useEffect(() => {
    if (!showCallModal || !callerInfo.callId) return;

    const timeoutId = setTimeout(async () => {
      const shouldExitAfterCall = launchedFromCallPushRef.current;
      launchedFromCallPushRef.current = false;
      forceStopRingtone();
      pollBlockedUntilRef.current = Date.now() + 6000;
      setShowCallModal(false);
      setCallerInfo({ name: '', image: null, userId: '', userName: '', callId: '', roomId: '', waitingDuration: 0 });
      await displayMissedCallNotification(callerInfo, 'missed');
      await AsyncStorage.removeItem('pendingIncomingCallPush');
      if (shouldExitAfterCall && Platform.OS === 'android') {
        setTimeout(() => BackHandler.exitApp(), 100);
      }
    }, INCOMING_RING_TIMEOUT_MS);

    return () => clearTimeout(timeoutId);
  }, [showCallModal, callerInfo.callId]);

  useEffect(() => {
    if (!showCallModal || !callerInfo.callId) return;

    let cancelled = false;

    const checkCallEnded = async () => {
      try {
        const storedUserId = await AsyncStorage.getItem('userId');
        if (!storedUserId || cancelled) return;

        const response = await axiosInstance.get(
          `/api/video/calls/${callerInfoRef.current.callId}/details`,
          { params: { userId: storedUserId, userType: 'user' } },
        );
        if (cancelled) return;

        const status = getCallStatus(response.data);
        if (TERMINAL_CALL_STATUSES.has(status)) {
          const shouldExitAfterCall = launchedFromCallPushRef.current;
          launchedFromCallPushRef.current = false;
          forceStopRingtone();
          pollBlockedUntilRef.current = Date.now() + 6000;
          setShowCallModal(false);
          setCallerInfo({ name: '', image: null, userId: '', userName: '', callId: '', roomId: '', waitingDuration: 0 });
          await displayMissedCallNotification(
            callerInfoRef.current,
            status === 'ended' ? 'ended' : 'missed',
          );
          await AsyncStorage.removeItem('pendingIncomingCallPush');
          if (shouldExitAfterCall && Platform.OS === 'android') {
            setTimeout(() => BackHandler.exitApp(), 100);
          }
        }
      } catch (_) {}
    };

    const intervalId = setInterval(checkCallEnded, 2000);

    return () => {
      cancelled = true;
      clearInterval(intervalId);
    };
  }, [showCallModal, callerInfo.callId]);

  const fetchUserData = async () => {
    try {
      // Clear any previous image-load failure so a freshly uploaded photo gets
      // a fair attempt instead of staying on initials.
      setAvatarFailed(false);
      const storedUserId = await AsyncStorage.getItem("userId");
      if (!storedUserId) return;

      setUserId(storedUserId);

      const response = await axiosInstance.get(`/api/auth/getUser/${storedUserId}`);

      if (response.data.success) {
        const user = response.data.user;
        setUserData({
          name: user.fullName || "",
          email: user.email || "",
          phone: user.phoneNumber || "",
          // Field name varies by endpoint/record in this backend, and reading only
          // `profilePhoto` left the sidebar avatar blank while the profile page
          // (which also falls back to its own local state) showed one. Each is
          // run through toImageUri, so any string / {url} / {secure_url} /
          // {publicId} shape resolves.
          profilePhoto: getGeneratedUserAvatarUri(user.profilePhoto, user.profilePic, user.avatar, user.photo),
        });
      }
    } catch (error) {
      console.error("Error fetching user:", error);
    }
  };

  // Pulls a usable counselor id out of an appointment, whatever shape the
  // backend used: apt.counselor can be a populated object ({_id}/{id}), a raw
  // ObjectId string, or the id can live directly on the appointment
  // (counselorId / counsellorId). Returns a string id or null.
  const extractCounselorId = (apt) => {
    const c = apt?.counselor ?? apt?.counsellor;
    let id =
      (typeof c === "object" && c ? (c._id || c.id) : c) ||
      apt?.counselorId ||
      apt?.counsellorId ||
      apt?.receiverId;
    return id ? String(id) : null;
  };

  const initiateAptCall = async (apt, callType, failLabel) => {
    try {
      const counselor = normalizeAptCounselor(apt);
      const token = await AsyncStorage.getItem("token") || await AsyncStorage.getItem("accessToken");
      const currentUserId = userId || await AsyncStorage.getItem("userId");
      const counselorId = extractCounselorId(apt);

      if (!currentUserId || !counselorId) {
        console.warn("Call aborted — missing ids:", { currentUserId, counselorId, apt });
        Alert.alert("Error", "Missing user or consultant information");
        return;
      }

      const payload = {
        initiatorId: String(currentUserId),
        initiatorType: "user",
        receiverId: counselorId,
        receiverType: "counsellor",
        callType,
      };
      console.log("📞 Initiating call:", payload);

      const response = await axios.post(
        `${API_BASE_URL}/api/video/calls/initiate`,
        payload,
        { headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` } }
      );

      // Backends vary: some return { success, callData }, others return the
      // call object directly. Treat any 2xx with call data as success.
      const callData = response.data?.callData || response.data?.call || response.data;
      if (isNotificationOnlyCallResponse(response.data)) {
        Alert.alert(
          "Call request sent",
          getNotificationOnlyCallMessage(response.data, counselor?.name || "Consultant"),
        );
        return;
      }

      if (response.data?.success !== false && callData) {
        navigation.navigate("ChatBox", {
          chatId: null,
          counselor,
          callType: callType === "audio" ? "voice" : "video",
          callData: {
            ...callData,
            roomId: getStreamRoomId(response.data, callData),
            streamCallId: getStreamRoomId(response.data, callData),
          },
        });
      } else {
        Alert.alert("Error", response.data?.message || `${failLabel} failed. Please try again.`);
      }
    } catch (error) {
      // Surface the real reason instead of a generic message.
      const serverMsg =
        error?.response?.data?.message ||
        error?.response?.data?.error ||
        error?.message;
      console.error(`${failLabel} error:`, error?.response?.status, error?.response?.data || error);
      Alert.alert("Error", serverMsg ? `${failLabel}: ${serverMsg}` : failLabel);
    }
  };

  // Handler for appointment video call
  const handleAptVideoCall = (apt) => initiateAptCall(apt, "video", "Failed to initiate video call");

  // Handler for appointment voice call
  const handleAptVoiceCall = (apt) => initiateAptCall(apt, "audio", "Failed to initiate voice call");

  // Handler for appointment chat
  // An appointment's counselor carries `fullName` and possibly a Cloudinary photo
  // object, while ChatBox and the call modals read `name` / `profilePhoto`. Passing
  // the raw object through is why the call header and the chat header showed a
  // placeholder name and no avatar. Used by every appointment -> chat/call route.
  const normalizeAptCounselor = (apt) => {
    const raw = (typeof apt?.counselor === "object" && apt.counselor) || {};
    const photo = toImageUri(raw.profilePhoto) || toImageUri(raw.avatar);
    const id = extractCounselorId(apt) || raw._id || raw.id || null;
    return {
      ...raw,
      id,
      _id: raw._id || id,
      name: raw.fullName || raw.name || "Counselor",
      fullName: raw.fullName || raw.name || "Counselor",
      specialization: raw.specialization || "",
      profilePhoto: photo,
      avatar: photo,
      avatarType: photo ? "image" : "text",
      phoneNumber: raw.phoneNumber || raw.phone || null,
      online: Boolean(raw.isOnline ?? raw.online ?? false),
    };
  };

  const handleAptChat = async (apt) => {
    try {
      const counselor = normalizeAptCounselor(apt);

      navigation.navigate("ChatBox", {
        chatId: null,
        counselor,
        user: userData,
      });
    } catch (error) {
      Alert.alert("Error", "Failed to open chat");
      console.error("Chat error:", error);
    }
  };

  // Save a generated avatar from the header/profile drawer.
  const uploadHeaderPhoto = async (formData, optimisticUri) => {
    try {
      const token =
        (await AsyncStorage.getItem("accessToken")) ||
        (await AsyncStorage.getItem("token"));
      const storedUserId = await AsyncStorage.getItem("userId");
      const response = await axios.patch(
        `${API_BASE_URL}/api/auth/update/${storedUserId}`,
        formData,
        {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "multipart/form-data",
          },
        }
      );
      if (response.data?.success) {
        if (optimisticUri) setUserData((prev) => ({ ...prev, profilePhoto: optimisticUri }));
        fetchUserData();
      }
    } catch (e) {
      console.error("Header photo upload failed:", e);
    }
  };

  // Generated avatar selected → save it.
  const handleHeaderAvatarSelect = async (avatarUrl) => {
    setShowAvatarBuilder(false);
    const formData = new FormData();
    formData.append("avatarUrl", avatarUrl);
    await uploadHeaderPhoto(formData, avatarUrl);
  };

  const sendMessage = async (messageText = newMessage, imageUri = null) => {
    const sourceText = typeof messageText === "string" ? messageText : newMessage;
    const trimmedMessage = sourceText.trim();
    if (!trimmedMessage && !imageUri) return;

    let outgoingText = trimmedMessage;
    if (trimmedMessage && selectedLang && !['en', 'en-US', 'en-IN', 'en-GB'].includes(selectedLang)) {
      try {
        const translated = await translationService.translate(trimmedMessage, selectedLang, 'en-US');
        if (translated && translated.trim()) {
          outgoingText = translated.trim();
        }
      } catch (error) {
        console.warn('[AI-CHAT] outgoing translate failed:', error?.message || error);
      }
    }

    const userMessage = {
      id: Date.now(),
      text: outgoingText,
      sender: "user",
      image: imageUri || null,
    };
    setChatMessages((prev) => [...prev, userMessage]);
    setNewMessage("");
    setIsLoading(true);

    try {
      const outgoingPayloadText = outgoingText || "I've shared a photo — please take a look.";
      const history = chatMessages.slice(-10).map((msg) => ({
        role: msg.sender === "user" ? "user" : "assistant",
        content: msg.text,
      }));

      const response = await axiosInstance.post('/api/ai-chat/send-message', {
        message: outgoingPayloadText,
        history,
        sessionId: aiSessionId,
        language: selectedLang,
      });

      if (response.data?.success !== false) {
        const responsePayload = response.data?.data || response.data || {};
        const aiResponse =
          responsePayload.aiResponse ||
          responsePayload.response ||
          responsePayload.reply ||
          responsePayload.message ||
          response.data?.aiResponse;

        if (!aiResponse) {
          throw new Error("Invalid AI response");
        }

        const nextSessionId = responsePayload.sessionId || response.data?.sessionId;
        if (nextSessionId) {
          setAiSessionId(nextSessionId);
        }

        const aiMessage = {
          id: Date.now() + 1,
          text: aiResponse,
          sender: "ai",
        };
        setChatMessages((prev) => [...prev, aiMessage]);
      } else {
        throw new Error("Invalid AI response");
      }
    } catch (error) {
      console.error("AI Chat error:", error);

      const aiMessage = {
        id: Date.now() + 1,
        text: "I'm sorry, I'm having trouble connecting to the medical server. Please try again later.",
        sender: "ai",
      };
      setChatMessages((prev) => [...prev, aiMessage]);
    } finally {
      setIsLoading(false);
      if (!chatOpen) {
        setUnreadCount((prev) => prev + 1);
      }
    }
  };

  const handleMenuItemClick = (id) => {
    setShowMoreModal(false);
    setShowProfileMenu(false);
    switchDashboardTab(id);
  };

  const handleProfileClick = () => {
    setShowProfileMenu(false);
    switchDashboardTab("profile");
  };

  // Android hardware back had no handler here, so on any tab other than Chat -
  // Settings, Profile, Wallet, Call history - it fell straight through to the
  // navigator, where this screen is the initial route, and closed the app.
  // Unwind the visible layer instead: overlay first, then tab, then let it exit.
  useEffect(() => {
    // Only while this screen is on top. A screen pushed above it (ChatBox,
    // CounselorTable...) must get the back press itself, otherwise back would
    // silently switch this dashboard's tab instead of popping the stack.
    if (!isFocused) return undefined;

    const onBackPress = () => {
      // Topmost first, roughly in z-order.
      if (chatOpen) { setChatOpen(false); return true; }
      if (showLogoutConfirm) { setShowLogoutConfirm(false); return true; }
      if (showAvatarBuilder) { setShowAvatarBuilder(false); return true; }
      if (showAvatarChooser) { setShowAvatarChooser(false); return true; }
      if (showDirectBookingModal) { setShowDirectBookingModal(false); return true; }
      if (showPrivacyPolicy) { closeSidebarChild(() => setShowPrivacyPolicy(false)); return true; }
      if (showHelpSupport) { closeSidebarChild(() => setShowHelpSupport(false)); return true; }
      if (showNotifications) { setShowNotifications(false); return true; }
      if (showMoreModal) return handleSidebarBack();

      // Came here from the sidebar - go back to the sidebar.
      if (cameFromSidebarRef.current) {
        cameFromSidebarRef.current = false;
        sidebarViaBackRef.current = true;
        setShowMoreModal(true);
        return true;
      }

      // Otherwise retrace the tab history one step at a time. Jumping straight
      // to the home tab loses everything in between, which is what made back
      // feel like it went "home" instead of back.
      return handleDashboardBack();
    };

    const sub = BackHandler.addEventListener('hardwareBackPress', onBackPress);
    return () => sub.remove();
  }, [
    isFocused,
    active,
    chatOpen,
    showLogoutConfirm,
    showAvatarBuilder,
    showAvatarChooser,
    showDirectBookingModal,
    showPrivacyPolicy,
    showHelpSupport,
    showNotifications,
    showMoreModal,
  ]);

  // One step back through the tab history. Used by the hardware/system back and
  // by in-screen back arrows so both behave the same.
  const handleDashboardBack = () => {
    setSidebarSection(null);
    if (tabHistoryRef.current.length > 0) {
      setActive(tabHistoryRef.current.pop());
      return true;
    }
    if (active !== 'Chat') {
      setActive('Chat');
      return true;
    }
    return false;
  };

  // Back press while the sidebar is open. This has to be shared: the sidebar is
  // a Modal, and a Modal's onRequestClose consumes the Android back press before
  // the screen-level BackHandler ever sees it - so putting the logic only in the
  // BackHandler did nothing at all while the drawer was up.
  const handleSidebarBack = () => {
    setShowMoreModal(false);
    // Re-opened BY a back press means the screen behind it is the one already
    // backed out of (Settings / Profile / Call history). Keep retracing so the
    // user lands on the tab they came from instead of bouncing back into it.
    if (sidebarViaBackRef.current) {
      sidebarViaBackRef.current = false;
      handleDashboardBack();
    }
    return true;
  };

  const switchDashboardTab = (tabId) => {
    // Cleared before the early return: picking a tab always drops the sidebar's
    // modal-section highlight, even if that tab was already active.
    setSidebarSection(null);
    cameFromSidebarRef.current = false;
    setShowMoreModal(false);
    if (active === tabId) return;
    safeVibrate(100);
    // Remember where we came from so back retraces the path rather than jumping
    // straight to the home tab.
    tabHistoryRef.current.push(active);
    setActive(tabId);
  };

  const handleLogout = async () => {
    // The logout request is a network round-trip; without this guard a second
    // tap fires it again and can race the AsyncStorage.clear() below.
    if (loggingOut) return;
    setLoggingOut(true);
    try {
      const refreshToken = await AsyncStorage.getItem("refreshToken");
      try {
        await axiosInstance.post('/api/auth/logout', { refreshToken });
      } catch (apiError) {
        console.error("Backend logout error:", apiError);
      }

      await AsyncStorage.clear();
      setShowLogoutConfirm(false);
      resetToLoginScreen(navigation);
    } catch (error) {
      console.error("Logout error:", error);
      await AsyncStorage.clear();
      setShowLogoutConfirm(false);
      resetToLoginScreen(navigation);
    } finally {
      setLoggingOut(false);
    }
  };

  const handleDeleteConfirm = async () => {
    if (deletingAccount) return;
    safeVibrate([220, 100, 220]);
    setDeletingAccount(true);
    try {
      await axiosInstance.delete('/api/auth/delete');
      await clearAccountLocalData();
      setShowDeleteConfirm(false);
      setDeleteSuccess(true);
      setTimeout(() => {
        navigation.replace("RoleSelector");
      }, 1500);
    } catch (error) {
      console.error("Delete account error:", error);
      Alert.alert(
        "Delete failed",
        error?.response?.data?.message || "Could not delete your account. Please try again.",
      );
    } finally {
      setDeletingAccount(false);
    }
  };

  const handleAcceptCall = async (callId) => {
    launchedFromCallPushRef.current = false;
    await AsyncStorage.removeItem('pendingIncomingCallPush');
    forceStopRingtone();
    pollBlockedUntilRef.current = Date.now() + 6000;
    try {
      const storedUserId = await AsyncStorage.getItem('userId');
      if (!storedUserId) throw new Error('User ID missing');

      const acceptRes = await axiosInstance.put(
        '/api/video/calls/' + callId + '/accept',
        { acceptorId: storedUserId, acceptorType: 'user' }
      );
      if (!acceptRes.data?.success) {
        throw new Error(acceptRes.data?.error || acceptRes.data?.message || 'Failed to accept call');
      }

      const acceptedPayload =
        acceptRes.data?.call ||
        acceptRes.data?.callData ||
        acceptRes.data?.data?.call ||
        acceptRes.data?.data?.callData ||
        null;

      const incomingType = String(callerInfo.callType || callType || 'video').toLowerCase();
      const modalType = incomingType === 'audio' ? 'voice' : incomingType;
      const remoteParticipant = acceptedPayload?.initiator || callerInfo?.from || {};

      const acceptedCallData = {
        id: acceptedPayload?.id || acceptedPayload?._id || callId,
        callId,
        roomId: getStreamRoomId(acceptRes.data, acceptedPayload, callerInfo),
        streamCallId: getStreamRoomId(acceptRes.data, acceptedPayload, callerInfo),
        name: remoteParticipant?.fullName || remoteParticipant?.displayName || callerInfo.name || 'Counselor',
        type: modalType,
        callType: modalType,
        status: acceptRes.data?.status || acceptedPayload?.status || 'active',
        profilePic: remoteParticipant?.profilePhoto || callerInfo.image || null,
        phoneNumber: remoteParticipant?.phoneNumber || '',
        apiCallData: acceptedPayload,
        initiator: acceptedPayload?.initiator || callerInfo?.from,
        receiver: acceptedPayload?.receiver,
        initiatorId: acceptedPayload?.initiator?.id || acceptedPayload?.initiator?._id,
        receiverId: acceptedPayload?.receiver?.id || acceptedPayload?.receiver?._id,
        currentUserId: storedUserId,
        currentUserType: 'user',
        isIncoming: true,
      };

      setSelectedCall(acceptedCallData);
      if (modalType === 'video') setIsVideoModalOpen(true);
      else setIsVoiceModalOpen(true);
      setShowCallModal(false);
      setCallerInfo({ name: '', image: null, userId: '', userName: '', callId: '', roomId: '', waitingDuration: 0 });
    } catch (error) {
      console.error('Error accepting call:', error);
      setShowCallModal(true);
      startIncomingRingtone(true);
    }
  };

  const handleRejectCall = async (callId) => {
    const shouldExitAfterReject = launchedFromCallPushRef.current;
    launchedFromCallPushRef.current = false;
    forceStopRingtone();
    setShowCallModal(false);
    setCallerInfo({ name: '', image: null, userId: '', userName: '', callId: '', roomId: '', waitingDuration: 0 });
    // Block polling so the backend has time to process the reject before we poll again
    pollBlockedUntilRef.current = Date.now() + 6000;
    try {
      const storedUserId = await AsyncStorage.getItem('userId');
      if (storedUserId && callId) {
        await axiosInstance.put(
          '/api/video/calls/' + callId + '/reject',
          { userId: storedUserId, reason: 'declined' }
        ).catch(() => {});
      }
    } catch (_) {}
    await AsyncStorage.removeItem('pendingIncomingCallPush');
    if (shouldExitAfterReject && Platform.OS === 'android') {
      setTimeout(() => BackHandler.exitApp(), 100);
    }
  };

  const allMenuItems = [
    { id: "Chat", icon: "chat", label: t('dashboard:chat'), type: "material" },
    { id: "Counselor", icon: "psychology", label: t('dashboard:consultants', 'Consultants'), type: "material" },
    { id: "Appointment", icon: "event-available", label: t('dashboard:appointments', 'Appointments'), type: "material" },
    { id: "Prescription", icon: "receipt-long", label: "Prescription", type: "material" },
    { id: "Wallet", icon: "account-balance-wallet", label: t('dashboard:wallet'), type: "material" },
    { id: "Video", icon: "history", label: t('dashboard:callHistory'), type: "material" },
  ];

  const handleDirectDateChange = (event, selectedDate) => {
    if (selectedDate) {
      const newDate = new Date(directBookDateTime);
      newDate.setFullYear(selectedDate.getFullYear());
      newDate.setMonth(selectedDate.getMonth());
      newDate.setDate(selectedDate.getDate());
      setDirectBookDateTime(newDate);
    }
    if (Platform.OS === 'android') {
      setShowDirectDatePicker(false);
    }
  };

  const handleDirectTimeChange = (event, selectedTime) => {
    if (selectedTime) {
      const newDate = new Date(directBookDateTime);
      newDate.setHours(selectedTime.getHours());
      newDate.setMinutes(selectedTime.getMinutes());
      setDirectBookDateTime(newDate);
    }
    if (Platform.OS === 'android') {
      setShowDirectTimePicker(false);
    }
  };

  const handleDirectBooking = async () => {
    if (!directBookCounselor) return;
    if (!directBookDateTime || directBookDateTime.getTime() <= Date.now()) {
      Alert.alert(t('appointment:invalidTime', 'Invalid time'), t('appointment:pleaseChooseFutureDateTime', 'Please choose a future date and time.'));
      return;
    }

    try {
      setDirectBookLoading(true);
      const counselorId = directBookCounselor._id || directBookCounselor.id || directBookCounselor.counselorId;

      await axiosInstance.post('/api/appointments', {
        counselorId,
        date: directBookDateTime.toISOString(),
        notes: directBookNotes.trim(),
      });

      Alert.alert(
        t('appointment:bookedSuccessfully', 'Appointment Booked'),
        `Your appointment request was sent to ${directBookCounselor.fullName || directBookCounselor.name || 'the consultant'}.`
      );
      setShowDirectBookingModal(false);
      setDirectBookNotes('');
      setDirectBookDateTime(new Date());
    } catch (error) {
      console.error('Error booking appointment:', error);
      Alert.alert(
        t('appointment:bookingFailed', 'Booking Failed'),
        error?.response?.data?.message || t('appointment:failedToBook', 'Failed to book appointment')
      );
    } finally {
      setDirectBookLoading(false);
    }
  };

  // Profile / Call history / Settings only flip `active`, so they work straight
  // away. Help & Support and Privacy Policy are separate <Modal statusBarTranslucent navigationBarTranslucent>s, and React
  // Native will not mount a second Modal while the sidebar Modal is still
  // dismissing - the open call was simply swallowed. Let the sidebar finish
  // fading out first.
  const closeSidebarThen = (open) => {
    sidebarViaBackRef.current = false;
    // Sidebar stays open behind the child. Nothing is dismissing, so the child
    // Modal mounts immediately - and closing it reveals the sidebar with no gap.
    cameFromSidebarRef.current = true;
    open();
  };

  // Dismissing a screen opened from the sidebar just uncovers the sidebar.
  const closeSidebarChild = (close) => {
    close();
    cameFromSidebarRef.current = false;
    // Drop the section highlight too. Without this the sidebar still showed
    // Help/Privacy as the active row after returning, and because every tab row
    // is gated on `!sidebarSection` none of them could light up either.
    setSidebarSection(null);
  };


  // Opening a tab from the sidebar records the sidebar as the origin, so back
  // returns there rather than to the tab that happened to be underneath.
  const openTabFromSidebar = (tabId, go) => {
    sidebarViaBackRef.current = false;
    setShowMoreModal(false);
    (go || switchDashboardTab)(tabId);
    // Set after the switch: switchDashboardTab clears this flag for ordinary
    // tab changes, and this one is not ordinary.
    cameFromSidebarRef.current = true;
  };

  const sidebarItems = [
    {
      id: 'profile',
      icon: 'person-outline',
      iconActive: 'person',
      label: t('settings:myProfile'),
      // `!sidebarSection` so a tab and a modal section are never both lit.
      isActive: !sidebarSection && active === 'profile',
      onPress: () => openTabFromSidebar('profile'),
    },
    {
      id: 'Prescription',
      icon: 'document-text-outline',
      iconActive: 'document-text',
      label: 'Prescription',
      isActive: !sidebarSection && active === 'Prescription',
      onPress: () => openTabFromSidebar('Prescription', handleMenuItemClick),
    },
    {
      id: 'Video',
      icon: 'call-outline',
      iconActive: 'call',
      label: t('dashboard:callHistory'),
      isActive: !sidebarSection && active === 'Video',
      onPress: () => openTabFromSidebar('Video', handleMenuItemClick),
    },
    {
      id: 'Token',
      icon: 'ticket-outline',
      iconActive: 'ticket',
      label: t('dashboard:myToken', 'My Token'),
      isActive: !sidebarSection && active === 'Token',
      onPress: () => openTabFromSidebar('Token', handleMenuItemClick),
    },
    {
      id: 'settings',
      icon: 'settings-outline',
      iconActive: 'settings',
      label: t('settings:settings'),
      isActive: !sidebarSection && active === 'settings',
      // Routed through switchDashboardTab so it clears sidebarSection too.
      onPress: () => openTabFromSidebar('settings'),
    },
    {
      id: 'help',
      icon: 'help-circle-outline',
      iconActive: 'help-circle',
      label: t('settings:helpSupport'),
      isActive: sidebarSection === 'help',
      onPress: () => {
        setSidebarSection('help');
        closeSidebarThen(() => setShowHelpSupport(true));
      },
    },
    {
      id: 'privacy',
      icon: 'shield-checkmark-outline',
      iconActive: 'shield-checkmark',
      label: t('settings:privacyPolicy'),
      isActive: sidebarSection === 'privacy',
      onPress: () => {
        setSidebarSection('privacy');
        closeSidebarThen(() => setShowPrivacyPolicy(true));
      },
    },
  ];

  const renderContent = () => {
    switch (active) {
      case "Chat":
        return <ChatInterface setActiveTab={switchDashboardTab} onOpenCounselor={handleAIContactClick} />;
      case "Counselor":
        return (
          <CounselorTable
            initialSearchQuery={targetCounselor}
            initialOpenRequestName={openCounselorRequestTarget}
            onInitialOpenHandled={() => setOpenCounselorRequestTarget("")}
          />
        );
      case "Appointment":
        return (
          <MyAppointmentsPanel
            onBookPress={(apt) => {
              const c = apt?.counselor || apt;
              setDirectBookCounselor(c);
              const nextSlot = new Date();
              nextSlot.setHours(nextSlot.getHours() + 1);
              setDirectBookDateTime(nextSlot);
              setDirectBookNotes("");
              setShowDirectBookingModal(true);
            }}
            onVideoCall={handleAptVideoCall}
            onVoiceCall={handleAptVoiceCall}
            onChat={handleAptChat}
          />
        );
      case "Prescription":
        return <PrescriptionScreen />;
      case "Wallet":
        return <WalletDashboard userData={userData} navigation={navigation} initialTab={walletInitialTab} />;
      case "Video":
        return <CallHistory />;
      case "Token":
        return <TokenStatusScreen />;
      case "profile":
        // The dashboard reads userData once on mount, so a photo changed inside
        // the profile tab left the sidebar avatar (and the header) showing the
        // old one until the app restarted. PatientProfile already fires this
        // callback after a successful save - it just was never wired up.
        return <PatientProfile onProfileUpdate={fetchUserData} />;
      case "settings":
        return (
          <UserAccountSettings
            onNavigateBack={() => handleDashboardBack()}
            onDeleteAccount={() => setShowDeleteConfirm(true)}
          />
        );
      default:
        return <ChatInterface />;
    }
  };

  return (
    <SafeAreaView style={styles.container} edges={['top', 'left', 'right']}>
      <StatusBar
        barStyle="dark-content"
        backgroundColor={PATIENT.surface}
        translucent={false}
      />
      <RatingPrompt triggerKey={active} />
      <UpdateReminderModal variant="patient" />

      <CallModal
        isOpen={showCallModal}
        onClose={() => {
          forceStopRingtone();
          setShowCallModal(false);
          setCallerInfo({ name: '', image: null, userId: '', userName: '', callId: '', roomId: '', waitingDuration: 0 });
          pollBlockedUntilRef.current = Date.now() + 6000;
        }}
        callType={callType}
        callerName={callerInfo.userName || callerInfo.name}
        callerImage={callerInfo.image}
        callData={callerInfo}
        onAcceptCall={handleAcceptCall}
        onRejectCall={handleRejectCall}
      />

      <RealVideoCallModal
        isOpen={isVideoModalOpen}
        onClose={() => {
          pollBlockedUntilRef.current = Date.now() + 6000;
          setIsVideoModalOpen(false);
          setSelectedCall(null);
          setShowCallModal(false);
          setCallerInfo({ name: '', image: null, userId: '', userName: '', callId: '', roomId: '', waitingDuration: 0 });
        }}
        callData={selectedCall}
        onEndCall={async (callId) => {
          try {
            const storedUserId = await AsyncStorage.getItem('userId');
            if (storedUserId && callId) {
              await axiosInstance.put(
                '/api/video/calls/' + callId + '/end',
                { userId: storedUserId, endedBy: 'user' }
              ).catch(() => {});
            }
          } catch (_) {}
        }}
      />

      <RealVoiceCallModal
        isOpen={isVoiceModalOpen}
        onClose={() => {
          pollBlockedUntilRef.current = Date.now() + 6000;
          setIsVoiceModalOpen(false);
          setSelectedCall(null);
          setShowCallModal(false);
          setCallerInfo({ name: '', image: null, userId: '', userName: '', callId: '', roomId: '', waitingDuration: 0 });
        }}
        callData={selectedCall}
        onEndCall={async (callId) => {
          try {
            const storedUserId = await AsyncStorage.getItem('userId');
            if (storedUserId && callId) {
              await axiosInstance.put(
                '/api/video/calls/' + callId + '/end',
                { userId: storedUserId, endedBy: 'user' }
              ).catch(() => {});
            }
          } catch (_) {}
        }}
      />

      {/* HEADER */}
      <View style={styles.header}>
        <TouchableOpacity
          style={styles.menuBtnWrapper}
          onPress={() => { sidebarViaBackRef.current = false; setShowMoreModal(true); }}
          activeOpacity={0.7}
          hitSlop={{ top: 12, bottom: 12, left: 12, right: 12 }}
          accessible={true}
          accessibilityLabel="Menu"
        >
          <View style={styles.menuBtn}>
            <View style={[styles.menuLine, { width: 22 }]} />
            <View style={[styles.menuLine, { width: 22 }]} />
            <View style={[styles.menuLine, { width: 14 }]} />
          </View>
        </TouchableOpacity>

        <View style={styles.headerLeft}>
          <Text style={styles.headerName} numberOfLines={1}>
            {(() => {
              const firstName = (userData.name || 'User').split(' ')[0];
              return firstName.charAt(0).toUpperCase() + firstName.slice(1);
            })()}
          </Text>
        </View>

        <TouchableOpacity style={styles.bellBtn} activeOpacity={0.7} onPress={() => setShowQrScanner(true)}>
          <Ionicons name="qr-code-outline" size={22} color={PATIENT.primary} />
        </TouchableOpacity>

        <TouchableOpacity style={styles.bellBtn} activeOpacity={0.7} onPress={() => setShowNotifications(true)}>
          <Ionicons name="notifications-outline" size={22} color={PATIENT.primary} />
          {notifUnread > 0 && (
            <View style={styles.bellBadge}>
              <Text style={styles.bellBadgeText}>{notifUnread > 99 ? '99+' : notifUnread}</Text>
            </View>
          )}
        </TouchableOpacity>
      </View>

      <QrScannerScreen visible={showQrScanner} onClose={() => setShowQrScanner(false)} onScanned={handleQrScanned} />
      <WalkInBookingScreen
        visible={Boolean(walkInBooking)}
        doctorId={walkInBooking?.doctorId}
        clinicId={walkInBooking?.clinicId}
        clinicName={walkInBooking?.clinicName}
        source={walkInBooking?.source}
        onClose={() => setWalkInBooking(null)}
      />

      {/* MAIN CONTENT */}
      <View style={[styles.contentContainer, { marginBottom: bottomNavHeight }]}>
        <ResponsiveContent>{renderContent()}</ResponsiveContent>
      </View>

      {/* CHAT POPUP */}
      {chatOpen && (
        <ChatPopup
          messages={chatMessages}
          newMessage={newMessage}
          setNewMessage={setNewMessage}
          sendMessage={sendMessage}
          isLoading={isLoading}
          onClose={() => {
            setShowResetChatConfirm(false);
            setChatOpen(false);
          }}
          onReset={handleResetChat}
          showResetConfirm={showResetChatConfirm}
          onCancelReset={cancelResetChat}
          onConfirmReset={confirmResetChat}
          onCounselorPress={handleAIContactClick}
          selectedLang={selectedLang}
          userPhoto={userData.profilePhoto}
        />
      )}

      {/* BOTTOM NAVIGATION */}
      <View
        pointerEvents="box-none"
        style={[
          styles.bottomNav,
          {
            height: bottomNavHeight,
            paddingBottom: bottomNavPaddingBottom,
          },
        ]}
      >
        {[
          { id: 'Chat', icon: 'chatbubble-ellipses-outline', iconActive: 'chatbubble-ellipses', label: t('dashboard:chat') },
          { id: 'Counselor', icon: 'bulb-outline', iconActive: 'bulb', label: t('dashboard:consultants', 'Consultants') },
        ].map((tab) => (
          <TouchableOpacity
            key={tab.id}
            style={styles.navItem}
            onPress={() => handleMenuItemClick(tab.id)}
            activeOpacity={0.7}
          >
            <Ionicons
              name={active === tab.id ? tab.iconActive : tab.icon}
              size={22}
              color={active === tab.id ? PATIENT.primary : PATIENT.textMuted}
            />
            <Text
              style={[styles.navLabel, active === tab.id && styles.navLabelActive]}
              numberOfLines={2}
              maxFontSizeMultiplier={1}
            >
              {tab.label}
            </Text>
          </TouchableOpacity>
        ))}

        {/* Spacer for the centre AI button */}
        <View style={styles.navCenterSpacer} />

        {[
          { id: 'Appointment', icon: 'calendar-outline', iconActive: 'calendar', label: t('dashboard:appointments', 'Appointments') },
          { id: 'Wallet', icon: 'wallet-outline', iconActive: 'wallet', label: t('dashboard:wallet') },
        ].map((tab) => (
          <TouchableOpacity
            key={tab.id}
            style={styles.navItem}
            onPress={() => handleMenuItemClick(tab.id)}
            activeOpacity={0.7}
          >
            <Ionicons
              name={active === tab.id ? tab.iconActive : tab.icon}
              size={22}
              color={active === tab.id ? PATIENT.primary : PATIENT.textMuted}
            />
            <Text
              style={[styles.navLabel, active === tab.id && styles.navLabelActive]}
              numberOfLines={2}
              maxFontSizeMultiplier={1}
            >
              {tab.label}
            </Text>
          </TouchableOpacity>
        ))}
      </View>

      {/* AI FLOATING BUTTON — centred above the bottom nav */}
      <TouchableOpacity
        style={[
          styles.aiButton,
          {
            bottom: aiButtonBottom,
          },
        ]}
        onPress={() => setChatOpen(true)}
        activeOpacity={0.85}
        hitSlop={{ top: 12, bottom: 12, left: 12, right: 12 }}
        accessibilityLabel="Open Humaelio AI"
      >
        <LinearGradient
          colors={[PATIENT.gradientFrom, PATIENT.gradientTo]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={styles.aiButtonGradient}
        >
          <Ionicons name="sparkles" size={26} color="#ffffff" />
        </LinearGradient>
        {unreadCount > 0 && !chatOpen && (
          <View style={styles.aiUnreadBadge}>
            <Text style={styles.aiUnreadBadgeText}>{unreadCount}</Text>
          </View>
        )}
      </TouchableOpacity>

      {/* SIDEBAR DRAWER */}
      <Modal statusBarTranslucent navigationBarTranslucent
        transparent
        visible={showMoreModal}
        animationType="fade"
        onRequestClose={handleSidebarBack}
      >
        <View style={styles.sidebarRoot} pointerEvents="auto">
          {/* Explicit insets instead of SafeAreaView: inside this translucent
              Modal (its own Android window) SafeAreaView reported a 0 top
              inset, so the user card sat under the status bar icons. */}
          <View
            style={[
              styles.sidebar,
              {
                paddingTop: sidebarTopInset + 12,
                paddingBottom: dashboardBottomInset + 12,
                paddingLeft: navInsets.left + 14,
              },
            ]}
          >
            {/* User card — green gradient */}
            <LinearGradient
              colors={['#006B2C', '#01CE54']}
              start={{ x: 0, y: 0.5 }}
              end={{ x: 1, y: 0.5 }}
              style={styles.sbUserCard}
            >
              <TouchableOpacity
                style={styles.sbUserMain}
                activeOpacity={0.85}
                onPress={() => { setShowMoreModal(false); switchDashboardTab('profile'); }}
              >
                <View style={styles.sbAvatarWrap}>
                  {userData.profilePhoto && !avatarFailed ? (
                    <Image
                      source={{ uri: userData.profilePhoto }}
                      style={styles.sbAvatar}
                      // A dead URL used to leave an empty circle. Show initials.
                      onError={() => setAvatarFailed(true)}
                    />
                  ) : (
                    <View style={styles.sbAvatarPlaceholder}>
                      <Text style={styles.sbAvatarText}>
                        {userData.name?.charAt(0)?.toUpperCase() || 'U'}
                      </Text>
                    </View>
                  )}
                </View>
                <View style={styles.sbUserInfo}>
                  <Text style={styles.sbUserName} numberOfLines={1}>
                    {(() => {
                      const name = userData.name || 'User';
                      return name.length > 15 ? `${name.slice(0, 15)}...` : name;
                    })()}
                  </Text>
                  <Text style={styles.sbUserRole} numberOfLines={1}>{t('auth:userRole', 'Patient')}</Text>
                </View>
              </TouchableOpacity>
            </LinearGradient>

            {/* Menu */}
            <View style={styles.sbMenu}>
              {/* Pressable, not TouchableOpacity: opacity alone gave no visible
                  feedback, so Help and Privacy looked dead when tapped. */}
              {sidebarItems.map((item) => {
                return (
                  <Pressable
                    key={item.id}
                    style={({ pressed }) => [
                      styles.sbItem,
                      item.isActive && styles.sbItemActive,
                      pressed && styles.sbItemPressed,
                    ]}
                    onPress={item.onPress}
                    android_ripple={{ color: '#D7F0E1', borderless: false }}
                  >
                    <View style={[styles.sbIconChip, item.isActive && styles.sbIconChipActive]}>
                      <Ionicons
                        name={item.isActive ? item.iconActive : item.icon}
                        size={19}
                        color={item.isActive ? '#ffffff' : PATIENT.primary}
                      />
                    </View>
                    <Text style={[styles.sbItemText, item.isActive && styles.sbItemTextActive]}>
                      {item.label}
                    </Text>
                    <Ionicons
                      name="chevron-forward"
                      size={17}
                      color={item.isActive ? PATIENT.primary : '#CBD5E1'}
                    />
                  </Pressable>
                );
              })}
            </View>

            <View style={styles.sbBottomActions}>
              {/* Opens the shared language sheet; saved per user. */}
              <LanguageSelector
                userId={userId}
                role="user"
                brand={PATIENT.primary}
                triggerStyle={styles.sbItem}
              >
                <View style={styles.sbIconChip}>
                  <Ionicons name="globe-outline" size={19} color={PATIENT.primary} />
                </View>
                <Text style={styles.sbItemText}>{t('settings:language', 'Language')}</Text>
                <Ionicons name="chevron-forward" size={17} color="#CBD5E1" />
              </LanguageSelector>

              <TouchableOpacity
                style={styles.sbLogout}
                activeOpacity={0.85}
                onPress={() => { setShowMoreModal(false); setShowLogoutConfirm(true); }}
              >
                <LinearGradient
                  colors={['#DC2626', '#F87171']}
                  start={{ x: 0, y: 0.5 }}
                  end={{ x: 1, y: 0.5 }}
                  style={StyleSheet.absoluteFillObject}
                />
                <View style={styles.sbLogoutIcon}>
                  <Ionicons name="log-out-outline" size={19} color="#ffffff" />
                </View>
                <Text style={styles.sbLogoutText}>{t('auth:logout')}</Text>
                <Ionicons name="chevron-forward" size={18} color="rgba(255,255,255,0.85)" />
              </TouchableOpacity>
            </View>
          </View>

          <TouchableOpacity
            style={styles.sidebarBackdrop}
            activeOpacity={1}
            onPress={() => setShowMoreModal(false)}
          />
        </View>
      </Modal>

      {/* Notifications full-screen modal */}
      <Modal statusBarTranslucent navigationBarTranslucent visible={showNotifications} animationType="slide" transparent={false} onRequestClose={() => setShowNotifications(false)}>
        <NotificationScreen
          onClose={() => setShowNotifications(false)}
          onAction={(n) => {
            setShowNotifications(false);
            if (n.type === 'appointment') switchDashboardTab('Appointment');
            else if (n.type === 'message' || n.type === 'chat') switchDashboardTab('Chat');
            else if (n.type === 'payment' || n.type === 'wallet') switchDashboardTab('Wallet');
          }}
        />
      </Modal>

      {/* LOGOUT CONFIRM MODAL */}
      {/* Help & Support full-screen modal */}
      <Modal statusBarTranslucent navigationBarTranslucent visible={showHelpSupport} animationType="slide" transparent={false} onRequestClose={() => closeSidebarChild(() => setShowHelpSupport(false))}>
        <HelpSupport
          onClose={() => closeSidebarChild(() => setShowHelpSupport(false))}
          onOpenTab={switchDashboardTab}
          onOpenAiChat={() => { setShowHelpSupport(false); setChatOpen(true); }}
        />
      </Modal>

      {/* Privacy Policy full-screen modal */}
      <Modal statusBarTranslucent navigationBarTranslucent visible={showPrivacyPolicy} animationType="slide" transparent={false} onRequestClose={() => closeSidebarChild(() => setShowPrivacyPolicy(false))}>
        <PrivacyPolicy
          onClose={() => closeSidebarChild(() => setShowPrivacyPolicy(false))}
          onOpenTab={switchDashboardTab}
          onOpenHelpSupport={() => {
            setSidebarSection('help');
            setShowHelpSupport(true);
          }}
          onOpenRefund={() => {
            setWalletInitialTab('refund');
            switchDashboardTab('Wallet');
          }}
        />
      </Modal>

      <Modal statusBarTranslucent navigationBarTranslucent
        transparent={true}
        visible={showLogoutConfirm}
        animationType="fade"
        onRequestClose={() => !loggingOut && setShowLogoutConfirm(false)}
      >
        {/* Backdrop tap and Android back both dismiss, matching the rest of the
            app's sheets. Both are blocked mid-logout so the screen can't be
            dismissed while the session is being torn down. */}
        <Pressable
          style={styles.logoutOverlay}
          onPress={() => !loggingOut && setShowLogoutConfirm(false)}
        >
          <Pressable style={styles.logoutCard} onPress={() => {}}>
            <View style={styles.logoutIconRing}>
              <LinearGradient
                colors={['#006B2C', '#01CE54']}
                start={{ x: 0, y: 0.5 }}
                end={{ x: 1, y: 0.5 }}
                style={styles.logoutIconBadge}
              >
                <Ionicons name="log-out-outline" size={26} color="#ffffff" />
              </LinearGradient>
            </View>

            <Text style={styles.logoutTitle}>{t('settings:confirmLogout')}</Text>
            <Text style={styles.logoutMessage}>{t('settings:logoutConfirm')}</Text>

            <View style={styles.logoutActions}>
              <TouchableOpacity
                style={styles.logoutCancelBtn}
                onPress={() => setShowLogoutConfirm(false)}
                disabled={loggingOut}
                activeOpacity={0.85}
              >
                <Text style={styles.logoutCancelText}>{t('common:cancel')}</Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={[styles.logoutConfirmBtn, loggingOut && styles.logoutBtnBusy]}
                onPress={handleLogout}
                disabled={loggingOut}
                activeOpacity={0.85}
              >
                <LinearGradient
                  colors={['#006B2C', '#01CE54']}
                  start={{ x: 0, y: 0.5 }}
                  end={{ x: 1, y: 0.5 }}
                  style={styles.logoutConfirmInner}
                >
                  {loggingOut ? (
                    <ActivityIndicator size="small" color="#ffffff" />
                  ) : (
                    <>
                      <Ionicons name="log-out-outline" size={17} color="#ffffff" />
                      <Text style={styles.logoutConfirmText}>{t('auth:logout')}</Text>
                    </>
                  )}
                </LinearGradient>
              </TouchableOpacity>
            </View>
          </Pressable>
        </Pressable>
      </Modal>

      {/* DELETE CONFIRM MODAL */}
      <Modal statusBarTranslucent navigationBarTranslucent transparent={true} visible={showDeleteConfirm} animationType="fade">
        <View style={styles.modalOverlay}>
          <View style={styles.confirmModal}>
            <View style={styles.confirmModalHeader}>
              <Text style={styles.confirmModalTitle}>{t('settings:deleteAccount')}</Text>
            </View>
            <View style={styles.confirmModalBody}>
              <Text style={styles.confirmModalText}>{t('settings:deleteWarning')}</Text>
              <Text style={styles.confirmModalText}>Payment history will be kept.</Text>
            </View>
            <View style={styles.confirmModalFooter}>
              <TouchableOpacity
                style={[styles.modalBtn, styles.cancelBtn]}
                onPress={() => setShowDeleteConfirm(false)}
                disabled={deletingAccount}
              >
                <Text style={styles.cancelBtnText}>{t('common:cancel')}</Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={[styles.modalBtn, styles.deleteBtn, deletingAccount && styles.deleteBtnBusy]}
                onPress={handleDeleteConfirm}
                disabled={deletingAccount}
              >
                {deletingAccount ? (
                  <ActivityIndicator size="small" color="#ffffff" />
                ) : (
                  <Text style={styles.deleteBtnText}>{t('settings:deleteAccount')}</Text>
                )}
              </TouchableOpacity>
            </View>
          </View>
        </View>
      </Modal>

      {/* DELETE SUCCESS MODAL */}
      <Modal statusBarTranslucent navigationBarTranslucent transparent={true} visible={deleteSuccess} animationType="fade">
        <View style={styles.modalOverlay}>
          <View style={[styles.confirmModal, styles.successModal]}>
            <View style={styles.confirmModalHeader}>
              <Text style={[styles.confirmModalTitle, styles.successTitle]}>
                <MaterialIcons name="check-circle" size={20} color="#10b981" /> Account Deleted!
              </Text>
            </View>
            <View style={styles.confirmModalBody}>
              <Text style={styles.confirmModalText}>Your account has been successfully deleted.</Text>
              <Text style={styles.confirmModalText}>Redirecting...</Text>
            </View>
          </View>
        </View>
      </Modal>

      {/* Avatar action chooser (from header popup) */}
      <Modal statusBarTranslucent navigationBarTranslucent
        visible={showAvatarChooser}
        transparent
        animationType="fade"
        onRequestClose={() => setShowAvatarChooser(false)}
      >
        <TouchableOpacity
          style={styles.avatarChooserOverlay}
          activeOpacity={1}
          onPress={() => setShowAvatarChooser(false)}
        >
          <View style={styles.avatarChooserSheet}>
            <View style={styles.avatarChooserHandle} />
            <Text style={styles.avatarChooserTitle}>{t('profile:createAvatar', 'Change Avatar')}</Text>

            <TouchableOpacity
              style={styles.avatarChooserOption}
              onPress={() => { setShowAvatarChooser(false); setShowAvatarBuilder(true); }}
              activeOpacity={0.8}
            >
              <View style={[styles.avatarChooserIcon, { backgroundColor: '#E6F6EC' }]}>
                <MaterialIcons name="face" size={22} color="#6366f1" />
              </View>
              <View style={styles.avatarChooserTextWrap}>
                <Text style={styles.avatarChooserOptionTitle}>{t('profile:createAvatar', 'Create Avatar')}</Text>
                <Text style={styles.avatarChooserOptionSub}>{t('profile:createAvatarSub', 'Build a custom cartoon avatar')}</Text>
              </View>
              <MaterialIcons name="chevron-right" size={20} color="#cbd5e1" />
            </TouchableOpacity>

            <TouchableOpacity
              style={styles.avatarChooserCancel}
              onPress={() => setShowAvatarChooser(false)}
              activeOpacity={0.8}
            >
              <Text style={styles.avatarChooserCancelText}>{t('common:cancel', 'Cancel')}</Text>
            </TouchableOpacity>
          </View>
        </TouchableOpacity>
      </Modal>

      <AvatarPicker
        visible={showAvatarBuilder}
        userGender={userData?.gender}
        currentAvatarUrl={userData?.profilePhoto}
        onSelect={handleHeaderAvatarSelect}
        onClose={() => setShowAvatarBuilder(false)}
      />

      {/* Direct Booking Modal - opened from appointment "Book Now" button */}
      <Modal statusBarTranslucent navigationBarTranslucent
        visible={showDirectBookingModal}
        animationType="slide"
        transparent={true}
        onRequestClose={() => setShowDirectBookingModal(false)}
      >
        <View style={styles.directBookingOverlay}>
          <View style={styles.directBookingContent}>
            <View style={styles.directBookingHeader}>
              <Text style={styles.directBookingTitle}>
                {directBookCounselor ? `Book with Dr. ${directBookCounselor.fullName || directBookCounselor.name}` : "Book Appointment"}
              </Text>
              <TouchableOpacity onPress={() => setShowDirectBookingModal(false)}>
                <Text style={styles.directBookingClose}>×</Text>
              </TouchableOpacity>
            </View>

            <ScrollView showsVerticalScrollIndicator={false} style={styles.directBookingScroll}>
              <Text style={styles.directBookingLabel}>Date</Text>
              <TouchableOpacity
                style={styles.directBookingInput}
                onPress={() => {
                  setShowDirectDatePicker(true);
                  if (Platform.OS === 'ios') {
                    setShowDirectTimePicker(false);
                  }
                }}
              >
                <Text>{directBookDateTime.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}</Text>
              </TouchableOpacity>

              <Text style={styles.directBookingLabel}>Time</Text>
              <TouchableOpacity
                style={styles.directBookingInput}
                onPress={() => {
                  setShowDirectTimePicker(true);
                  if (Platform.OS === 'ios') {
                    setShowDirectDatePicker(false);
                  }
                }}
              >
                <Text>{directBookDateTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</Text>
              </TouchableOpacity>

              {(showDirectDatePicker || showDirectTimePicker) && Platform.OS === 'ios' && (
                <View style={styles.directBookingPickerWrap}>
                  {showDirectDatePicker && (
                    <DateTimePicker
                      value={directBookDateTime}
                      mode="date"
                      display="spinner"
                      minimumDate={new Date()}
                      onChange={handleDirectDateChange}
                    />
                  )}
                  {showDirectTimePicker && (
                    <DateTimePicker
                      value={directBookDateTime}
                      mode="time"
                      display="spinner"
                      onChange={handleDirectTimeChange}
                    />
                  )}
                </View>
              )}

              {showDirectDatePicker && Platform.OS === 'android' && (
                <DateTimePicker
                  value={directBookDateTime}
                  mode="date"
                  display="default"
                  minimumDate={new Date()}
                  onChange={handleDirectDateChange}
                />
              )}

              {showDirectTimePicker && Platform.OS === 'android' && (
                <DateTimePicker
                  value={directBookDateTime}
                  mode="time"
                  display="default"
                  onChange={handleDirectTimeChange}
                />
              )}

              <Text style={styles.directBookingLabel}>Notes</Text>
              <TextInput
                style={styles.directBookingTextArea}
                multiline
                numberOfLines={4}
                value={directBookNotes}
                onChangeText={setDirectBookNotes}
                placeholder="Share what you want to discuss..."
                placeholderTextColor="#94a3b8"
              />

              <Text style={styles.directBookingHint}>Sent to the consultant for confirmation.</Text>
            </ScrollView>

            <View style={styles.directBookingActions}>
              <TouchableOpacity
                style={styles.directBookingCancelBtn}
                onPress={() => setShowDirectBookingModal(false)}
              >
                <Text style={styles.directBookingCancelText}>Cancel</Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={[styles.directBookingSendBtn, directBookLoading && styles.directBookingSendBtnDisabled]}
                onPress={handleDirectBooking}
                disabled={directBookLoading}
              >
                <Text style={styles.directBookingSendText}>
                  {directBookLoading ? 'Sending...' : 'Send Request'}
                </Text>
              </TouchableOpacity>
            </View>
          </View>
        </View>
      </Modal>
    </SafeAreaView>
  );
}

