// CounselorDirectoryScreen.js
import React, { useEffect, useMemo, useState, useCallback, useRef } from "react";
import {
  View,
  FlatList,
  TouchableOpacity,
  Image,
  ActivityIndicator,
  RefreshControl,
  SafeAreaView,
  StatusBar,
  Modal,
  ScrollView,
    StyleSheet,
  Alert,
  AppState,
  KeyboardAvoidingView,
} from "react-native";
import TextInput from '../../../../../../components/TranslatedTextInput';
import Text from '../../../../../../components/TranslatedText';
import { useContentDimensions } from '../../../../../../components/common/ResponsiveLayout';
import useLanguageRender from "../../../../../../hooks/useLanguageRender";
import TranslatedMessageBubble from "../../../../../../components/TranslatedMessageBubble";
import AsyncStorage from "@react-native-async-storage/async-storage";
import socketService from "../../../../../../services/socketService";
import DateTimePicker from '@react-native-community/datetimepicker';
import api, { API_BASE_URL } from "../../../../../../axiosConfig";
import StarRating from "../../../../../../components/StarRating";
import { useAutoTranslate } from "../../../../../../hooks/useAutoTranslate";
import LinearGradient from "react-native-linear-gradient";
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { DOCTOR, PATIENT } from '../../../../../../theme/palette';
import { getCachedLocationSummary } from '../../../../../../utils/locationHelper';
import {
  formatDistance,
  getDistanceToProfessional,
  getUserCoords,
  isNearby,
} from '../../../../../../utils/nearby';
import { nextSlotTime } from '../../../../../../utils/appointmentTime';
import { isPsychiatristSpecialization } from '../../../../../../components/common/PsychiatristDirectory';

// Same gradient and direction as the wallet balance card.
const WALLET_GRADIENT = ["#006B2C", "#01CE54"];
// Lets an inactive pill keep its own background behind an identically sized
// gradient layer, so selecting a chip cannot change its width.
const TRANSPARENT_GRADIENT = ["transparent", "transparent"];
const GRADIENT_START = { x: 0, y: 0.5 };
const GRADIENT_END = { x: 1, y: 0.5 };

/**
 * Filter pill. Active state is the wallet gradient rather than a flat fill.
 * Both states render the same tree with the same metrics - only the gradient
 * stops and text colour change - so selecting a chip never resizes the row.
 */
const FilterChip = ({ label, active, onPress }) => {
  const { styles } = useResponsiveScreenStyles();
  return (<TouchableOpacity onPress={onPress} activeOpacity={0.85} style={styles.filterChipWrap}>
    <LinearGradient
      colors={active ? WALLET_GRADIENT : TRANSPARENT_GRADIENT}
      start={GRADIENT_START}
      end={GRADIENT_END}
      style={[styles.filterChip, active && styles.filterChipActive]}
    >
      <Text style={[styles.filterChipText, active && styles.filterChipTextActive]}>{label}</Text>
    </LinearGradient>
  </TouchableOpacity>);
};

// Psychiatrists are medical doctors (can prescribe); everyone else in this
// directory is a non-medical counselor/therapist. Same classifier already
// used by PsychiatristDirectory, surfaced here as a small badge so the two
// read differently at a glance.
// NOTE: the backend's `role` field is only ever "user" / "counsellor" / "admin"
// — there is no "doctor" value in the DB (DoctorSignup stores a real
// `counsellor`-role account; "Doctor" is a local-only label on that device).
// So a Doctor account can only be told apart from a Consultant by its
// specialization, which DoctorSignup enforces must contain "Psychiatrist" —
// the same signal isPsychiatristSpecialization already uses.
const isDoctorRole = (person) =>
  isPsychiatristSpecialization(person?.specialization);

const RoleBadge = ({ isDoctor }) => {
  const { styles } = useResponsiveScreenStyles();
  return (<View style={[styles.roleBadge, isDoctor ? styles.roleBadgeDoctor : styles.roleBadgeConsultant]}>
    <Text style={[styles.roleBadgeText, isDoctor ? styles.roleBadgeTextDoctor : styles.roleBadgeTextConsultant]}>
      {isDoctor ? 'Doctor' : 'Consultant'}
    </Text>
  </View>);
};



// Counselor availability status → display color + label (mirrors the counselor
// settings picker). 'offline' is used as the fallback when status is unknown.
const AVAIL_STATUS_META = {
  online:  { color: "#10B981", label: "Online" },
  busy:    { color: "#EF4444", label: "Busy" },
  away:    { color: "#F59E0B", label: "Away" },
  offline: { color: "#94A3B8", label: "Offline" },
};

// Utility Functions
const getInitials = (name = "Consultant") =>
  name
    .split(" ")
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join("") || "CO";

const normalizeArray = (value) => {
  if (Array.isArray(value)) return value.filter(Boolean);
  if (typeof value === "string" && value.trim()) return [value.trim()];
  return [];
};

const isCompletedCounselorProfile = (counselor) => {
  const specializations = normalizeArray(counselor?.specialization);
  return (
    counselor?.profileCompleted === true &&
    specializations.length > 0 &&
    Number(counselor?.experience || 0) > 0 &&
    Boolean(counselor?.location) &&
    Boolean(counselor?.qualification || counselor?.education)
  );
};

const getProfilePhotoUrl = (counselor) => {
  if (!counselor) return null;
  
  if (counselor.profilePhoto) {
    if (typeof counselor.profilePhoto === "string") {
      if (counselor.profilePhoto.startsWith("http")) {
        return counselor.profilePhoto;
      }
      return `${API_BASE_URL}${counselor.profilePhoto}`;
    }
    if (counselor.profilePhoto.url) {
      if (counselor.profilePhoto.url.startsWith("http")) {
        return counselor.profilePhoto.url;
      }
      return `${API_BASE_URL}${counselor.profilePhoto.url}`;
    }
  }
  
  if (counselor.avatar) {
    if (counselor.avatar.startsWith("http")) {
      return counselor.avatar;
    }
    return `${API_BASE_URL}${counselor.avatar}`;
  }
  
  return null;
};

const CounselorDirectoryScreen = ({ navigation }) => {
  const { styles } = useResponsiveScreenStyles();
  const { width: contentWidth } = useContentDimensions();
  const columns = contentWidth >= 900 ? 2 : 1;
  const insets = useSafeAreaInsets();
  const { t } = useLanguageRender();
  const [searchTerm, setSearchTerm] = useState("");
  const [searchLocation, setSearchLocation] = useState("");
  const [selectedCategory, setSelectedCategory] = useState("all");
  // The user's own coordinates, so "Nearby" is a real distance and not a guess
  // from the free-text location box above it.
  const [userCoords, setUserCoords] = useState(null);
  const [sortBy, setSortBy] = useState("online");
  const [counselorsData, setCounselorsData] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");
  const [refreshing, setRefreshing] = useState(false);
  const [selectedCounselor, setSelectedCounselor] = useState(null);
  const [showBookingModal, setShowBookingModal] = useState(false);
  const [showChatModal, setShowChatModal] = useState(false);
  // Offered booking time starts on a clean slot (:00/:15/:30/:45) about an
  // hour ahead, not "now" — that saved odd times like 14:33.
  const [bookingDate, setBookingDate] = useState(() => nextSlotTime(60));
  const [bookingNotes, setBookingNotes] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [userAnonymous, setUserAnonymous] = useState("");
  const [uniqueLocations, setUniqueLocations] = useState([]);
  const [showLocationDropdown, setShowLocationDropdown] = useState(false);
  const [imageErrors, setImageErrors] = useState({});
  const socketRef = useRef(null);

  // Get user data
  useEffect(() => {
    const getUserData = async () => {
      try {
        const storedAnonymous = await AsyncStorage.getItem("userAnonymousName");
        if (storedAnonymous) {
          setUserAnonymous(storedAnonymous);
        } else {
          const userId = await AsyncStorage.getItem("userId");
          if (userId) {
            try {
              const response = await api.get(`/api/auth/getUser/${userId}`);
              if (response.data.success && response.data.user) {
                const anonymousName = response.data.user.anonymous || response.data.user.fullName || response.data.user.name || `Anonymous_${Math.floor(Math.random() * 10000)}`;
                setUserAnonymous(anonymousName);
                await AsyncStorage.setItem("userAnonymousName", anonymousName);
                return;
              }
            } catch (err) {
              console.error("Error fetching user:", err);
            }
          }
          const anonymousName = `Anonymous_${Math.floor(Math.random() * 10000)}`;
          setUserAnonymous(anonymousName);
          await AsyncStorage.setItem("userAnonymousName", anonymousName);
        }
      } catch (error) {
        console.error("Error getting user data:", error);
        const anonymousName = `Anonymous_${Math.floor(Math.random() * 10000)}`;
        setUserAnonymous(anonymousName);
      }
    };
    getUserData();
  }, []);

  // Fetch counselors using the api instance
  const fetchCounselors = useCallback(async (showLoader = true) => {
    try {
      if (showLoader) {
        setError("");
        setIsLoading(true);
      }

      // Same endpoint the web directory uses. It returns counsellors AND
      // doctors (role === 'doctor') with live socket presence.
      const response = await api.get("/api/auth/counsellors", {
        headers: { 'Cache-Control': 'no-cache' },
      });

      let counselors = [];
      if (response.data?.counselors) {
        counselors = response.data.counselors;
      } else if (response.data?.counsellors) {
        counselors = response.data.counsellors;
      } else if (Array.isArray(response.data)) {
        counselors = response.data;
      }
      
      console.log("Number of counselors fetched:", counselors.length);
      
      // Doctors are listed as the backend returns them (same as web); the
      // completed-profile rule only applies to counselors.
      const visibleCounselors = counselors.filter(
        (c) => isDoctorRole(c) || isCompletedCounselorProfile(c),
      );

      const formattedCounselors = visibleCounselors.map((c, index) => {
        const profilePhotoUrl = getProfilePhotoUrl(c);
        
        return {
          id: c._id || c.id || index.toString(),
          role: String(c.role || '').trim().toLowerCase(),
          isDoctor: isDoctorRole(c),
          name: c.fullName || c.name || "Consultant",
          specialization: Array.isArray(c.specialization) ? c.specialization.join(", ") : (c.specialization || "General"),
          experience: c.experience || 0,
          // Real aggregate rating from the backend (0 when not yet rated).
          rating: Number(c.rating ?? c.averageRating ?? 0),
          ratingCount: Number(c.ratingCount ?? c.totalRatings ?? c.reviewsCount ?? 0),
          online: Boolean(c.isOnline),
          active: Boolean(c.isActive),
          available: Boolean(c.isOnline) && Boolean(c.isActive),
          canSchedule: true,
          // Counselor's self-set availability. Only meaningful while online;
          // when socket-offline we show 'offline' regardless.
          availabilityStatus: Boolean(c.isOnline)
            ? (c.availabilityStatus || 'online')
            : 'offline',
          lastSeen: c.lastSeen || null,
          profilePhoto: profilePhotoUrl,
          avatarType: profilePhotoUrl ? "image" : "text",
          expertise: Array.isArray(c.specialization) ? c.specialization : (c.specialization ? [c.specialization] : []),
          responseTime: c.responseTime || "< 10 seconds",
          email: c.email,
          phone: c.phoneNumber,
          location: c.location || "Online",
          // Carried through so Nearby can measure an actual distance; the
          // directory payload keeps coordinates under locationData.current.
          locationData: c.locationData,
          languages: c.languages || [],
          aboutMe: c.aboutMe,
          qualification: c.qualification,
          totalSessions: c.totalSessions || 0,
          profileCompleted: c.profileCompleted === true,
        };
      });
      
      setCounselorsData(formattedCounselors);
      
      const locations = [...new Set(
        formattedCounselors
          .map(c => c.location)
          .filter(l => l && l !== "Online" && l.trim())
      )];
      // Use server-provided fields only: isOnline for live presence, isActive for availability setting.
      // Chat requires both. Scheduling remains available for later even when a consultant is offline.
      setUniqueLocations(locations);
      if (!showLoader) setError("");

    } catch (err) {
      console.error("Failed to fetch counselors:", err);
      if (showLoader) {
        setError(err.response?.data?.message || "Unable to load consultants right now. Please check your connection.");
      }
    } finally {
      if (showLoader) setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchCounselors(true);

    // Real-time reconciliation, same as web: silent re-fetch every 15s so newly
    // registered/updated doctors and counselors appear without a manual refresh.
    const timer = setInterval(() => fetchCounselors(false), 15000);
    const appStateSub = AppState.addEventListener('change', (state) => {
      if (state === 'active') fetchCounselors(false);
    });
    return () => {
      clearInterval(timer);
      appStateSub?.remove?.();
    };
  }, [fetchCounselors]);

  // Socket connection for real-time updates
  useEffect(() => {
    let socket = null;
    
    const setupSocket = async () => {
      const unsubscribers = [];
      try {
        const token = await AsyncStorage.getItem("accessToken") || await AsyncStorage.getItem("token");
        if (!token) {
          console.log("No token found, skipping socket connection");
          return;
        }

        const socket = await socketService.connect();
        socketRef.current = socket;

        unsubscribers.push(await socketService.on('connect', () => console.log('Socket connected successfully')));
        unsubscribers.push(await socketService.on('presence-update', ({ userId, isOnline, lastSeen }) => {
          console.log('[presence] event userId=', userId, 'isOnline=', isOnline);
          setCounselorsData((prev) => {
            const matched = prev.find((c) => String(c.id) === String(userId));
            if (!matched) {
              console.log('[presence] event for unknown counselor:', userId, 'have:', prev.map((c) => c.id));
            }
            return prev.map((counselor) => String(counselor.id) === String(userId)
              ? {
                  ...counselor,
                  online: isOnline,
                  available: Boolean(isOnline) && counselor.active !== false,
                  // Going offline forces 'offline'; coming online keeps the
                  // counselor's manual status if known, else defaults to online.
                  availabilityStatus: isOnline
                    ? (counselor.availabilityStatus && counselor.availabilityStatus !== 'offline'
                        ? counselor.availabilityStatus
                        : 'online')
                    : 'offline',
                  lastSeen,
                }
              : counselor);
          });
        }));

        // Backend emits this when the directory changes (same event the web uses).
        unsubscribers.push(await socketService.on('counselor-directory-updated', () => fetchCounselors(false)));
        unsubscribers.push(await socketService.on('connect', () => fetchCounselors(false)));

        unsubscribers.push(await socketService.on('connect_error', (err) => console.error('Socket connection error:', err?.message || err)));

        socketRef.current._unsubscribers = unsubscribers;
      } catch (error) {
        console.error('Error setting up socket:', error);
      }
    };

    setupSocket();

    return () => {
      try { const unsub = socketRef.current?._unsubscribers || []; unsub.forEach(fn => { try { fn(); } catch {} }); } catch (e) {}
      if (socketRef.current) socketRef.current = null;
    };
  }, [fetchCounselors]);

  const onRefresh = useCallback(async () => {
    setRefreshing(true);
    await fetchCounselors();
    setRefreshing(false);
  }, [fetchCounselors]);

  // Location the app already captured for this user (cached by locationHelper
  // after /api/location/update).
  useEffect(() => {
    let active = true;
    getCachedLocationSummary()
      .then((summary) => { if (active) setUserCoords(getUserCoords(summary)); })
      .catch(() => { /* Nearby just stays unavailable */ });
    return () => { active = false; };
  }, []);

  // Real distance per professional, attached once so the chip, the sort and the
  // card badge all read the same number.
  const counselorsWithDistance = useMemo(
    () => counselorsData.map((counselor) => {
      const km = getDistanceToProfessional(userCoords, counselor);
      return { ...counselor, distanceKm: km, distanceLabel: formatDistance(km), isNearby: isNearby(km) };
    }),
    [counselorsData, userCoords],
  );

  // Only offer Nearby when we know where the user is and someone is in range.
  const hasNearbyAvailable = Boolean(userCoords) && counselorsWithDistance.some((c) => c.isNearby);

  // If Nearby stops being available while it's selected its chip disappears,
  // which would leave an empty list and no chip to switch off. Fall back to All.
  useEffect(() => {
    if (selectedCategory === 'nearby' && !hasNearbyAvailable) setSelectedCategory('all');
  }, [selectedCategory, hasNearbyAvailable]);

  const statusFilterChips = useMemo(() => ([
    { id: 'all', label: t('common:all', 'All') },
    ...(hasNearbyAvailable ? [{ id: 'nearby', label: t('common:nearby', 'Nearby') }] : []),
    { id: 'online', label: t('common:online', 'Online') },
    { id: 'offline', label: t('common:offline', 'Offline') },
    { id: 'doctor', label: t('common:doctor', 'Doctor') },
    { id: 'consultant', label: t('common:consultant', 'Consultant') },
  ]), [t, hasNearbyAvailable]);

  const filteredAndSortedCounselors = useMemo(() => {
    let filtered = counselorsWithDistance.filter((counselor) => {
      const name = (counselor.name || "").toLowerCase();
      const specialization = (counselor.specialization || "").toLowerCase();
      const aboutMe = (counselor.aboutMe || "").toLowerCase();
      const location = (counselor.location || "").toLowerCase();
      const languages = (counselor.languages || []).join(" ").toLowerCase();
      const expertise = (counselor.expertise || []).join(" ").toLowerCase();
      const qualification = (counselor.qualification || "").toLowerCase();
      const status = counselor.online ? "online available" : "offline unavailable";
      
      const searchableText = `${name} ${specialization} ${aboutMe} ${location} ${languages} ${expertise} ${qualification} ${status}`;
      const matchesSearch = searchTerm === "" || searchableText.includes(searchTerm.toLowerCase());
      
      const matchesLocation = searchLocation === "" || location.includes(searchLocation.toLowerCase());
      
      const matchesCategory =
        selectedCategory === "all" ||
        (selectedCategory === "nearby" && counselor.isNearby) ||
        (selectedCategory === "online" && counselor.online) ||
        (selectedCategory === "offline" && !counselor.online) ||
        (selectedCategory === "doctor" && counselor.isDoctor) ||
        (selectedCategory === "consultant" && !counselor.isDoctor);

      return matchesSearch && matchesLocation && matchesCategory;
    });

    filtered.sort((a, b) => {
      // Under Nearby, closest first regardless of the chosen sort — that is
      // what the filter is for.
      if (selectedCategory === "nearby") {
        const byDistance = (a.distanceKm ?? Infinity) - (b.distanceKm ?? Infinity);
        if (byDistance) return byDistance;
      }
      if (sortBy === "online") return Number(b.online) - Number(a.online);
      if (sortBy === "rating") return (b.rating || 0) - (a.rating || 0);
      if (sortBy === "experience") return (b.experience || 0) - (a.experience || 0);
      if (sortBy === "name") return (a.name || "").localeCompare(b.name || "");
      return 0;
    });

    return filtered;
  }, [counselorsWithDistance, searchTerm, searchLocation, selectedCategory, sortBy]);

  const handleImageError = (counselorId) => {
    setImageErrors(prev => ({ ...prev, [counselorId]: true }));
  };

  // Send chat request - Handle existing chat gracefully
  const handleSendChatRequest = async () => {
    if (!selectedCounselor) return;
    if (!selectedCounselor.profileCompleted) {
      Alert.alert("Consultant Unavailable", "This consultant profile is not complete yet.");
      setShowChatModal(false);
      resetChatForm();
      return;
    }

    setIsSubmitting(true);
    try {
      const token = await AsyncStorage.getItem("accessToken") || await AsyncStorage.getItem("token");
      if (!token) {
        Alert.alert("Error", "Please login to start a chat");
        setIsSubmitting(false);
        return;
      }

      const response = await api.post("/api/chat/start", {
        counselorId: selectedCounselor.id,
      });

      console.log("Chat request response:", response.data);

      // Handle existing chat case
      if (response.data.error === "Chat already active. Please continue your conversation." || 
          response.data.status === "accepted" ||
          response.data.chatId) {
        
        const chatId = response.data.chatId;
        Alert.alert(
          "Chat Available",
          `You already have an active chat with ${selectedCounselor.name}. Would you like to continue?`,
          [
            { 
              text: "Cancel", 
              style: "cancel",
              onPress: () => {
                setShowChatModal(false);
                resetChatForm();
              }
            },
            { 
              text: "Continue Chat", 
              onPress: () => {
                setShowChatModal(false);
                resetChatForm();
                navigation.navigate("Chat", {
                  chatId: chatId,
                  counselorId: selectedCounselor.id,
                  counselor: selectedCounselor,
                  userAnonymous: userAnonymous,
                });
              }
            }
          ]
        );
      } 
      // Handle successful new chat request
      else if (response.data.success || response.data.message === "Chat request sent successfully") {
        Alert.alert(
          "Success",
          `Chat request sent to ${selectedCounselor.name}! You'll be notified when they accept.`,
          [{ 
            text: "OK", 
            onPress: () => {
              setShowChatModal(false);
              resetChatForm();
            }
          }]
        );
      } 
      else {
        Alert.alert("Error", response.data?.message || "Failed to send chat request");
      }
    } catch (error) {
      console.error("Chat request error:", error);
      console.error("Error response:", error.response?.data);
      
      // Handle error response from server
      if (error.response?.data?.error === "Chat already active. Please continue your conversation." ||
          error.response?.data?.status === "accepted" ||
          error.response?.data?.status === "active") {

        const chatId = error.response?.data?.chatId;
        Alert.alert(
          "Chat Available",
          `You already have an active chat with ${selectedCounselor.name}. Would you like to continue?`,
          [
            { 
              text: "Cancel", 
              style: "cancel",
              onPress: () => {
                setShowChatModal(false);
                resetChatForm();
              }
            },
            { 
              text: "Continue Chat", 
              onPress: () => {
                setShowChatModal(false);
                resetChatForm();
                navigation.navigate("Chat", {
                  chatId: chatId,
                  counselorId: selectedCounselor.id,
                  counselor: selectedCounselor,
                  userAnonymous: userAnonymous,
                });
              }
            }
          ]
        );
      } else if (error.response?.data?.reason === "counselor_unavailable") {
        // Counselor has marked themselves Busy or Offline.
        Alert.alert(
          "Consultant Unavailable",
          error.response.data.error ||
            "This consultant is not available right now. Please try again later."
        );
      } else if (error.response?.data?.status === "pending") {
        // Request already sent and waiting for the counselor to accept — not an error.
        Alert.alert(
          "Request Sent",
          `Your request to ${selectedCounselor.name} was already sent. Please wait for them to accept.`,
          [{ text: "OK", onPress: () => { setShowChatModal(false); resetChatForm(); } }]
        );
      } else {
        let errorMessage = "Failed to send chat request";
        if (error.response?.status === 401) {
          errorMessage = "Please login again to chat";
        } else if (error.response?.data?.message || error.response?.data?.error) {
          errorMessage = error.response.data.message || error.response.data.error;
        }
        Alert.alert("Error", errorMessage);
      }
    } finally {
      setIsSubmitting(false);
    }
  };

  // Book appointment - Handle success properly
  const handleConfirmBooking = async () => {
    if (!selectedCounselor?.profileCompleted) {
      Alert.alert("Consultant Unavailable", "This consultant profile is not complete yet.");
      setShowBookingModal(false);
      resetBookingForm();
      return;
    }
    if (!bookingDate) {
      Alert.alert("Error", "Please select a date and time");
      return;
    }
    if (!bookingNotes.trim()) {
      Alert.alert("Error", "Please provide some notes about your concern");
      return;
    }

    setIsSubmitting(true);
    try {
      const token = await AsyncStorage.getItem("accessToken") || await AsyncStorage.getItem("token");
      if (!token) {
        Alert.alert("Error", "Please login to book an appointment");
        setIsSubmitting(false);
        return;
      }

      const formattedDate = bookingDate.toISOString();
      
      const response = await api.post("/api/appointments", {
        counselorId: selectedCounselor.id,
        date: formattedDate,
        notes: bookingNotes,
      });

      console.log("Booking response:", response.data);

      // Check if appointment was created successfully
      if (response.data._id || response.data.success || response.data.message === "Appointment booked successfully") {
        Alert.alert(
          "Success",
          "Appointment booked successfully! The consultant has been notified.",
          [{ 
            text: "OK", 
            onPress: () => {
              setShowBookingModal(false);
              resetBookingForm();
            }
          }]
        );
      } else {
        Alert.alert("Error", response.data?.message || "Failed to book appointment");
      }
    } catch (error) {
      console.error("Booking error:", error);
      
      let errorMessage = "Failed to book appointment";
      if (error.response?.status === 401) {
        errorMessage = "Please login again to book";
      } else if (error.response?.data?.message) {
        errorMessage = error.response.data.message;
      }
      
      Alert.alert("Error", errorMessage);
    } finally {
      setIsSubmitting(false);
    }
  };

  const resetBookingForm = () => {
    setBookingDate(nextSlotTime(60));
    setBookingNotes("");
    setSelectedCounselor(null);
  };

  const resetChatForm = () => {
    setSelectedCounselor(null);
  };

  const renderCounselorCard = ({ item: counselor }) => {
    const name = counselor.name || "Consultant";
    const location = counselor.location || "Online";
    const hasImageError = imageErrors[counselor.id];
    const profilePhotoUrl = !hasImageError ? counselor.profilePhoto : null;
    const statusMeta =
      AVAIL_STATUS_META[counselor.availabilityStatus] || AVAIL_STATUS_META.offline;
    const canChatNow = Boolean(counselor.available);
    const canSchedule = counselor.canSchedule !== false;

    return (
      <View style={styles.card}>
        <View style={styles.cardHeader}>
          <View style={styles.avatarContainer}>
            {profilePhotoUrl ? (
              <Image 
                source={{ uri: profilePhotoUrl }} 
                style={styles.avatar}
                onError={() => handleImageError(counselor.id)}
              />
            ) : (
              <View style={styles.avatarInitials}>
                <Text style={styles.initialsText}>{getInitials(name)}</Text>
              </View>
            )}
            <View style={[styles.presenceDot, { backgroundColor: statusMeta.color }]} />
          </View>
          
          <View style={styles.counselorInfo}>
            <View style={styles.nameRow}>
              <Text style={styles.counselorName}>{name}</Text>
              <RoleBadge isDoctor={counselor.isDoctor} />
            </View>
            <Text style={styles.specialization} numberOfLines={1}>
              {counselor.specialization}
            </Text>
            {counselor.ratingCount > 0 && (
              <StarRating
                rating={counselor.rating}
                count={counselor.ratingCount}
                size={14}
                style={styles.ratingRow}
              />
            )}
            <View style={styles.locationRow}>
              {location !== "Online" && (
                <Text style={styles.locationText}>📍 {location}</Text>
              )}
              {counselor.isNearby && (
                <View style={styles.nearbyBadge}>
                  <Text style={styles.nearbyBadgeText}>{counselor.distanceLabel} away</Text>
                </View>
              )}
            </View>
          </View>

          <View style={[styles.statusPill, { backgroundColor: `${statusMeta.color}1A` }]}>
            <View style={[styles.statusPillDot, { backgroundColor: statusMeta.color }]} />
            <Text style={[styles.statusPillText, { color: statusMeta.color }]}>
              {statusMeta.label}
            </Text>
          </View>
        </View>

        <View style={styles.tagsContainer}>
          {counselor.expertise && counselor.expertise.slice(0, 3).map((spec, idx) => (
            <View key={idx} style={styles.tag}>
              <Text style={styles.tagText}>{spec}</Text>
            </View>
          ))}
        </View>

        <View style={styles.statsGrid}>
          <View style={styles.statItem}>
            <TranslatedMessageBubble text={t('profile:rating')} style={styles.statLabel} />
            <Text style={styles.statValue}>
              {counselor.ratingCount > 0 ? `★ ${counselor.rating.toFixed(1)}` : t('profile:notSpecified')}
            </Text>
          </View>
          <View style={styles.statItem}>
            <Text style={styles.statLabel}>{t('profile:experience')}</Text>
            <Text style={styles.statValue}>{counselor.experience || 0}y</Text>
          </View>
        </View>

        <View style={styles.cardFooter}>
          <View style={styles.languagesContainer}>
            {counselor.languages && counselor.languages.slice(0, 2).map((lang, idx) => (
              <Text key={idx} style={styles.language}>{lang}</Text>
            ))}
          </View>
          <View style={styles.actionButtons}>
            {counselor.isDoctor ? (
              // Doctors: no chat (same as web). Clinic/slot booking is not in the app yet.
              <TouchableOpacity
                style={[styles.actionBtn, styles.bookBtn]}
                onPress={() =>
                  Alert.alert(
                    "Doctor appointment",
                    "Booking an appointment with a doctor will be available in the app soon."
                  )
                }
              >
                <Text style={styles.actionBtnText}>📅 Book</Text>
              </TouchableOpacity>
            ) : (
              <>
            <TouchableOpacity
              style={[styles.actionBtn, styles.chatBtn, !canChatNow && styles.disabledBtn]}
              onPress={() => {
                setSelectedCounselor(counselor);
                setShowChatModal(true);
              }}
              disabled={!canChatNow}
            >
              <Text style={styles.actionBtnText}>
                {counselor.available ? "💬 " + t('appointment:chatNow') : "🔴 " + t('counselor:available')}
              </Text>
            </TouchableOpacity>
            <TouchableOpacity
              style={[styles.actionBtn, styles.bookBtn, !canSchedule && styles.disabledBtn]}
              onPress={() => {
                setSelectedCounselor(counselor);
                setShowBookingModal(true);
              }}
              disabled={!canSchedule}
            >
              <Text style={styles.actionBtnText}>Schedule</Text>
            </TouchableOpacity>
              </>
            )}
          </View>
        </View>
      </View>
    );
  };

  if (isLoading && !refreshing) {
    return (
      <View style={styles.loadingContainer}>
        <ActivityIndicator size="large" color={PATIENT.primary} />
        <Text style={styles.loadingText}>Loading consultants...</Text>
      </View>
    );
  }

  return (
    <SafeAreaView style={styles.container}>
      <StatusBar barStyle="dark-content" backgroundColor="#F8FAFC" />

      <FlatList
        key={`consultants-${columns}`}
        numColumns={columns}
        data={filteredAndSortedCounselors}
        renderItem={(item) => <View style={{ flex: 1, maxWidth: `${100 / columns}%` }}>{renderCounselorCard(item)}</View>}
        keyExtractor={(item) => item.id}
        refreshControl={
          <RefreshControl refreshing={refreshing} onRefresh={onRefresh} />
        }
        ListHeaderComponent={
          <>
            {/* Search Section */}
            <View style={styles.searchSection}>
              <View style={styles.searchWrapper}>
                <Text style={styles.searchIcon}>🔍</Text>
                <TextInput
                  style={styles.searchInput}
                  placeholder={t('messages:searchCounselors')}
                  placeholderTextColor="#94A3B8"
                  value={searchTerm}
                  onChangeText={setSearchTerm}
                />
                {searchTerm.length > 0 && (
                  <TouchableOpacity onPress={() => setSearchTerm("")}>
                    <Text style={styles.searchClear}>✕</Text>
                  </TouchableOpacity>
                )}
              </View>

              <View style={styles.locationWrapper}>
                <Text style={styles.locationIcon}>📍</Text>
                <TextInput
                  style={styles.locationInput}
                  placeholder="Search by location..."
                  placeholderTextColor="#94A3B8"
                  value={searchLocation}
                  onChangeText={(text) => {
                    setSearchLocation(text);
                    setShowLocationDropdown(true);
                  }}
                  onFocus={() => setShowLocationDropdown(true)}
                />
                {searchLocation.length > 0 && (
                  <TouchableOpacity onPress={() => setSearchLocation("")}>
                    <Text style={styles.searchClear}>✕</Text>
                  </TouchableOpacity>
                )}
              </View>

              {/* Location Dropdown */}
              {showLocationDropdown && uniqueLocations.length > 0 && searchLocation.length > 0 && (
                <View style={styles.locationDropdown}>
                  <ScrollView style={styles.dropdownScroll} nestedScrollEnabled>
                    {uniqueLocations
                      .filter(location => 
                        location.toLowerCase().includes(searchLocation.toLowerCase())
                      )
                      .map((location, index) => (
                        <TouchableOpacity
                          key={index}
                          style={styles.locationOption}
                          onPress={() => {
                            setSearchLocation(location);
                            setShowLocationDropdown(false);
                          }}
                        >
                          <Text>📍 {location}</Text>
                        </TouchableOpacity>
                      ))}
                  </ScrollView>
                </View>
              )}

              {/* Filter Stats */}
              {(searchTerm || searchLocation || selectedCategory !== "all") && (
                <View style={styles.filterStats}>
                  <Text style={styles.filterCount}>
                    Found {filteredAndSortedCounselors.length} consultant(s)
                  </Text>
                  <TouchableOpacity onPress={() => {
                    setSearchTerm("");
                    setSearchLocation("");
                    setSelectedCategory("all");
                  }}>
                    <Text style={styles.clearFilters}>Clear Filters</Text>
                  </TouchableOpacity>
                </View>
              )}
            </View>

            {/* Filter Chips */}
            <View style={styles.filtersContainer}>
              <ScrollView horizontal showsHorizontalScrollIndicator={false}>
                {statusFilterChips.map((chip) => (
                  <FilterChip
                    key={chip.id}
                    label={chip.label}
                    active={selectedCategory === chip.id}
                    onPress={() => setSelectedCategory(chip.id)}
                  />
                ))}
              </ScrollView>
            </View>

            {/* Sort Bar */}
            <View style={styles.sortBar}>
              <ScrollView horizontal showsHorizontalScrollIndicator={false}>
                {["online", "name", "rating", "experience"].map((sort) => (
                  <TouchableOpacity
                    key={sort}
                    style={[styles.sortBtn, sortBy === sort && styles.sortBtnActive]}
                    onPress={() => setSortBy(sort)}
                  >
                    <Text style={[styles.sortBtnText, sortBy === sort && styles.sortBtnTextActive]}>
                      {sort.charAt(0).toUpperCase() + sort.slice(1)}
                    </Text>
                  </TouchableOpacity>
                ))}
              </ScrollView>
            </View>

            {error && (
              <View style={styles.errorContainer}>
                <Text style={styles.errorText}>{error}</Text>
                <TouchableOpacity style={styles.retryButton} onPress={fetchCounselors}>
                  <Text style={styles.retryButtonText}>Retry</Text>
                </TouchableOpacity>
              </View>
            )}

            {filteredAndSortedCounselors.length === 0 && !error && (
              <View style={styles.emptyState}>
                <Text style={styles.emptyIcon}>🔍</Text>
                <Text style={styles.emptyTitle}>No consultants found</Text>
                <Text style={styles.emptyText}>Try adjusting your search or filter</Text>
                <TouchableOpacity style={styles.resetButton} onPress={() => {
                  setSearchTerm("");
                  setSearchLocation("");
                  setSelectedCategory("all");
                }}>
                  <Text style={styles.resetButtonText}>Clear all filters</Text>
                </TouchableOpacity>
              </View>
            )}
          </>
        }
        contentContainerStyle={styles.listContent}
        showsVerticalScrollIndicator={false}
      />

      {/* Booking Modal */}
      <Modal
        visible={showBookingModal}
        animationType="slide"
        transparent={true}
        onRequestClose={() => {
          setShowBookingModal(false);
          resetBookingForm();
        }}
      >
        <KeyboardAvoidingView behavior="height" style={styles.modalOverlay}>
          <View style={[styles.modalContent, { paddingBottom: Math.max(insets.bottom, 20) }]}>
            <View style={styles.modalHeader}>
              <Text style={styles.modalTitle}>Book Appointment with {selectedCounselor?.name}</Text>
              <TouchableOpacity onPress={() => {
                setShowBookingModal(false);
                resetBookingForm();
              }}>
                <Text style={styles.modalClose}>✕</Text>
              </TouchableOpacity>
            </View>

            <ScrollView showsVerticalScrollIndicator={false}>
              <View style={styles.inputGroup}>
                <Text style={styles.inputLabel}>Select Date and Time</Text>
                <DateTimePicker
                  value={bookingDate}
                  mode="datetime"
                  display="default"
                  onChange={(event, selectedDate) => {
                    if (selectedDate) {
                      const picked = new Date(selectedDate);
                      picked.setSeconds(0, 0);
                      setBookingDate(picked);
                    }
                  }}
                  minimumDate={new Date()}
                />
              </View>

              <View style={styles.inputGroup}>
                <Text style={styles.inputLabel}>Clinical Notes / Reason (Required)</Text>
                <TextInput
                  style={styles.textArea}
                  placeholder="Share what you'd like to discuss..."
                  placeholderTextColor="#94A3B8"
                  multiline
                  numberOfLines={4}
                  value={bookingNotes}
                  onChangeText={setBookingNotes}
                />
              </View>

              <View style={styles.infoBox}>
                {selectedCounselor && !selectedCounselor.online && (
                  <View style={styles.infoRow}>
                    <Text style={styles.infoIcon}>i</Text>
                    <Text style={styles.infoText}>This consultant is offline right now, but you can still schedule an appointment for confirmation.</Text>
                  </View>
                )}
                <View style={styles.infoRow}>
                  <Text style={styles.infoIcon}>⏳</Text>
                  <Text style={styles.infoText}>Appointment will be sent for confirmation</Text>
                </View>
                <View style={styles.infoRow}>
                  <Text style={styles.infoIcon}>✅</Text>
                  <Text style={styles.infoText}>Consultant will be notified instantly</Text>
                </View>
              </View>

              <TouchableOpacity
                style={[styles.submitButton, isSubmitting && styles.submitButtonDisabled]}
                onPress={handleConfirmBooking}
                disabled={isSubmitting}
              >
                <Text style={styles.submitButtonText}>
                  {isSubmitting ? "Booking..." : "Confirm Appointment"}
                </Text>
              </TouchableOpacity>
            </ScrollView>
          </View>
        </KeyboardAvoidingView>
      </Modal>

      {/* Chat Request Modal */}
      <Modal
        visible={showChatModal}
        animationType="slide"
        transparent={true}
        onRequestClose={() => {
          setShowChatModal(false);
          resetChatForm();
        }}
      >
        <KeyboardAvoidingView behavior="height" style={styles.modalOverlay}>
          <View style={styles.modalContent}>
            <View style={styles.modalHeader}>
              <Text style={styles.modalTitle}>Start Chat with {selectedCounselor?.name}</Text>
              <TouchableOpacity onPress={() => {
                setShowChatModal(false);
                resetChatForm();
              }}>
                <Text style={styles.modalClose}>✕</Text>
              </TouchableOpacity>
            </View>

            <ScrollView showsVerticalScrollIndicator={false}>
              <View style={styles.userInfoCard}>
                <Text style={styles.userInfoIcon}>🔒</Text>
                <View style={styles.userInfoDetails}>
                  <Text style={styles.userInfoLabel}>You are chatting anonymously as:</Text>
                  <Text style={styles.userInfoName}>{userAnonymous || "Anonymous"}</Text>
                  <Text style={styles.userInfoNote}>This anonymous name will be shown to the consultant</Text>
                </View>
              </View>

              {selectedCounselor && (
                <View style={styles.counselorPreview}>
                  <View style={styles.counselorPreviewHeader}>
                    <View style={styles.counselorPreviewAvatar}>
                      {selectedCounselor.profilePhoto && !imageErrors[selectedCounselor.id] ? (
                        <Image 
                          source={{ uri: selectedCounselor.profilePhoto }} 
                          style={styles.previewAvatarImage}
                          onError={() => handleImageError(selectedCounselor.id)}
                        />
                      ) : (
                        <View style={styles.previewAvatarText}>
                          <Text>{getInitials(selectedCounselor.name)}</Text>
                        </View>
                      )}
                    </View>
                    <View style={styles.counselorPreviewInfo}>
                      <View style={styles.nameRow}>
                        <Text style={styles.counselorPreviewName}>{t(selectedCounselor.name)}</Text>
                        <RoleBadge isDoctor={selectedCounselor.isDoctor} />
                      </View>
                      <Text style={styles.counselorPreviewSpecialization}>{selectedCounselor.specialization}</Text>
                      {selectedCounselor.ratingCount > 0 && (
                        <StarRating
                          rating={selectedCounselor.rating}
                          count={selectedCounselor.ratingCount}
                          size={14}
                          showValue={true}
                        />
                      )}
                      {selectedCounselor.location && selectedCounselor.location !== "Online" && (
                        <Text style={styles.counselorPreviewLocation}>📍 {selectedCounselor.location}</Text>
                      )}
                    </View>
                  </View>
                </View>
              )}

              <View style={styles.infoBox}>
                <View style={styles.infoRow}>
                  <Text style={styles.infoIcon}>⏳</Text>
                  <Text style={styles.infoText}>Sends a request to the consultant</Text>
                </View>
                <View style={styles.infoRow}>
                  <Text style={styles.infoIcon}>✅</Text>
                  <Text style={styles.infoText}>You'll be notified when they accept</Text>
                </View>
                <View style={[styles.infoRow, styles.privacyRow]}>
                  <Text style={styles.infoIcon}>🔒</Text>
                  <Text style={[styles.infoText, styles.privacyNote]}>You are chatting anonymously. Your real identity is protected.</Text>
                </View>
              </View>

              <TouchableOpacity
                style={[styles.submitButton, isSubmitting && styles.submitButtonDisabled]}
                onPress={handleSendChatRequest}
                disabled={isSubmitting}
              >
                <Text style={styles.submitButtonText}>
                  {isSubmitting ? "Sending..." : "Send Request"}
                </Text>
              </TouchableOpacity>
            </ScrollView>
          </View>
        </KeyboardAvoidingView>
      </Modal>
    </SafeAreaView>
  );
};

