// ChatInterface.tsx - Android version with iOS design
import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import {
  View,
  TouchableOpacity,
  FlatList,
  ScrollView,
  Image,
  Modal,
  ActivityIndicator,
  SafeAreaView,
  StatusBar,
  Animated,
  Platform,
  Pressable,
  RefreshControl,
  Vibration,
  useWindowDimensions,
} from 'react-native';
import TextInput from '../../../../../../components/TranslatedTextInput';
import Text from '../../../../../../components/TranslatedText';
import { useNavigation, useFocusEffect } from '@react-navigation/native';
import { useTranslation } from 'react-i18next';
import AsyncStorage from '@react-native-async-storage/async-storage';
import axios from 'axios';
import socketService from '../../../../../../services/socketService';
import { API_BASE_URL } from '../../../../../../axiosConfig';
import safeVibrate from '../../../../../../utils/safeVibrate';
import { toImageUri } from '../../../../../../utils/imageUri';
import Ionicons from 'react-native-vector-icons/Ionicons';
import LinearGradient from 'react-native-linear-gradient';
import PATIENT from '../../../../../../theme/palette';
import useLanguageRender from '../../../../../../hooks/useLanguageRender';
import PatientGradientButton from '../../../../../../components/common/PatientGradientButton';
import { formatLocationLabel, getCachedLocationSummary } from '../../../../../../utils/locationHelper';

// Same gradient and direction as the wallet balance card.
const WALLET_GRADIENT = ['#006B2C', '#01CE54'];
// Lets the inactive pill keep its own background while rendering an identically
// sized gradient layer, so selecting a chip cannot change its width.
const TRANSPARENT_GRADIENT = ['transparent', 'transparent'];
const GRADIENT_START = { x: 0, y: 0.5 };
const GRADIENT_END = { x: 1, y: 0.5 };


const ChatListSkeleton = () => {
  const anim = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    const loop = Animated.loop(
      Animated.sequence([
        Animated.timing(anim, { toValue: 1, duration: 850, useNativeDriver: true }),
        Animated.timing(anim, { toValue: 0, duration: 850, useNativeDriver: true }),
      ])
    );
    loop.start();
    return () => loop.stop();
  }, [anim]);
  const opacity = anim.interpolate({ inputRange: [0, 1], outputRange: [0.35, 0.75] });
  return (
    <View style={chatSkel.wrap}>
      {[1, 2, 3, 4, 5, 6, 7].map((i) => (
        <View key={i} style={chatSkel.row}>
          <Animated.View style={[chatSkel.avatar, { opacity }]} />
          <View style={chatSkel.body}>
            <Animated.View style={[chatSkel.nameLine, { opacity }]} />
            <Animated.View style={[chatSkel.msgLine, { opacity }]} />
          </View>
          <Animated.View style={[chatSkel.time, { opacity }]} />
        </View>
      ))}
    </View>
  );
};

const chatSkel = {
  wrap: { flex: 1, width: '100%', paddingHorizontal: 14, paddingTop: 8 },
  row: {
    flexDirection: 'row',
    width: '100%',
    paddingVertical: 14,
    alignItems: 'center',
    borderBottomWidth: 1,
    borderBottomColor: '#F0F2F5',
  },
  avatar: { width: 50, height: 50, borderRadius: 25, backgroundColor: '#e2e8f0' },
  body: { flex: 1, marginLeft: 14, gap: 8 },
  nameLine: { width: '45%', height: 15, borderRadius: 5, backgroundColor: '#e2e8f0' },
  msgLine: { width: '75%', height: 12, borderRadius: 4, backgroundColor: '#edf1f5' },
  time: { width: 40, height: 10, borderRadius: 4, backgroundColor: '#edf1f5' },
};

const resolveOnlineStatus = (person) => {
  const explicitOnline = person?.isOnline ?? person?.online;
  if (typeof explicitOnline === 'boolean') return explicitOnline;
  if (typeof explicitOnline === 'string') return ['online', 'true', '1', 'yes'].includes(explicitOnline.toLowerCase());
  return false;
};

const ChatInterface = ({ setActiveTab, onOpenCounselor }) => {
  const navigation = useNavigation();
  const { t } = useLanguageRender();
  const { width: windowWidth, height: windowHeight } = useWindowDimensions();
  const compactEmptyState = windowHeight < 700 || windowWidth < 360;

  const [counselors, setCounselors] = useState([]);
  const [loading, setLoading] = useState(true);
  const [initialLoading, setInitialLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState(null);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [selectedCounselor, setSelectedCounselor] = useState(null);
  const [activeFilter, setActiveFilter] = useState('all');
  const [nearbyCounselors, setNearbyCounselors] = useState([]);
  const [nearbyLoading, setNearbyLoading] = useState(false);
  const [userLocationLabel, setUserLocationLabel] = useState('');
  const socketRef = useRef(null);

  const scaleAnim = useRef(new Animated.Value(1)).current;
  const longPressTimer = useRef(null);
  const pressedItemId = useRef(null);

  const getInitials = (name) => {
    if (!name) return '👤';
    return name.split(' ').map(n => n[0]).join('').toUpperCase().substring(0, 2);
  };

  const getAvatarColor = (name) => {
    if (!name) return '#4f46e5';
    const colors = [
      '#4f46e5', '#0891b2', '#059669', '#b45309', '#c2410c',
      '#7e22ce', '#be123c', '#1e40af', '#0f766e', '#6b21a8',
      '#d97706', '#dc2626', '#16a34a', '#9333ea', '#db2777'
    ];
    let hash = 0;
    for (let i = 0; i < name.length; i++) {
      hash = name.charCodeAt(i) + ((hash << 5) - hash);
    }
    return colors[Math.abs(hash) % colors.length];
  };

  const formatTime = (timeString) => {
    if (!timeString) return '';
    try {
      const messageTime = new Date(timeString);
      const now = new Date();
      const diffMs = now - messageTime;
      const diffMins = Math.floor(diffMs / 60000);
      const diffHours = Math.floor(diffMs / 3600000);
      const diffDays = Math.floor(diffMs / 86400000);

      if (diffMins < 1) return t('messages:justNow', 'Just now');
      if (diffHours < 1) return `${diffMins}m ago`;
      if (diffDays === 0) return messageTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      if (diffDays === 1) return t('messages:yesterday', 'Yesterday');
      if (diffDays < 7) return messageTime.toLocaleDateString([], { weekday: 'short' });
      if (diffDays < 30) return `${diffDays}d ago`;
      return messageTime.toLocaleDateString([], { month: 'short', day: 'numeric' });
    } catch {
      return '';
    }
  };

  const formatFullDateTime = (timeString) => {
    if (!timeString) return '';
    try {
      const date = new Date(timeString);
      return date.toLocaleString([], {
        year: 'numeric', month: 'long', day: 'numeric',
        hour: '2-digit', minute: '2-digit',
      });
    } catch {
      return timeString;
    }
  };

  const formatLastSeen = (lastSeen) => {
    if (!lastSeen) return t('common:offline', 'Offline');
    try {
      const lastSeenTime = new Date(lastSeen);
      const now = new Date();
      const diffMs = now - lastSeenTime;
      const diffMins = Math.floor(diffMs / 60000);
      const diffHours = Math.floor(diffMs / 3600000);
      const diffDays = Math.floor(diffMs / 86400000);

      if (diffMins < 1) return t('messages:justNow', 'Just now');
      if (diffHours < 1) return `${diffMins} minutes ago`;
      if (diffHours === 1) return '1 hour ago';
      if (diffHours < 24) return `${diffHours} hours ago`;
      if (diffDays === 1) return t('messages:yesterday', 'Yesterday');
      if (diffDays < 7) return `${diffDays} days ago`;
      return lastSeenTime.toLocaleDateString();
    } catch {
      return t('messages:recently', 'Recently');
    }
  };

  const fetchChats = useCallback(async (isInitial = false) => {
    const resolveLastMessage = (chat) => {
      const latestFromArray = Array.isArray(chat?.messages) && chat.messages.length > 0
        ? chat.messages[chat.messages.length - 1]
        : null;
      return (
        chat?.lastMessage?.content ||
        chat?.lastMessage?.message ||
        chat?.lastMessage?.text ||
        latestFromArray?.content ||
        latestFromArray?.message ||
        latestFromArray?.text ||
        t('messages:noMessages', 'No messages yet')
      );
    };

    try {
      if (isInitial) {
        setInitialLoading(true);
      } else {
        setRefreshing(true);
      }
      setLoading(true);
      setError(null);

      const token = await AsyncStorage.getItem('token') || await AsyncStorage.getItem('accessToken');
      if (!token) {
        setCounselors([]);
        setLoading(false);
        setInitialLoading(false);
        setRefreshing(false);
        return;
      }

      const response = await axios.get(`${API_BASE_URL}/api/chat/chats`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      const chatsArray =
        response.data?.chats ||
        response.data?.data?.chats ||
        (Array.isArray(response.data) ? response.data : []);

      if (response.status === 200 && Array.isArray(chatsArray)) {
        const counselorList = chatsArray.map((chat) => {
          const otherParty = chat.otherParty || {};
          const lastMessage = resolveLastMessage(chat);
          const lastMessageTime = chat.lastMessage?.createdAt || chat.updatedAt || chat.startedAt;

          let specialization = 'Counselor';
          if (otherParty.specialization) {
            if (Array.isArray(otherParty.specialization) && otherParty.specialization.length > 0) {
              specialization = otherParty.specialization[0];
            } else if (typeof otherParty.specialization === 'string') {
              specialization = otherParty.specialization;
            }
          }

          return {
            id: otherParty.id || chat.chatId,
            chatMongoId: chat.id || chat._id || null,
            name: otherParty.name || 'Unknown Counselor',
            fullName: otherParty.name || 'Unknown Counselor',
            lastMessage,
            lastMessageTime,
            time: formatTime(lastMessageTime),
            fullDateTime: formatFullDateTime(lastMessageTime),
            unread: chat.unreadCount || 0,
            online: resolveOnlineStatus(otherParty),
            lastSeen: otherParty.lastSeen || null,
            avatar: toImageUri(otherParty.profilePhoto) || toImageUri(otherParty.avatar),
            specialization,
            chatId: chat.chatId,
            status: chat.status,
            isExpired: chat.isExpired,
            profilePhoto: otherParty.profilePhoto,
            phoneNumber: otherParty.phoneNumber,
          };
        });

        counselorList.sort((a, b) => {
          const timeA = a.lastMessageTime ? new Date(a.lastMessageTime).getTime() : 0;
          const timeB = b.lastMessageTime ? new Date(b.lastMessageTime).getTime() : 0;
          return timeB - timeA;
        });

        setCounselors(counselorList);

        try {
          await AsyncStorage.setItem('activeChats', JSON.stringify(chatsArray));
        } catch (storageError) {
          console.warn('Could not cache active chats:', storageError);
        }
      } else {
        setCounselors([]);
      }
    } catch (error) {
      console.error('Error fetching chats:', error);
      setError(error.message);

      try {
        const savedChats = JSON.parse(await AsyncStorage.getItem('activeChats') || '[]');
        if (Array.isArray(savedChats) && savedChats.length > 0) {
          const counselorList = savedChats.map((chat) => {
            const otherParty = chat.otherParty || {};
            const lastMessage = resolveLastMessage(chat);
            const lastMessageTime = chat.lastMessage?.createdAt || chat.updatedAt || chat.startedAt;
            const specialization = Array.isArray(otherParty.specialization)
              ? otherParty.specialization[0] || 'Counselor'
              : otherParty.specialization || 'Counselor';

            return {
              id: otherParty.id || otherParty._id || chat.chatId,
              chatMongoId: chat.id || chat._id || null,
              name: otherParty.name || otherParty.fullName || 'Unknown Counselor',
              fullName: otherParty.name || otherParty.fullName || 'Unknown Counselor',
              lastMessage,
              lastMessageTime,
              time: formatTime(lastMessageTime),
              fullDateTime: formatFullDateTime(lastMessageTime),
              unread: chat.unreadCount || 0,
              online: resolveOnlineStatus(otherParty),
              lastSeen: otherParty.lastSeen || null,
              avatar: toImageUri(otherParty.profilePhoto) || toImageUri(otherParty.avatar),
              specialization,
              chatId: chat.chatId,
              status: chat.status,
              isExpired: chat.isExpired,
              profilePhoto: otherParty.profilePhoto,
              phoneNumber: otherParty.phoneNumber,
            };
          });
          setCounselors(counselorList);
        }
      } catch (storageError) {
        console.warn('Could not load cached chats:', storageError);
      }
    } finally {
      setLoading(false);
      setInitialLoading(false);
      setRefreshing(false);
    }
  }, []);

  const markChatAsRead = useCallback(async (chatIdentifier) => {
    try {
      const token = await AsyncStorage.getItem('token') || await AsyncStorage.getItem('accessToken');
      if (!token) return;
      await axios.post(
        `${API_BASE_URL}/api/chat/mark-all-read`,
        { chatId: chatIdentifier },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setCounselors((prev) => prev.map((c) => ((c.chatId === chatIdentifier || String(c.id) === String(chatIdentifier)) ? { ...c, unread: 0 } : c)));
    } catch (error) {
      console.error('Error marking chat as read:', error);
    }
  }, []);

  const deleteChat = useCallback(async (chatId) => {
    try {
      const token = await AsyncStorage.getItem('token') || await AsyncStorage.getItem('accessToken');
      if (!token) return false;
      const response = await axios.delete(`${API_BASE_URL}/api/chat/chat/${chatId}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (response.status === 200 || response.status === 204) {
        setCounselors((prev) => prev.filter((c) => c.id !== chatId && c.chatId !== chatId));
        if (Platform.OS === 'android') {
          Vibration.vibrate(50);
        }
        return true;
      }
      return false;
    } catch (error) {
      console.error('Error deleting chat:', error);
      return false;
    }
  }, []);

  useEffect(() => {
    fetchChats(true);
    const interval = setInterval(() => fetchChats(false), 30000);
    return () => clearInterval(interval);
  }, [fetchChats]);

  useEffect(() => {
    const setupSocket = async () => {
      const unsubscribers = [];
      try {
        const token = await AsyncStorage.getItem('accessToken') || await AsyncStorage.getItem('token');
        if (!token) return;

        const socket = await socketService.connect();
        socketRef.current = socket;

        unsubscribers.push(await socketService.on('presence-update', ({ userId, isOnline, lastSeen }) => {
          setCounselors((prev) => prev.map((counselor) => (
            String(counselor.id) === String(userId)
              ? { ...counselor, online: !!isOnline, lastSeen: lastSeen || counselor.lastSeen || null }
              : counselor
          )));
        }));

        unsubscribers.push(await socketService.on('chat-list-update', () => {
          fetchChats(false);
        }));
        unsubscribers.push(await socketService.on('disconnect', () => { socketRef.current = null; }));
        socketRef.current._unsubscribers = unsubscribers;
      } catch (error) {
        console.error('Chat interface presence socket error:', error);
      }
    };

    setupSocket();

    return () => {
      try {
        const unsub = socketRef.current?._unsubscribers || [];
        unsub.forEach(fn => { try { fn(); } catch {} });
      } catch (e) {}
      socketRef.current = null;
    };
  }, [fetchChats]);

  useFocusEffect(
    useCallback(() => {
      fetchChats(false);
    }, [fetchChats])
  );

  const handleCounselorSelect = useCallback(async (counselor) => {
    await markChatAsRead(counselor.chatId || counselor.id);
    safeVibrate(80);
    navigation.navigate('ChatBox', {
      id: counselor.id,
      chatId: counselor.chatId,
      chatMongoId: counselor.chatMongoId,
      counselor: {
        id: counselor.id,
        name: counselor.name,
        fullName: counselor.name,
        specialization: counselor.specialization,
        online: counselor.online,
        lastSeen: counselor.lastSeen,
        avatar: counselor.avatar,
        profilePhoto: counselor.profilePhoto,
        phoneNumber: counselor.phoneNumber,
      },
    });
  }, [markChatAsRead, navigation]);

  const handleStartNewChat = useCallback(() => {
    safeVibrate(100);
    if (setActiveTab) {
      setActiveTab('Counselor');
    } else {
      navigation.navigate('CounselorDirectory');
    }
  }, [setActiveTab, navigation]);

  const fetchNearbyCounselors = useCallback(async () => {
    try {
      setNearbyLoading(true);
      const summary = await getCachedLocationSummary();
      const locationLabel = formatLocationLabel(summary);
      setUserLocationLabel(locationLabel);
      if (!summary || !locationLabel) {
        setNearbyCounselors([]);
        return;
      }

      const response = await axios.get(`${API_BASE_URL}/api/chat/counselors`);
      const list = response.data?.counselors || response.data?.counsellors || (Array.isArray(response.data) ? response.data : []);
      const locationTerms = [summary.city, summary.state, summary.address]
        .filter(Boolean)
        .flatMap((value) => String(value).toLowerCase().split(',').map((part) => part.trim()))
        .filter((value) => value.length >= 3);

      const nearby = list
        .filter((person) => {
          const location = String(person.location || person.address || '').toLowerCase();
          return person.profileCompleted === true && location && locationTerms.some((term) => location.includes(term));
        })
        .map((person) => ({
          id: person._id || person.id,
          name: person.fullName || person.name || 'Consultant',
          specialization: Array.isArray(person.specialization) ? person.specialization.join(', ') : person.specialization || 'Mental health consultant',
          lastMessage: `Nearby · ${person.location || person.address}`,
          time: '',
          unread: 0,
          online: resolveOnlineStatus(person),
          avatar: toImageUri(person.profilePhoto) || toImageUri(person.avatar),
          profilePhoto: person.profilePhoto,
          location: person.location || person.address,
          isNearbyDiscovery: true,
        }));
      setNearbyCounselors(nearby);
    } catch (nearbyError) {
      console.error('Unable to load nearby consultants:', nearbyError);
      setNearbyCounselors([]);
    } finally {
      setNearbyLoading(false);
    }
  }, []);

  useEffect(() => {
    if (activeFilter === 'nearby') fetchNearbyCounselors();
  }, [activeFilter, fetchNearbyCounselors]);

  const handleLongPressStart = useCallback((counselor) => {
    pressedItemId.current = counselor.id;
    Animated.spring(scaleAnim, {
      toValue: 0.95,
      useNativeDriver: true,
      speed: 50,
    }).start();
    longPressTimer.current = setTimeout(() => {
      if (pressedItemId.current === counselor.id) {
        if (Platform.OS === 'android') {
          Vibration.vibrate(50);
        }
        setSelectedCounselor(counselor);
        setShowDeleteConfirm(true);
        Animated.spring(scaleAnim, {
          toValue: 1,
          useNativeDriver: true,
          speed: 50,
        }).start();
      }
    }, 500);
  }, [scaleAnim]);

  const handleLongPressEnd = useCallback(() => {
    if (longPressTimer.current) {
      clearTimeout(longPressTimer.current);
      longPressTimer.current = null;
    }
    pressedItemId.current = null;
    Animated.spring(scaleAnim, {
      toValue: 1,
      useNativeDriver: true,
      speed: 50,
    }).start();
  }, [scaleAnim]);

  const handleItemPress = useCallback((counselor) => {
    if (longPressTimer.current) {
      clearTimeout(longPressTimer.current);
      longPressTimer.current = null;
    }
    handleCounselorSelect(counselor);
  }, [handleCounselorSelect]);

  const confirmDeleteChat = useCallback(async () => {
    if (selectedCounselor) {
      const success = await deleteChat(
        selectedCounselor.chatMongoId || selectedCounselor.chatId
      );
      if (success && Platform.OS === 'android') {
        Vibration.vibrate([50, 30, 50]);
      }
      setShowDeleteConfirm(false);
      setSelectedCounselor(null);
    }
  }, [selectedCounselor, deleteChat]);

  // Only status chips are shown here; specialties remain searchable.
  const filterChips = useMemo(() => {
    return [
      { id: 'all', label: t('common:all', 'All') },
      { id: 'online', label: t('common:online', 'Online') },
      { id: 'offline', label: t('common:offline', 'Offline') },
      { id: 'nearby', label: t('common:nearby', 'Nearby') },
    ];
  }, [t]);

  const filteredCounselors = useMemo(() => {
    const term = searchTerm.trim().toLowerCase();
    const source = activeFilter === 'nearby' ? nearbyCounselors : counselors;
    return source.filter((counselor) => {
      const matchesSearch =
        !term ||
        String(counselor.name || '').toLowerCase().includes(term) ||
        String(counselor.specialization || '').toLowerCase().includes(term) ||
        String(counselor.lastMessage || '').toLowerCase().includes(term) ||
        (counselor.online ? 'online available' : 'offline unavailable').includes(term);
      if (!matchesSearch) return false;

      if (activeFilter === 'all') return true;
      if (activeFilter === 'online') return !!counselor.online;
      if (activeFilter === 'offline') return !counselor.online;
      if (activeFilter === 'nearby') return true;
      return true;
    });
  }, [counselors, nearbyCounselors, searchTerm, activeFilter]);

  const renderAvatar = (counselor) => {
    // `?.url` alone missed Cloudinary objects that only carry `secure_url`, and
    // plain string URLs, so counselors with a photo still showed initials.
    const avatarUrl = toImageUri(counselor.profilePhoto) || toImageUri(counselor.avatar);
    if (avatarUrl) {
      return (
        <Image
          source={{ uri: avatarUrl }}
          style={styles.avatarImage}
        />
      );
    }
    return (
      <View style={[styles.avatarInitials, { backgroundColor: getAvatarColor(counselor.name) }]}>
        <Text style={styles.avatarInitialsText}>{getInitials(counselor.name)}</Text>
      </View>
    );
  };

  const renderChatItem = ({ item }) => {
    const animatedStyle = {
      transform: [{ scale: pressedItemId.current === item.id ? scaleAnim : 1 }],
    };
    // Press feedback is a background tint, never an opacity fade: fading the
    // parent of an elevated, rounded card makes Android draw the card's
    // shadow as a hard rectangle inside it while the press lasts.
    return (
      <Pressable
        onPress={() => item.isNearbyDiscovery
          ? (onOpenCounselor ? onOpenCounselor(item.name) : handleStartNewChat())
          : handleItemPress(item)}
        onLongPress={item.isNearbyDiscovery ? undefined : () => handleLongPressStart(item)}
        onPressOut={handleLongPressEnd}
        delayLongPress={500}
      >
        {({ pressed }) => (
        <Animated.View style={[styles.chatItem, pressed && styles.chatItemPressed, animatedStyle]}>
          <View style={styles.avatarContainer}>
            <View style={styles.avatarWrapper}>
              {renderAvatar(item)}
            </View>
            {/* Always show presence: green when online, gray when offline. */}
            <View style={[styles.statusDot, !item.online && styles.statusDotOffline]} />
          </View>
          <View style={styles.chatInfo}>
            <Text style={styles.chatName} numberOfLines={1}>
              {item.name}
            </Text>
            <Text style={styles.specialization} numberOfLines={1}>
              {item.specialization}
            </Text>
            <Text style={styles.lastMessage} numberOfLines={1}>
              {item.lastMessage}
            </Text>
            {item.isExpired && (
              <View style={styles.metaContainer}>
                <View style={styles.expiredBadge}>
                  <Ionicons name="time-outline" size={14} color="#f59e0b" />
                  <Text style={styles.expiredText}>{t('messages:expired', 'Expired')}</Text>
                </View>
              </View>
            )}
          </View>
          <View style={styles.chatRight}>
            <Text style={[styles.chatTime, item.unread > 0 && styles.chatTimeUnread]}>
              {item.time}
            </Text>
            {item.unread > 0 && (
              <View style={styles.unreadBadge}>
                <Text style={styles.unreadBadgeText}>
                  {item.unread > 99 ? '99+' : item.unread}
                </Text>
              </View>
            )}
          </View>
        </Animated.View>
        )}
      </Pressable>
    );
  };

  const renderEmptyState = () => {
    if (initialLoading || loading) return null;
    return (
      <View style={[styles.emptyContainer, compactEmptyState && styles.emptyContainerCompact]}>
        {activeFilter === 'nearby' ? (
          <>
            <Ionicons name="location-outline" size={58} color={PATIENT.primary} />
            <Text style={styles.emptyTitle}>
              {userLocationLabel ? 'No nearby consultants found' : 'Your address is not available'}
            </Text>
            <Text style={styles.emptyText}>
              {userLocationLabel
                ? `No completed consultant profiles currently match ${userLocationLabel}.`
                : 'Add or refresh your address from your profile to discover nearby consultants and doctors.'}
            </Text>
            <PatientGradientButton style={styles.startButton} contentStyle={styles.startButtonContent} onPress={handleStartNewChat}>
              <Ionicons name="people-outline" size={17} color="#ffffff" />
              <Text style={styles.startButtonText}>Browse all consultants</Text>
            </PatientGradientButton>
          </>
        ) : searchTerm ? (
          <>
            <Ionicons name="search-outline" size={64} color="#cbd5e1" />
            <Text style={styles.emptyTitle}>{t('messages:noCounselorsFound', 'No consultants found')}</Text>
            <Text style={styles.emptyText}>
              {t('messages:noCounselorsMatching', 'No consultants matching "{{term}}"', { term: searchTerm })}
            </Text>
            <TouchableOpacity style={styles.clearButton} onPress={() => setSearchTerm('')}>
              <Text style={styles.clearButtonText}>{t('messages:clearSearch', 'Clear search')}</Text>
            </TouchableOpacity>
          </>
        ) : (
          <>
            <View style={[styles.emptyIconWrap, compactEmptyState && styles.emptyIconWrapCompact]}>
              <LinearGradient
                colors={['#DDF8E7', '#F0FFF5']}
                start={{ x: 0, y: 0 }}
                end={{ x: 1, y: 1 }}
                style={styles.emptyIconGradient}
              >
                <Ionicons
                  name="chatbubbles-outline"
                  size={compactEmptyState ? 30 : 36}
                  color={PATIENT.primary}
                />
              </LinearGradient>
              <View style={styles.emptyIconSparkle}>
                <Ionicons name="sparkles" size={12} color="#ffffff" />
              </View>
            </View>
            <Text style={styles.emptyEyebrow}>{t('messages:welcomeSafeSpace', 'YOUR SAFE SPACE')}</Text>
            <Text style={styles.emptyTitle}>{t('messages:newUserChatTitle', 'Find someone who understands')}</Text>
            <Text style={styles.emptyText}>
              {t('messages:newUserChatSubtitle', 'Explore consultant profiles and choose who feels right for you.')}
            </Text>

            <View style={styles.emptyBenefits}>
              <View style={styles.emptyBenefit}>
                <Ionicons name="lock-closed-outline" size={15} color={PATIENT.primary} />
                <Text style={styles.emptyBenefitText}>{t('messages:private', 'Private')}</Text>
              </View>
              <View style={styles.emptyBenefitDivider} />
              <View style={styles.emptyBenefit}>
                <Ionicons name="shield-checkmark-outline" size={16} color={PATIENT.primary} />
                <Text style={styles.emptyBenefitText}>{t('messages:trusted', 'Trusted')}</Text>
              </View>
              <View style={styles.emptyBenefitDivider} />
              <View style={styles.emptyBenefit}>
                <Ionicons name="heart-outline" size={16} color={PATIENT.primary} />
                <Text style={styles.emptyBenefitText}>{t('messages:yourChoice', 'Your choice')}</Text>
              </View>
            </View>

            <PatientGradientButton
              style={styles.startButton}
              contentStyle={styles.startButtonContent}
              onPress={handleStartNewChat}
            >
              <Ionicons name="people-outline" size={17} color="#ffffff" />
              <Text style={styles.startButtonText}>{t('messages:findCounselor', 'Find a consultant')}</Text>
              <Ionicons name="arrow-forward" size={16} color="#ffffff" />
            </PatientGradientButton>
            <Text style={styles.emptyReassurance}>
              {t('messages:browseFirst', 'Review profiles before you decide')}
            </Text>
          </>
        )}
      </View>
    );
  };

  const renderErrorState = () => {
    if (!error || loading || initialLoading) return null;
    return (
      <View style={styles.errorContainer}>
        <Ionicons name="alert-circle-outline" size={48} color="#ef4444" />
        <Text style={styles.errorText}>{error}</Text>
        <TouchableOpacity style={styles.retryButton} onPress={() => fetchChats(false)}>
          <Text style={styles.retryButtonText}>{t('common:retry', 'Retry')}</Text>
        </TouchableOpacity>
      </View>
    );
  };

  return (
    <SafeAreaView style={styles.container} edges={['top', 'left', 'right']}>
      <StatusBar barStyle="dark-content" backgroundColor={PATIENT.backgroundTint} />
      <View style={styles.header}>
        <View style={styles.searchContainer}>
          <Ionicons name="search" size={18} color={PATIENT.textMuted} style={styles.searchIcon} />
          <TextInput
            style={styles.searchInput}
            placeholder={t('messages:searchCounselors', 'Search consultants...')}
            placeholderTextColor={PATIENT.textMuted}
            value={searchTerm}
            onChangeText={setSearchTerm}
            returnKeyType="search"
            autoCorrect={false}
            autoCapitalize="none"
          />
          {searchTerm.length > 0 && (
            <TouchableOpacity style={styles.searchClearButton} onPress={() => setSearchTerm('')} activeOpacity={0.7}>
              <Ionicons name="close-circle" size={16} color={PATIENT.textMuted} />
            </TouchableOpacity>
          )}
        </View>

        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          contentContainerStyle={styles.chipRow}
        >
          {filterChips.map((chip) => {
            const active = activeFilter === chip.id;
            // Both states render the same tree with the same metrics - only the
            // gradient stops and text colour change. Branching the structure (or
            // the font weight) resized the pill on tap, which shifted the whole
            // row and pushed the last chip out of the scroll view.
            return (
              <TouchableOpacity
                key={chip.id}
                onPress={() => setActiveFilter(chip.id)}
                activeOpacity={0.8}
                style={styles.chipWrap}
              >
                <LinearGradient
                  colors={active ? WALLET_GRADIENT : TRANSPARENT_GRADIENT}
                  start={GRADIENT_START}
                  end={GRADIENT_END}
                  style={[styles.chip, active && styles.chipActive]}
                >
                  <Text style={[styles.chipText, active && styles.chipTextActive]} numberOfLines={1}>
                    {chip.label}
                  </Text>
                </LinearGradient>
              </TouchableOpacity>
            );
          })}
        </ScrollView>
      </View>
      {activeFilter === 'nearby' && nearbyLoading ? (
        <ChatListSkeleton />
      ) : initialLoading ? (
        <ChatListSkeleton />
      ) : error && !loading ? (
        renderErrorState()
      ) : (
        <FlatList
          style={styles.chatList}
          data={filteredCounselors}
          keyExtractor={(item) => (item.chatId ? String(item.chatId) : item.id?.toString())}
          renderItem={renderChatItem}
          showsVerticalScrollIndicator={false}
          contentContainerStyle={filteredCounselors.length === 0 ? styles.listEmpty : styles.list}
          ListHeaderComponent={
            filteredCounselors.length > 0 ? (
              <Text style={styles.sectionTitle}>
                {activeFilter === 'nearby'
                  ? `${t('common:nearby', 'Nearby')} · ${userLocationLabel}`
                  : t('messages:recentConversations', 'Recent Conversations')}
              </Text>
            ) : null
          }
          refreshControl={
            <RefreshControl
              refreshing={refreshing}
              onRefresh={() => fetchChats(false)}
              tintColor={PATIENT.primary}
              colors={[PATIENT.primary]}
            />
          }
          ListEmptyComponent={renderEmptyState}
        />
      )}
      <Modal
        visible={showDeleteConfirm}
        transparent={true}
        animationType="fade"
        onRequestClose={() => setShowDeleteConfirm(false)}
      >
        <TouchableOpacity style={styles.modalOverlay} activeOpacity={1} onPress={() => setShowDeleteConfirm(false)}>
          <View style={styles.modalContainer}>
            <View style={styles.modalHeader}>
              <Text style={styles.modalTitle}>{t('messages:deleteChat', 'Delete Chat')}</Text>
            </View>
            {selectedCounselor && (
              <View style={styles.modalBody}>
                <View style={styles.deleteCounselorInfo}>
                  <View style={styles.deleteAvatar}>
                    {renderAvatar(selectedCounselor)}
                  </View>
                  <View style={styles.deleteInfo}>
                    <Text style={styles.deleteName}>{t(selectedCounselor.name)}</Text>
                    <Text style={styles.deleteSpecialization}>
                      {selectedCounselor.specialization}
                    </Text>
                  </View>
                </View>
                <Text style={styles.deleteMessage}>
                  {t('messages:deleteChatConfirm', 'Are you sure you want to delete this chat?')}
                </Text>
                <Text style={styles.deleteWarning}>
                  {t('messages:deleteChatWarning', 'This removes the current history from your view. New messages will restore the conversation.')}
                </Text>
                {selectedCounselor.fullDateTime && (
                  <Text style={styles.chatTimeInfo}>
                    {t('messages:lastMessageLabel', 'Last message')}: {selectedCounselor.fullDateTime}
                  </Text>
                )}
              </View>
            )}
            <View style={styles.modalFooter}>
              <TouchableOpacity
                style={[styles.modalButton, styles.cancelButton]}
                onPress={() => setShowDeleteConfirm(false)}
              >
                <Text style={styles.cancelButtonText}>{t('common:cancel', 'Cancel')}</Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={[styles.modalButton, styles.deleteButton]}
                onPress={confirmDeleteChat}
              >
                <Text style={styles.deleteButtonText}>{t('messages:deleteChat', 'Delete Chat')}</Text>
              </TouchableOpacity>
            </View>
          </View>
        </TouchableOpacity>
      </Modal>
    </SafeAreaView>
  );
};

