const normalizeCallType = (value) => {
  const type = String(value || '').trim().toLowerCase();
  if (type === 'audio' || type === 'voice' || type.includes('audio') || type.includes('voice')) {
    return 'voice';
  }
  return 'video';
};

const TERMINAL_CALL_STATUSES = new Set([
  'ended',
  'rejected',
  'missed',
  'completed',
  'cancelled',
  'canceled',
  'expired',
  'timeout',
  'timed_out',
  'no_answer',
]);

const getCallStatus = (payload) => String(
  payload?.call?.status ||
  payload?.status ||
  payload?.data?.status ||
  ''
).trim().toLowerCase();

const getStreamRoomId = (...sources) => {
  for (const source of sources) {
    const roomId =
      source?.streamCallId ||
      source?.stream_call_id ||
      source?.streamId ||
      source?.roomId ||
      source?.room_id ||
      source?.channelId ||
      source?.call?.streamCallId ||
      source?.call?.roomId ||
      source?.data?.streamCallId ||
      source?.data?.roomId ||
      source?.callData?.streamCallId ||
      source?.callData?.roomId;
    if (roomId) return roomId;
  }
  return '';
};

