          <Text style={sessStyles.patientName} numberOfLines={1}>{patientName}</Text>
          <Text style={sessStyles.patientType} numberOfLines={1}>{sessionType}</Text>
        </View>
      </View>

      {/* Primary action */}
      {inProgress ? (
        <TouchableOpacity
          style={sessStyles.conductBtn}
          onPress={() => onVideoCall(apt)}
          activeOpacity={0.9}
        >
