import { useMemo as useResponsiveStylesMemo } from 'react';
import { useWindowDimensions as useResponsiveWindowDimensions } from 'react-native';
// CounselorProfile.jsx - Modern Full Width Design
import React, { useState, useEffect, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import {
  View,
  ScrollView,
  TouchableOpacity,
  Image,
  ActivityIndicator,
  Alert,
  StyleSheet,
  Platform,
  KeyboardAvoidingView,
    Animated,
} from 'react-native';
import TextInput from '../../../../../../components/TranslatedTextInput';
import Text from '../../../../../../components/TranslatedText';
import useLanguageRender from '../../../../../../hooks/useLanguageRender';
import useKeyboardAwareScroll from '../../../../../../hooks/useKeyboardAwareScroll';
import TranslatedMessageBubble from '../../../../../../components/TranslatedMessageBubble';
import axios from 'axios';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { launchImageLibrary } from 'react-native-image-picker';
import { pick } from '@react-native-documents/picker';
import DateTimePicker from '@react-native-community/datetimepicker';
import Icon from 'react-native-vector-icons/MaterialIcons';
import LinearGradient from 'react-native-linear-gradient';
import { useNavigation } from '@react-navigation/native';
import safeVibrate from '../../../../../../utils/safeVibrate';
import { API_BASE_URL } from '../../../../../../axiosConfig';
import { getCounselorRating } from '../../../../../../services/ratingService';
import { isPsychiatristSpecialization } from '../../../../../../components/common/PsychiatristDirectory';
import CountryPhoneInput from '../../../../../../components/common/CountryPhoneInput';
import { useToast } from '../../../../../../components/common/ToastProvider';
import { DOCTOR } from '../../../../../../theme/palette';
import toImageUri from '../../../../../../utils/imageUri';
import {
  getPhoneLengthLabel,
  isValidLocalPhoneNumber,
  normalizeLocalPhoneNumber,
  splitInternationalPhoneNumber,
} from '../../../../../../utils/countryCodes';
import {
  calculateAgeFromDateOfBirth,
  formatDateOfBirthDisplay,
  getDatePickerValue,
  toDateOnlyString,
} from '../../../../../../utils/dateOfBirth';



// Document upload specifications (same as web)
const MAX_CERTIFICATION_DOCUMENTS = 5;
const VERIFICATION_DOCUMENT_OPTIONS = [
  'Medical / Professional Registration Certificate',
  'Degree or Qualification Certificate',
  'Internship / Training Completion Certificate',
  'Government ID Proof',
  'Clinic / Hospital Affiliation Proof'
];
const ALLOWED_DOCUMENT_TYPES = ['application/pdf', 'application/msword', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'image/jpeg', 'image/jpg', 'image/png'];
const DATE_PICKER_FIELDS = {
  issueDate: 'issueDate',
  expiryDate: 'expiryDate',
};

const createBlankEmailChange = () => ({
  sending: false,
  sent: false,
  verifying: false,
  verified: false,
  sentValue: null,
  verifiedValue: null,
  otp: '',
  error: '',
});

const normalizeGender = (value) => {
  if (!value) return '';
  const v = String(value).trim().toLowerCase();
  if (v === 'm' || v === 'male') return 'male';
  if (v === 'f' || v === 'female') return 'female';
  if (v === 'o' || v === 'other') return 'other';
  return v;
};

const SESSION_VALIDATION_PATH = `${API_BASE_URL}/api/auth/me`;

const parseStoredJson = async (key) => {
  try {
    const raw = await AsyncStorage.getItem(key);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
};

const readCounsellorId = (profile, allowDocumentId = true) =>
  String(
    profile?.counsellorId ||
      profile?.counselorId ||
      profile?.counsellorProfileId ||
      profile?.counselorProfileId ||
      (allowDocumentId ? profile?._id || profile?.id : '') ||
      '',
  ).trim();

const getStoredCounsellorId = async () => {
  const directId =
    (await AsyncStorage.getItem('counsellorId')) ||
    (await AsyncStorage.getItem('counselorId'));

  if (directId) return directId;

  const storedProfile =
    (await parseStoredJson('counselor')) ||
    (await parseStoredJson('counsellor'));
  const storedProfileId = readCounsellorId(storedProfile);
  if (storedProfileId) {
    await Promise.all([
      AsyncStorage.setItem('counsellorId', storedProfileId),
      AsyncStorage.setItem('counselorId', storedProfileId),
    ]);
    return storedProfileId;
  }

  const storedUserProfile =
    (await parseStoredJson('userData')) ||
    (await parseStoredJson('user'));
  const storedUserCounsellorId = readCounsellorId(storedUserProfile, false);
  if (storedUserCounsellorId) {
    await Promise.all([
      AsyncStorage.setItem('counsellorId', storedUserCounsellorId),
      AsyncStorage.setItem('counselorId', storedUserCounsellorId),
    ]);
    return storedUserCounsellorId;
  }

  return '';
};

const extractCounselorProfile = (raw = {}) => {
  const candidates = [
    raw?.counsellor,
    raw?.counselor,
    raw?.profile,
    raw?.data?.counsellor,
    raw?.data?.counselor,
    raw?.data?.profile,
    raw?.data?.user?.counsellor,
    raw?.data?.user?.counselor,
    raw?.user?.counsellor,
    raw?.user?.counselor,
    raw?.user,
    raw?.data,
    raw,
  ];

  return (
    candidates.find(candidate => {
      if (!candidate || typeof candidate !== 'object') return false;
      return Boolean(
        candidate.counsellorId ||
          candidate.counselorId ||
          candidate.counsellorProfileId ||
          candidate.counselorProfileId ||
          candidate.specialization ||
          candidate.consultationMode ||
          candidate.qualification ||
          candidate.uniqueCode ||
          candidate.experience ||
          candidate.aboutMe ||
          candidate.role === 'counsellor' ||
          candidate.role === 'counselor',
      );
    }) || null
  );
};

const extractCounselorList = (raw = {}) => {
  const candidates = [
    raw?.counsellors,
    raw?.counselors,
    raw?.data?.counsellors,
    raw?.data?.counselors,
    raw?.data,
    raw,
  ];

  return candidates.find(Array.isArray) || [];
};

const normalizeArrayField = (value) => {
  if (Array.isArray(value)) {
    return value.map(item => String(item || '').trim()).filter(Boolean);
  }

  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      if (Array.isArray(parsed)) return normalizeArrayField(parsed);
    } catch {
      return value
        .split(',')
        .map(item => item.trim())
        .filter(Boolean);
    }
  }

  return [];
};

const resolveAssetUrl = (asset) => {
  const imageUri = toImageUri(asset);
  const candidate =
    imageUri ||
    (typeof asset === 'string'
      ? asset
      : asset?.secure_url || asset?.url || asset?.uri || asset?.path || '');

  if (!candidate) return '';
  if (/^(https?:|file:|content:|data:)/i.test(candidate)) return candidate;

  const baseUrl = API_BASE_URL.endsWith('/')
    ? API_BASE_URL.slice(0, -1)
    : API_BASE_URL;
  const assetPath = candidate.startsWith('/') ? candidate : `/${candidate}`;
  return `${baseUrl}${assetPath}`;
};

