      if (!userData) {
        const storedProfile =
          (await parseStoredJson('counselor')) ||
          (await parseStoredJson('counsellor')) ||
          extractCounselorProfile(await parseStoredJson('userData')) ||
          extractCounselorProfile(await parseStoredJson('user'));
        if (storedProfile) {
