  const handleInputChange = (field, value) => {
    if (field === 'dateOfBirth') {
      const dateOfBirth = toDateOnlyString(value);
      const calculatedAge = calculateAgeFromDateOfBirth(dateOfBirth);
      setEditedData(prev => ({
        ...prev,
        dateOfBirth,
        age: calculatedAge !== null ? calculatedAge : '',
      }));
      return;
    }

    setEditedData(prev => ({ ...prev, [field]: value }));
  };

  const handleDateOfBirthChange = (_event, selectedDate) => {
    if (Platform.OS === 'android') {
      setShowDateOfBirthPicker(false);
    }
    if (!selectedDate) return;
    handleInputChange('dateOfBirth', selectedDate);
  };

  const handleCertificationDateChange = (_event, selectedDate) => {
    if (Platform.OS === 'android') {
      setCertDatePickerField(null);
    }
    if (!selectedDate || !certDatePickerField) return;
    const field = certDatePickerField;
    setNewCertification(prev => ({
      ...prev,
      [field]: toDateOnlyString(selectedDate),
    }));
  };

  const handleTabPress = (tabKey) => {
    if (activeTab === tabKey) return;
    safeVibrate(80);
    setActiveTab(tabKey);
  };

  const handleNestedInputChange = (parentField, field, value) => {
    setEditedData(prev => ({
      ...prev,
      [parentField]: { ...prev[parentField], [field]: value }
    }));
  };

  const handleProfilePhotoUpload = async () => {
    const options = {
      mediaType: 'photo',
      includeBase64: false,
      quality: 0.7,
      storageOptions: { skipBackup: true, path: 'images' }
    };

    launchImageLibrary(options, (response) => {
      if (response.didCancel) {
        return;
      }

      if (response.errorCode) {
        Alert.alert('Error', 'Failed to pick image. Please try again.');
        return;
      }

      if (response.assets && response.assets[0]) {
        const asset = response.assets[0];

        // Validate file size (max 10MB)
        if (asset.fileSize && asset.fileSize > 10 * 1024 * 1024) {
          Alert.alert('File Too Large', 'Profile photo must be less than 10MB');
          return;
        }

        // Validate file type
        const allowedTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/gif', 'image/webp'];
        if (!allowedTypes.includes(asset.type)) {
          Alert.alert('Invalid Format', 'Only JPG, PNG, GIF, and WEBP images are allowed');
          return;
        }

        // Set the photo
        setEditedData(prev => ({
          ...prev,
          profilePhoto: {
            uri: asset.uri,
            type: asset.type || 'image/jpeg',
            name: asset.fileName || 'profile_photo.jpg'
          },
          profilePhotoUrl: asset.uri
        }));

        Alert.alert('Success', 'Photo selected. It will be uploaded when you save.');
      }
    });
  };

  const handlePrescriptionAssetUpload = (kind) => {
    const isSignature = kind === 'signature';
    const options = {
      mediaType: 'photo',
      includeBase64: false,
      quality: 0.9,
      selectionLimit: 1,
      storageOptions: { skipBackup: true, path: 'images' }
    };

    launchImageLibrary(options, (response) => {
      if (response.didCancel) return;

      if (response.errorCode) {
        Alert.alert('Error', 'Failed to pick image. Please try again.');
        return;
      }

      const asset = response.assets?.[0];
      if (!asset?.uri) {
        Alert.alert('Error', 'Unable to read selected image.');
        return;
      }

      if (asset.fileSize && asset.fileSize > 5 * 1024 * 1024) {
        Alert.alert('File Too Large', 'Signature or seal image must be less than 5MB.');
        return;
      }

      const allowedTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp'];
      if (!allowedTypes.includes(asset.type)) {
        Alert.alert('Invalid Format', 'Only JPG, PNG, and WEBP images are allowed.');
        return;
      }

      const file = {
        uri: asset.uri,
        type: asset.type || 'image/png',
        name: asset.fileName || `${isSignature ? 'signature' : 'seal'}.png`,
      };

      setEditedData(prev => ({
        ...prev,
        [isSignature ? 'prescriptionSignature' : 'prescriptionSeal']: file,
        [isSignature ? 'prescriptionSignatureUrl' : 'prescriptionSealUrl']: asset.uri,
      }));
    });
  };

  const handleAddLanguage = () => {
    if (newLanguage.trim() && !editedData.languages.includes(newLanguage.trim())) {
      setEditedData(prev => ({ ...prev, languages: [...prev.languages, newLanguage.trim()] }));
      setNewLanguage('');
    }
  };

  const handleRemoveLanguage = (lang) => {
    setEditedData(prev => ({ ...prev, languages: prev.languages.filter(l => l !== lang) }));
  };

  const handleAddSpecialization = () => {
    if (newSpecialization.trim() && !editedData.specialization.includes(newSpecialization.trim())) {
      setEditedData(prev => ({ ...prev, specialization: [...prev.specialization, newSpecialization.trim()] }));
      setNewSpecialization('');
    }
  };

  const handleRemoveSpecialization = (spec) => {
    setEditedData(prev => ({ ...prev, specialization: prev.specialization.filter(s => s !== spec) }));
  };

  const handleAddConsultationMode = () => {
    const modes = ['online', 'offline', 'both'];
    if (newConsultationMode && modes.includes(newConsultationMode) && !editedData.consultationMode.includes(newConsultationMode)) {
      setEditedData(prev => ({ ...prev, consultationMode: [...prev.consultationMode, newConsultationMode] }));
      setNewConsultationMode('');
    }
  };

  const handleRemoveConsultationMode = (mode) => {
    setEditedData(prev => ({ ...prev, consultationMode: prev.consultationMode.filter(m => m !== mode) }));
  };

  const handleSelectDocumentType = (documentType) => {
    setNewCertification(prev => ({ ...prev, name: documentType }));
  };

  const handleUploadCertificationDocument = async () => {
    try {
      const [selectedDocument] = await pick();
      if (!selectedDocument?.uri) {
        Alert.alert('Error', 'Unable to read selected document.');
        return;
      }

      const fileName = selectedDocument.name || `verification-document-${Date.now()}`;
      setNewCertification(prev => ({
        ...prev,
        document: {
          uri: selectedDocument.uri,
          type: selectedDocument.type || 'application/octet-stream',
          name: fileName
        },
        documentName: fileName
      }));
    } catch (error) {
      if (error?.code === 'OPERATION_CANCELED') return;
      Alert.alert('Error', 'Unable to pick a document. Please try again.');
    }
  };

  const handleAddCertification = () => {
    if (!newCertification.name.trim()) {
      Alert.alert('Error', 'Please select certificate type');
      return;
    }

    if ((editedData.certifications || []).length >= 5) {
      Alert.alert('Error', 'You can add up to 5 certification documents.');
      return;
    }

    if (!newCertification.document?.uri) {
      Alert.alert('Error', 'Please upload a document before adding this certificate.');
      return;
    }

    if (newCertification.issueDate && newCertification.expiryDate) {
      const issueTime = new Date(newCertification.issueDate).getTime();
      const expiryTime = new Date(newCertification.expiryDate).getTime();
      if (!Number.isNaN(issueTime) && !Number.isNaN(expiryTime) && expiryTime < issueTime) {
        Alert.alert('Invalid Date', 'Expiry date cannot be before issue date.');
        return;
      }
    }

    const newCert = {
      _id: `temp_${Date.now()}`,
      name: newCertification.name,
      document: newCertification.document,
      documentName: newCertification.documentName,
      documentUrl: newCertification.document ? newCertification.document.uri : '',
      issueDate: newCertification.issueDate,
      expiryDate: newCertification.expiryDate,
      issuedBy: newCertification.issuedBy
    };
    setEditedData(prev => ({ ...prev, certifications: [...prev.certifications, newCert] }));
    setNewCertification({ name: '', issueDate: '', expiryDate: '', issuedBy: '', document: null, documentName: '' });
    setCertDatePickerField(null);
  };

  const handleRemoveCertification = (certId) => {
    setEditedData(prev => ({ ...prev, certifications: prev.certifications.filter(cert => cert._id !== certId) }));
  };

  // Document Upload Handlers
  const handleDocumentUpload = async () => {
    if (!selectedDocumentType) {
      Alert.alert('Error', 'Please select a document type');
      return;
    }

    if (documents.length >= MAX_CERTIFICATION_DOCUMENTS) {
      Alert.alert('Limit Reached', `You can upload a maximum of ${MAX_CERTIFICATION_DOCUMENTS} verification documents.`);
      return;
    }

    try {
      const [selectedDocument] = await pick({ type: ALLOWED_DOCUMENT_TYPES });
      if (!selectedDocument?.uri) {
        Alert.alert('Error', 'Unable to read selected document.');
        return;
      }

      const fileType = selectedDocument.type || '';
      if (fileType && !ALLOWED_DOCUMENT_TYPES.includes(fileType)) {
        Alert.alert('Invalid File', 'Only PDF, DOC, DOCX, JPG, and PNG files are allowed.');
        return;
      }

      const newDoc = {
        _id: `doc_${Date.now()}`,
        documentType: selectedDocumentType,
        documentName: selectedDocument.name || 'document',
        uri: selectedDocument.uri,
        type: selectedDocument.type || 'application/octet-stream',
        size: selectedDocument.size
      };

      setDocuments(prev => [...prev, newDoc]);
      setSelectedDocumentType(null);
      showToast({
        title: 'Uploaded',
        message: 'Verification document added. Save profile to submit it.',
        type: 'success',
        accent: DOCTOR.primary,
        bg: '#EFF6FF',
        border: '#BFDBFE',
        icon: 'OK',
        translate: false,
        duration: 2800,
      });
    } catch (err) {
      if (err?.code === 'OPERATION_CANCELED') return;
      Alert.alert('Error', 'Failed to upload document');
    }
  };

  const handleRemoveDocument = (docId) => {
    setDocuments(prev => prev.filter(doc => doc._id !== docId));
  };

  const handleSave = async () => {
    const dateOfBirth = toDateOnlyString(editedData.dateOfBirth);
    const calculatedAge = calculateAgeFromDateOfBirth(dateOfBirth);

    if (dateOfBirth && calculatedAge === null) {
      showErrorPopup('Select a valid date of birth', 'Invalid Date of Birth');
      return;
    }

    const normalizedPhone = normalizeLocalPhoneNumber(
      editedData.phoneNumber || '',
      editedData.phoneCountryCode,
    );
    if (!isValidLocalPhoneNumber(normalizedPhone, editedData.phoneCountryCode)) {
      const expectedLength = getPhoneLengthLabel(editedData.phoneCountryCode);
      showErrorPopup(`Phone number must be ${expectedLength} digits`, 'Invalid Phone Number');
      return;
    }

    if (!emailReady) {
      const msg = emailChange.sent
        ? 'Please enter and confirm the OTP sent to your new email before saving.'
        : 'Please verify your new email before saving.';
      showErrorPopup(msg, 'Email Verification Required');
      return;
    }

    try {
      setLoading(true);
      setError('');
      setSuccessMessage('');

      // NOTE: Verification documents are optional when editing an existing
      // profile. The `documents` list only holds NEW uploads from this session
      // (it isn't hydrated from the server), so requiring it here would block
      // every returning counselor from saving basic profile edits.

      const formData = new FormData();
      formData.append('fullName', editedData.fullName);
      formData.append('email', editedData.email);
      formData.append('phoneNumber', normalizedPhone);
      formData.append('phoneCountryCode', editedData.phoneCountryCode || '+91');
      formData.append('qualification', editedData.qualification || editedData.education);
      formData.append('experience', editedData.experience.toString());
      formData.append('aboutMe', editedData.aboutMe);
      formData.append('education', editedData.education);

      if (dateOfBirth) {
        formData.append('dateOfBirth', dateOfBirth);
        formData.append('age', calculatedAge.toString());
      } else if (editedData.age) {
        formData.append('age', editedData.age.toString());
      }
      if (editedData.gender) formData.append('gender', editedData.gender);
      if (editedData.address) {
        // One JSON field, not address[line1] / address[city] / ... fields.
        // The server's multipart parser turns bracket fields into an object
        // with no prototype, and its profile-completion check runs
        // String(address) on it once experience > 0, which crashed the save
        // with "Cannot convert object to primitive value" (500). The server
        // JSON.parses a string address into a normal object.
        formData.append('address', JSON.stringify({
          line1: editedData.address.line1 || '',
          line2: editedData.address.line2 || '',
          city: editedData.address.city || '',
          state: editedData.address.state || '',
          pincode: editedData.address.pincode || '',
          country: editedData.address.country || 'India',
        }));
      }

      if (editedData.languages && editedData.languages.length > 0) {
        editedData.languages.forEach((lang, index) => formData.append(`languages[${index}]`, lang));
      }
      if (editedData.specialization && editedData.specialization.length > 0) {
        editedData.specialization.forEach((spec, index) => formData.append(`specialization[${index}]`, spec));
      }
      if (editedData.consultationMode && editedData.consultationMode.length > 0) {
        editedData.consultationMode.forEach((mode, index) => formData.append(`consultationMode[${index}]`, mode));
      }
      if (editedData.prescriptionSignatureUrl && !editedData.prescriptionSignature?.uri) {
        formData.append('prescriptionSignatureUrl', editedData.prescriptionSignatureUrl);
      }
      if (editedData.prescriptionSealUrl && !editedData.prescriptionSeal?.uri) {
        formData.append('prescriptionSealUrl', editedData.prescriptionSealUrl);
      }
      if (editedData.prescriptionSignature?.uri) {
        formData.append('prescriptionSignature', {
          uri: editedData.prescriptionSignature.uri,
          type: editedData.prescriptionSignature.type || 'image/png',
          name: editedData.prescriptionSignature.name || 'prescription-signature.png'
        });
      }
      if (editedData.prescriptionSeal?.uri) {
        formData.append('prescriptionSeal', {
          uri: editedData.prescriptionSeal.uri,
          type: editedData.prescriptionSeal.type || 'image/png',
          name: editedData.prescriptionSeal.name || 'prescription-seal.png'
        });
      }

      // Upload photo separately if it exists
      if (editedData.profilePhoto && editedData.profilePhoto.uri) {
        try {
          const photoUri = editedData.profilePhoto.uri;
          const fileName = editedData.profilePhoto.name || 'profile_photo.jpg';
          const mimeType = editedData.profilePhoto.type || 'image/jpeg';

          console.log('Uploading photo:', { photoUri, fileName, mimeType });

          setSuccessMessage('Uploading photo...');
          await uploadProfilePhoto(photoUri, mimeType, fileName);
          console.log('Photo uploaded successfully');
          setSuccessMessage('Photo uploaded successfully!');
          setTimeout(() => setSuccessMessage(''), 3000);
        } catch (photoErr) {
          console.error('Photo upload error:', photoErr);
          const photoErrorMsg = photoErr.message || 'Photo upload failed. Please try again with a different image.';

          // Show specific error for photo
          Alert.alert('Photo Upload Issue', photoErrorMsg);

          // Don't block profile update if photo fails
        }
      }

      // Certifications go field by field, exactly like the web profile
      // (certifications[i][name], [issuedBy], ..., file in [document]).
      // Sending them as one JSON `certifications` string next to
      // `certifications[i][document]` files made the server fail with
      // "Cannot convert object to primitive value".
      //
      // Verification documents are saved as certifications too (name = the
      // document type), as on the web. The server has no
      // `verificationDocuments[...]` field and rejected it with
      // "Unexpected file field: verificationDocuments[0][document]".
      const certificationItems = [
        ...(editedData.certifications || []).filter(cert => cert && (cert._id || cert.name)),
        ...documents
          .filter((doc) => doc?.uri)
          .map((doc) => ({
            name: doc.documentType || 'Verification Document',
            documentName: doc.documentName || '',
            document: { uri: doc.uri, type: doc.type || 'application/octet-stream', name: doc.documentName },
          })),
      ];

      certificationItems.forEach((cert, index) => {
        const key = `certifications[${index}]`;
        formData.append(`${key}[name]`, cert.name || '');
        formData.append(`${key}[issuedBy]`, cert.issuedBy || '');
        if (cert.issueDate) formData.append(`${key}[issueDate]`, String(cert.issueDate));
        if (cert.expiryDate) formData.append(`${key}[expiryDate]`, String(cert.expiryDate));
        if (cert._id && !String(cert._id).startsWith('temp_')) formData.append(`${key}[_id]`, String(cert._id));

        if (cert.document?.uri) {
          formData.append(`${key}[document]`, {
            uri: cert.document.uri,
            type: cert.document.type || 'image/jpeg',
            name: cert.document.name || cert.documentName || `certificate-${index + 1}.jpg`
          });
        } else if (cert.documentUrl) {
          // Already uploaded: keep the stored file.
          formData.append(`${key}[documentUrl]`, cert.documentUrl);
          formData.append(`${key}[documentName]`, cert.documentName || '');
          if (cert.documentPublicId) formData.append(`${key}[documentPublicId]`, cert.documentPublicId);
        }
      });

      const response = await updateCounselorProfile(formData);
      if (response.data.success) {
        showToast({
          title: 'Success',
          message: 'Consultant profile updated successfully!',
          type: 'success',
          accent: '#FFFFFF',
          border: DOCTOR.gradientTo,
          gradientColors: [DOCTOR.gradientFrom, DOCTOR.gradientTo],
          iconBg: 'rgba(255,255,255,0.18)',
          titleColor: '#FFFFFF',
          messageColor: '#EAF4FF',
          icon: 'OK',
          translate: false,
          duration: 3200,
        });
        setEmailChange(createBlankEmailChange());
        // Now stored on the server as certifications; don't upload them again.
        setDocuments([]);
        await fetchCounselorProfile();
        await onProfileSaved?.();
        setShowRemainingAfterSave(true);
        setIsEditing(false);
      } else {
        showErrorPopup(response.data.message || 'Failed to update profile');
      }
    } catch (err) {
      console.error('Error updating profile:', err);

      // Handle specific errors
      let errorMsg = 'Failed to update profile';

      if (err.response?.status === 400) {
        errorMsg = err.response?.data?.message || 'Invalid data. Please check your inputs.';
      } else if (err.response?.status === 413) {
        errorMsg = 'Profile photo is too large. Please use a smaller image.';
      } else if (err.response?.status === 422) {
        errorMsg = 'Please fill in all required fields correctly.';
      } else if (err.message === 'Network Error') {
        errorMsg = 'Network error. Please check your connection and try again.';
      } else if (err.response?.data?.message?.includes('photo')) {
        errorMsg = 'Error uploading photo. Please try again with a different image.';
      } else {
        errorMsg = err.response?.data?.message || err.message || 'Failed to update profile';
      }

      showErrorPopup(errorMsg);
      setTimeout(() => setError(''), 5000);
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = () => {
    setEditedData(counselor);
    setNewLanguage('');
    setNewSpecialization('');
    setNewConsultationMode('');
    setShowDateOfBirthPicker(false);
    setCertDatePickerField(null);
    setNewCertification({ name: '', issueDate: '', expiryDate: '', issuedBy: '', document: null, documentName: '' });
    setEmailChange(createBlankEmailChange());
    setShowRemainingAfterSave(false);
    setIsEditing(false);
    setError('');
    setSuccessMessage('');
  };

  const formatDate = (dateString) => {
    if (!dateString) return t('profile:notSpecified');
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric', month: 'long', day: 'numeric'
    });
  };

  const StarRating = ({ rating, size = 14 }) => {
    const stars = [];
    for (let i = 1; i <= 5; i++) {
      const filled = i <= Math.round(rating);
      stars.push(
        <View key={i} style={{ position: 'relative', width: size + 2, height: size + 2, alignItems: 'center', justifyContent: 'center' }}>
          {filled ? (
            <Icon name="star" size={size} color="#2563EB" />
          ) : (
            <>
              <Icon name="star" size={size} color="#ffffff" />
              <Icon name="star-border" size={size} color="#2563EB" style={{ position: 'absolute' }} />
            </>
          )}
        </View>
      );
    }
    return <View style={styles.starRow}>{stars}</View>;
  };

  if (loading && !counselor._id) {
    return (
      <View style={styles.loadingScreen}>
        <ActivityIndicator size="large" color="#94A3B8" />
        <Text style={styles.loadingText}>{t('profile:loadingYourProfile')}</Text>
      </View>
    );
  }

  return (
    <KeyboardAvoidingView 
      style={styles.container} 
      behavior={Platform.OS === 'ios' ? 'padding' : undefined}
    >
      <ScrollView
        ref={kbScrollRef}
        style={styles.scrollView}
        showsVerticalScrollIndicator={false}
        // Signup-style keyboard handling on Android too (KeyboardAvoidingView
        // above is iOS-only): the form scrolls above the keyboard and the
        // focused field is scrolled into view.
        contentContainerStyle={[
          styles.scrollContent,
          isEditing && styles.scrollContentEditing,
          Platform.OS === 'android' && kbInset > 0 && { paddingBottom: kbInset + 24 },
        ]}
        onScroll={kbOnScroll}
        onLayout={kbOnLayout}
        onFocusCapture={kbFocus}
        scrollEventThrottle={16}
        keyboardShouldPersistTaps="handled"
      >
        {/* FULL WIDTH - NO SIDE SPACING */}
        <View style={styles.fullWidth}>

        {/* Notification Banner - Full Width */}
        {successMessage && (
          <View style={[styles.banner, styles.successBanner]}>
            <Icon name="check-circle" size={20} color="#fff" />
            <Text style={styles.bannerText}>{successMessage}</Text>
          </View>
        )}

        {/* Profile Header — blue gradient card matching the app design */}
        <LinearGradient
          colors={['#003A9B', '#1490FF']}
          start={{ x: 0, y: 0.5 }}
          end={{ x: 1, y: 0.5 }}
          style={styles.heroCard}
        >
          <View style={styles.heroTopRow}>
            <TouchableOpacity
              activeOpacity={isEditing ? 0.7 : 1}
              onPress={isEditing ? handleProfilePhotoUpload : undefined}
            >
              {editedData?.profilePhotoUrl ? (
                <Image source={{ uri: String(editedData.profilePhotoUrl) }} style={styles.heroAvatar} />
              ) : (
                <View style={styles.heroAvatarFallback}>
                  <Text style={styles.heroAvatarText}>
                    {counselor?.fullName?.charAt(0)?.toUpperCase() || 'C'}
                  </Text>
                </View>
              )}
              {isEditing && (
                <View style={styles.heroCamBadge}>
                  <Icon name="camera-alt" size={13} color="#2563EB" />
                </View>
              )}
            </TouchableOpacity>

            <View style={styles.heroInfo}>
              {isEditing ? (
                <TextInput
                  style={styles.heroNameInput}
                  value={editedData.fullName || ''}
                  onChangeText={(value) => handleInputChange('fullName', value)}
                  placeholder="Your Full Name"
                  placeholderTextColor="rgba(255,255,255,0.6)"
                />
              ) : (
                <Text style={styles.heroName} numberOfLines={1}>
                  {counselor.fullName || 'Your Name'}
                </Text>
              )}
              <Text style={styles.heroRole} numberOfLines={1}>
                {counselor.specialization?.[0] || t('counselor:psychologist', 'Psychologist')}
              </Text>
              <Text style={styles.heroEmail} numberOfLines={1}>{counselor.email || ''}</Text>
            </View>

            {!isEditing && (
              <TouchableOpacity onPress={() => setIsEditing(true)} style={styles.heroEditBtn} activeOpacity={0.85}>
                <Icon name="edit" size={12} color="#2563EB" />
                <Text style={styles.heroEditText}>{t('common:edit')}</Text>
              </TouchableOpacity>
            )}
          </View>

          {/* Stats strip */}
          <View style={styles.heroStats}>
            <View style={styles.heroStatItem}>
              <Text style={styles.heroStatNum}>
                {counselor.totalRatings > 0 ? Number(counselor.rating).toFixed(1) : t('counselor:newRating', 'New')}
              </Text>
              <Text style={styles.heroStatLabel}>{t('profile:rating')}</Text>
            </View>
            <View style={styles.heroStatDivider} />
            <View style={styles.heroStatItem}>
              <Text style={styles.heroStatNum}>{sessionsCount ?? '–'}</Text>
              <Text style={styles.heroStatLabel}>{t('profile:sessions')}</Text>
            </View>
            <View style={styles.heroStatDivider} />
            <View style={styles.heroStatItem}>
              <Text style={styles.heroStatNum}>{clientsCount}</Text>
              <Text style={styles.heroStatLabel}>{t('profile:clients')}</Text>
            </View>
            <View style={styles.heroStatDivider} />
            <View style={styles.heroStatItem}>
              <Text style={styles.heroStatNum}>{counselor.experience || 0}y</Text>
              <Text style={styles.heroStatLabel}>{t('profile:experience')}</Text>
            </View>
          </View>
        </LinearGradient>

        {/* Profile Completion Card */}
        {(() => {
          const pct = calcProfileCompletion(counselor);
          if (pct >= 100) return null;
          const barColor = '#2563EB';
          const bgColor = '#EFF6FF';
          const borderColor = '#DBEAFE';
          return (
            <View style={[styles.completionWrap, { backgroundColor: bgColor, borderColor }]}>
              <View style={styles.completionHeader}>
                <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6 }}>
                  <Icon name={pct === 100 ? 'check-circle' : 'person'} size={16} color={barColor} />
                  <Text style={styles.completionLabel}>{t('profile:profileCompletion')}</Text>
                </View>
                <Text style={[styles.completionPct, { color: barColor }]}>{pct}%</Text>
              </View>
              <View style={styles.completionTrack}>
                <Animated.View style={[styles.completionFill, {
                  backgroundColor: barColor,
                  width: progressAnim.interpolate({ inputRange: [0, 1], outputRange: ['0%', '100%'] }),
                }]} />
              </View>
              {pct < 100 && (
                <Text style={styles.completionHint}>
                  {pct < 50 ? 'Add your professional details to get discovered' :
                   pct < 80 ? t('Almost there! Fill remaining fields to appear in search') : t('Just a few fields left to complete your profile')}
                </Text>
              )}
            </View>
          );
        })()}

        {/* All profile content — no tabs */}
        <View style={styles.tabContent}>
          {/* Personal info card - DOB, age, gender, email, phone, address */}
          <View style={styles.card}>
            <View style={styles.sectionHead}>
              <Icon name="person-outline" size={18} color="#004AC6" />
              <Text style={styles.cardTitle}>{t('Personal Information')}</Text>
            </View>
            <View style={styles.detailRow}>
              <Icon name="event" size={18} color="#2563EB" />
              <View style={styles.detailContent}>
                <Text style={styles.detailLabel}>{t('profile:dateOfBirth')}</Text>
                {isEditing ? (
                  <>
                    <TouchableOpacity
                      style={styles.datePickerButton}
                      onPress={() => setShowDateOfBirthPicker(true)}
                      activeOpacity={0.85}
                    >
                      <Icon name="calendar-today" size={18} color="#2563EB" />
                      <Text
                        style={[
                          styles.datePickerText,
                          !editedData.dateOfBirth && styles.datePickerPlaceholder,
                        ]}
                      >
                        {formatDateOfBirthDisplay(
                          editedData.dateOfBirth,
                          'Select date of birth',
                        )}
                      </Text>
                      <Icon name="expand-more" size={20} color="#94A3B8" />
                    </TouchableOpacity>
