                    {missingItems.slice(0, 6).map((item) => (
                      <View key={item} style={styles.remainingItem}>
                        <Icon name="radio-button-unchecked" size={15} color="#2563EB" />
                        <Text style={styles.remainingItemText}>{item}</Text>
                      </View>
                    ))}
                    {missingItems.length > 6 && (
                      <Text style={styles.remainingMoreText}>
                        +{missingItems.length - 6} more
                      </Text>
                    )}
                  </View>
                )}
              </View>
            );
          })()}

        </View>

        {/* Bottom Spacing */}
        <View style={{ height: 40 }} />
        </View>
      </ScrollView>
      {isEditing && (
        <View style={styles.bottomEditActions}>
          <TouchableOpacity onPress={handleCancel} style={styles.bottomCancelBtn} activeOpacity={0.85}>
            <Text style={styles.bottomCancelText}>{t('common:cancel')}</Text>
          </TouchableOpacity>
          <TouchableOpacity
            onPress={handleSave}
            style={[
              styles.bottomSaveBtn,
              (loading || !emailReady) && styles.bottomSaveBtnDisabled,
            ]}
            disabled={loading || !emailReady}
            activeOpacity={0.9}
          >
            {loading ? (
              <ActivityIndicator size="small" color="#ffffff" />
            ) : (
              <>
                <Icon name="check" size={16} color="#ffffff" />
                <Text style={styles.bottomSaveText}>{t('common:save')}</Text>
              </>
            )}
          </TouchableOpacity>
        </View>
      )}
    </KeyboardAvoidingView>
  );
};

