const formatName = (full) => {
  if (!full) return '';
  const trimmed = String(full).trim();
  if (!trimmed) return '';
  return /^(dr\.?|mr\.?|mrs\.?|ms\.?)\s/i.test(trimmed)
    ? trimmed
    : `Dr. ${trimmed}`;
};

const firstName = (full) => {
  const name = formatName(full).replace(/^(dr\.?|mr\.?|mrs\.?|ms\.?)\s+/i, '');
  return name.split(/\s+/)[0] || '';
};

